INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('ADVISOR', 'Advisor', '[H4]Advisor[h4]
Not everyone who is skilled in the ways of the Force seeks to hold a position of tremendous authority. In fact, some believe they would find it too easy to abuse their unique abilities if they placed themselves in a position of leadership. Instead, they choose to accept the Advisor’s role to ensure they cannot be corrupted by the lure of power. Others feel their advice too valuable to limit to one planet or region and wander the stars, sowing the guidance of the Force wherever they might go. Socially adept and Force-sensitive characters with either of these philosophies can be excellent fits for the Advisor specialization.
[P]
Advisors acquire [B]Charm, Deception,
Negotiation[b], and [B]Streetwise[b] as additional career skills. If this is the character’s starting specialization, he may choose two of these skills and gain one free rank in each, without spending starting experience. This combination enables Advisors to take a very pragmatic approach in working with others and offering them the guidance of the Force. An accomplished Advisor can quickly analyze the risks of a situation and then, using the necessary tools, influence the involved parties so that a desired outcome is rapidly achieved. A less scrupulous individual with these techniques could become a successful con artist. Advisors must be careful to avoid that fate.
[P]
Some Advisors attach themselves to a planetary government, helping to shape the rule of law and ensure fairness and justice for all. Many popular rulers have had wise Advisors at hand, helping ensure their policies do the most good for the greatest number. Other Advisors choose to work in less glamorous roles—often among the poor and the desperate. There, they try to counsel and guide individuals in dire straits, sometimes providing salvation to those who have lost all hope.', NULL, '["CHARM","DECEP","NEG","SW"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["PLAUSDEN","KNOWSOM","GRIT","KILL"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["TOUGH","KNOWSOM","KNOWPOW","NOBFOOL"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":2,"cost":15,"talents":["GRIT","SMOOTHTALK","SMOOTHTALK","PLAUSDEN"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":false},{"right":true,"down":true,"left":true,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["NOBFOOL","NATCHARM","CONTPLAN","SENSDEMO"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["DEDI","STNERV","FORCERAT","SENSEADV"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":false,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('ADVOCATE', 'Advocate', '[H4]Advocate — Kingmakers[h4]
Not all politicians contribute to the cause through stirring speeches to win the hearts and minds of the public. Part political strategist and part counsellor, the Advocate uses argumentation and insight to expose the flaws in political opponents and accentuate the best qualities of allies. A skilled Advocate turns the words of a foe back upon him or rephrases a friend’s thoughtless comment, casting it in a positive light. Backed by an Advocate, even a political novice can become a force to be reckoned with, and a truly skilled politician can soar to untold heights of power and influence.
[P]
To assist with his unique political role, the Advocate receives the [B]Coercion, Deception Negotiation,[b] and [B]Vigilance[b] skills as additional career skills. If this is the character’s starting specialization, he may choose two of these skills, gaining one free rank in each without spending starting experience. These skills reflect an Advocate’s need to remain alert at all times, and his tendency to undertake tasks others might find onerous or unethical. Vigilance helps an Advocate determine when a situation is growing dangerous, while Coercion is crucial to badgering opponents into backing down once the Advocate has the right piece of evidence in hand.
[P]
Advocates approach the negotiation table in several different ways. Some seek to act entirely behind the scenes, writing speeches or giving guidance to assist more personable politicians. Others hurl themselves into the fray, undermining opponents with a solidly constructed argument or strengthening the rhetoric of political allies by subjecting it to the harshest scrutiny. A good Advocate can be a trusted mentor or a hated rival, and a great Advocate knows how to be either one as the situation demands.
[P]
Advocates work best within a group, either backing up a skilled speaker or elevating a less experienced but more personable character to act as the faction’s public face. While an Advocate can apply pressure effectively, his greatest potential is in the role of a mentor or manipulator, directing other, more visible actors.
[P]
A veteran Diplomat might want to take Advocate as a second specialization after investing heavily in interpersonal skills, combining the rhetorical skills of another specialization with the Advocate’s emphasis on applying pressure to get results. Alternatively, a Soldier, Spy, or other character with a more combat-oriented focus might find the Advocate helpful as a secondary specialization, enabling that character to more effectively contribute to social encounters.
[P]
An Advocate benefits greatly from a high Cunning or Willpower characteristic. One who invests in both can be extremely flexible in social situations, filling the role of mentor, manipulator, mediator, or attack dog as the circumstances of the negotiation require. Whatever skills the character wields to this end, a good Advocate gets results above all.', NULL, '["COERC","DECEP","NEG","VIGIL"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["PLAUSDEN","NOBFOOL","GRIT","CONF"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["DISCREDIT","PLAUSDEN","SUPPEVI","NOBFOOL"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":false},{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["TWISTWORD","PLAUSDENIMP","GRIT","ENCWORD"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["PLAUSDEN","GRIT","SUPPEVI","GRIT"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["BLACKMAIL","DEDI","INTERJECT","CONTPLAN"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('AGGRES', 'Aggressor', '[H4]Aggressor[h4]
The Aggressor relies on fear to intimidate his opposition into surrender or retreat. Aggressors tend to be tough and dangerous combatants, able to dish out brutal damage to anyone who fights them, while surviving the same. They use their confident, terrifying attitudes to convey this to their opponents. Some Aggressors hope their enemies back down without a fight, but others fall into the trap of relishing the fear they inspire.
[P]
Aggressors acquire [B]Coercion, Knowledge (Underworld), Ranged (Light)[b], and [B]Streetwise[b] as additional career skills. If this is the character’s starting specialization, he may choose two of these skills and gain one free rank in each, without spending starting experience. These skills enable Aggressors to recognize the bravado shown by criminal enforcers and thugs. It also aids them in cowing these individuals, assuring these predators that the Force-sensitive character is a far scarier and more potent individual than they have previously faced.
[P]
Tempered by the Force, some characters who undertake this specialization prefer to use their abilities to intimidate foes into surrender so they don’t have to kill needlessly. While they are extremely capable in this regard, they frequently learn the techniques required to cause the bare minimum of damage necessary. Precision is important, as every life still holds value in the Force.
[P]
When confronted by a foe that seems irredeemable, however, the Aggressor’s attitude shifts appropriately. All elements of self-restraint are discarded, and the Aggressor is able to simply punish his foes, inflicting devastating blow after devastating blow. Often, opponents simply flee rather than engage an Aggressor. Stories told by survivors—and sometimes allies—add to the character’s reputation, making it even easier to intimidate future enemies.', NULL, '["COERC","RANGLT","SW","UND"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["INTIM","PLAUSDEN","GRIT","TOUGH"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["FEARSOME","INTIM","PREYWEAK","SENSEADV"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":2,"cost":15,"talents":["FEARSOME","TERRIFY","CRIPV","TOUGH"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["GRIT","TERRIFYIMP","PREYWEAK","HERO"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":4,"cost":25,"talents":["FORCERAT","FEARSOME","DEDI","AAO"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":false,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('AGITATOR', 'Agitator', '[H4]Agitator — Rousing the Masses[h4]
The Empire''s main weapon, more effective than all of the incredible firepower at its disposal, is fear. Fear lets it maintain order and authority over the countless beings in its thrall. The Agitator''s primary goal is to remove that fear and replace it with anger, or courage, or a sense of righteousness—whatever it takes to get the people to rise up, take up arms, reject Palpatine''s tyranny, and restore freedom and justice to the galaxy. 

[P]For Agitators, [B]Coercion, Deception, Knowledge (Underworld),[b] and [B]Streetwise[b] are all added as career skills. So long as this is the first specialization for the PC, he gains a free rank in two of these four skills. Agitators often bully the bullies to move them out of the way, and when they are able to get the people to follow them, they know how to lead. Understanding the ways of the streets is also vital to survival and success. 

[P]Most Agitators come by the calling through hardship and suffering. Their own personal tragedies at the hands of their oppressors drive them to call upon others to resist injustice and authoritarianism. Some are more altruistic in nature, sufficiently moved,by the suffering of others to take action and rouse the people to a cause in which they can believe. Only those with charisma and will in sufficient quantities can truly succeed in this dangerous and demanding course. 

[P]Many in the Alliance''s upper levels consider Agitators a necessary evil; they are not keen to move populations of untrained civilians to go to war against the Empire''s stormtroopers and other resources, yet they accept that, ultimately, it will take the entire galaxy doing just that if victory is to be achieved. When possible, Agitators are supported by other Alliance operatives, and a plan to arm and support the populace is usually in place before the Agitator goes to work.', NULL, '["COERC","DECEP","UND","SW"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["PLAUSDEN","NOBFOOL","GRIT","INTIM"],"directions":[{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["STRSMART","STRSMART","CONV","INTIM"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":false}]},{"index":2,"cost":15,"talents":["CONV","PLAUSDEN","SCATH","GRIT"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["NATENF","NOBFOOL","SCATHIMP","INTIM"],"directions":[{"right":true,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":4,"cost":25,"talents":["INTIM","DEDI","SCATHSUP","INCITE"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('ALCHEMIST', 'Alchemist', '[H4]Alchemist — Giving Life to the Inanimate[h4]
[P]During the era of the Galactic Republic, the Jedi Order never embraced alchemy. Various spiritual orders that had worked in alchemy also allied with the dark side of the Force. The Sith, the Nightsisters of Dathomir, and the Frangawl Cult on Bardotta all used the dark side to power their weapons, talismans, and magicks. Whether or not the Jedi thought that alchemy led to the dark side of the Force has been lost to time.  Perhaps the Order felt that giving life to the inanimate, pouring the Force into a dead object, replicated the act of giving life, of giving birth, or of playing god, and would cause the Jedi to become prideful.
[P] With the rise of the Empire and the loss of the Jedi Order, now no one can warn a potential Alchemist away from practicing this lost art. This might be just as well. Just like any technology, it isn''t the object but t he user that makes it good or bad, light or dark, useful or destructive. In addition , the Force flows through everything, even inanimate objects. Rocks have a measure of the Force in them. How else could a Jedi move them? With that reasoning, nothing should prevent a Jedi from imbuing a machine with the Force, save the Jedi''s own fears, hatred, and obsessions.
[P]An Alchemist''s additional career skills are [B]Knowledge (Education), Knowledge (Xenology) , Medicine[b], and [B]Resilience[b]. Upon character creation, if t his is the character''s first specialization, pick two of these skills to automatically gain one rank in each.
[P]The Jedi built their own lightsabers not only for ritual or training purposes, but to infuse a bit of t heir own essence into the weapon. The Jedi consciously and deliberately built these weapons both as a technical test and as a meditative test. It co ld be argued that a lightsaber contains the presence of its creator-and perhaps its user(s).
[P]Force alchemy extends this idea and discipline further, crafting physical objects infused with the power of the Force.  These objects appear to have a life of their own, and in the eyes of a Force sensitive, perhaps they do. This creates a metaphysical conundrum: if an object possesses a measure of the Force, how is it different from a living being?
[P]Alchemists tend to focus on medicinal concoctions, since the healing of a physical body is the most direct method of using and influencing the Force. The flow of a medicine, tincture, salve, or draught mimics the flow of the Force. Alchemists can work in other materials, but this requires more training and attention. A malformed or malfunctioning machine can''t be fixed with an infusion of the Force. In many ways, it might exacerbate the damage.
[P]Folk tales and popular holovids of machines coming to life and terrorizing their creators and innocents may be based on true stories of Alchemists who fell to the dark side of the Force. Force-infused objects can be tortured as much as any living creature. When the Alchemist is a dark side user, alchemical machines take on a sinister and dangerous aura, "malfunctioning" to cause harm or, in the case of a weapon, increasing suffering when it does cause harm.', NULL, '["EDU","MED","RESIL","XEN"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["GRIT","STIMSPEC","RESEARCH","BLO"],"directions":[{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["RESEARCH","STIMAP","ALCHEMICALARTS","GRIT"],"directions":[{"right":true,"down":true,"left":false,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["STIMSPEC","BLO","BLOIMP","TRANSMOGRIFY"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":false},{"right":false,"down":true,"left":false,"up":true}]},{"index":3,"cost":20,"talents":["STIMAPIMP","KNOWHEAL","GRIT","ALCHEMICALARTS"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["FORCERAT","IDENTIFYINGREDIENTS","DEDI","IMPROVISEDCONCOCTION"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":false,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('AMBASSADOR', 'Ambassador', '[H4]Ambassador — Courting Support[h4]
An Ambassador seeks out those who can help a cause and works to ensure they do. He brings the best arguments he can to sway planets, systems, corporations, and other groups to side with the forces he serves. The Ambassador brings every possible asset to bear in order to convince them to see things his way. 

[P]Ambassadors gain [B]Charm, Discipline, Knowledge (Core Worlds),[b] and [B]Negotiation[b] as added career skills, and may receive a free rank in two of them if this is the first selected specialization for the PC. Masters of the bargaining process between governments and similar factions, Ambassadors know how to keep their wits about them and resist being manipulated themselves. 

[P]Compromise is a way of life for the Ambassador; he won''t even bother going into a negotiation if he has no room in which to maneuver. The true mastery of his trade is in getting his most important goals agreed to and making the other side of the discussion feel like the agreement was its doing. Ambassadors are just as effective in dealing with individuals in crisis situations as they are in managing discussions with a room full of skeptical politicians. 

[P]The Alliance lives and dies on the abilities of its best Ambassadors. Every time they are able to convince yet another planet, faction, or corporation to side with the Rebellion, that much more hope spreads throughout the ranks, and many more resources become available. The upper echelons understand even the end of the war won''t mean an end to the conflict, and that stage will be fully in the hands of their Ambassadors.', NULL, '["CHARM","DISC","CORE","NEG"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["INDIS","KILL","NOBFOOL","CONF"],"directions":[{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["INDIS","GRIT","GRIT","DODGE"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":2,"cost":15,"talents":["KILL","INSPRHET","STNERV","CONF"],"directions":[{"right":true,"down":true,"left":false,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["INSPRHETIMP","INTENSPRE","WORKLIKECHARM","DODGE"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":false},{"right":false,"down":true,"left":false,"up":true}]},{"index":4,"cost":25,"talents":["INSPRHETSUP","NATCHARM","DEDI","SIXSENSE"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":false,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('ANALYST', 'Analyst', '[H4]Analyst — Connecting the Dots[h4]
Knowledge is power, on the battlefield and in negotiations alike. The Analyst knows this (and a great many other things) better than anyone else. More importantly, the Analyst knows how to leverage such information to maximum effect, finding the trends and connections that turn otherwise meaningless facts into crucial intelligence that might someday decide the outcome of the Galactic Civil War. 

[P]The Analyst gains [B]Computers, Knowledge (Education), Knowledge (Warfare),[b] and [B]Perception[b] as additional career skills. If this is the character''s starting specialization, he may choose two of these skills, gaining one free rank in each without spending starting experience. These skills allow Analysts to not only parse and remember vast amounts of data, but also contextualize it in a way that makes the data useful. The Computers skill can be particularly valuable, allowing an Analyst to access archives and slice into communications systems to stay informed. The specialization''s considerable access to Knowledge skills also allows an Analyst to know a bit about everything. 

[P]Some Analysts focus their attention on one specific topic, such as mastering Rebel Alliance codes tracking data on its units in the field, or monitoring Imperial activity in specific regions via the HoloNet. Others act as liaisons to political and military leaders, using their considerable research experience to provide any information their allies need. 

[P]Experienced Analysts are crucial to the diplomatic success of the Rebel Alliance. Many politicians and leaders look to Analysts for key support, and some even have a background in such work themselves. Knowing the unique customs of a local culture can be crucial to the success of a diplomatic mission, so an Analyst must have access to this information at a moment''s notice. Analysts can be equally important on the battlefield, identifying troop-movement patterns that betray the foe''s strategy or providing information about local environmental conditions so the Quartermaster can properly equip infantry. Wherever they serve, the knowledge and skills of Analysts save lives as surely as the choices of commanders and the hands of medics. 

[P]Analysts work best when they have the opportunity to exhaustively research a subject before going into the field, but the work of the Rebel Alliance sometimes requires its representatives to improvise. Therefore, Analysts—especially those attached to squads with specializations and missions as diverse as most PC groups—must be prepared to work on the fly. Even without access to data archives or the HoloNet, a skilled Analyst can effectively observe and break down a situation, identifying ways the squad can exploit vulnerabilities in enemy strategies and technologies. 

[P]An Analyst benefits from a high Intellect characteristic for making Computers and Knowledge checks to access and remember information. A high Cunning also assists Perception checks to spot critical details.', NULL, '["COMP","EDU","PERC","WARF"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["RESEARCH","KNOWSPEC","COD","TECHAPT"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["VALFACT","RESEARCH","SUPPEVI","GRIT"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["KNOWSPEC","RESEARCHIMP","COD","ENCCOMM"],"directions":[{"right":true,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":3,"cost":20,"talents":["GRIT","KNOWALL","KNOWSPEC","NATPRO"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["DEDI","KNOWSPEC","THORASS","STRGEN"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":false,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('ARBITER', 'Arbiter', '[H4]Arbiter — The Open Hand[h4]

An Arbiter knows that often, no matter how hopeless a situation appears, a path to enlightenment and balance can be achieved through perserverance and negotiation. An Arbiter channels the nonviolent tendencies of the Consular into active negotiation between potential allies, who have fallen into conflict through misunderstanding or nefarious influences. Through an understanding of sentient nature and the ebb and flow of conflict, an Arbiter can often pave the way for a group in the face of the most violent opposition.

[P]The additional career skills for an Arbiter are [B]Knowledge (Xenology)[b], [B]Lightsaber[b], [B]Negotiation[b], and [B]Perception[b]. Characters who select this as their starting specialization may gain one free rank in two of these skills without spending starting experience. The career path of a Counsular is a wide and varied one leading in such directions as those of the healer, student, or mystic. The Arbiter has chosen the path of the negotiatior and peacemaker, following an innate impulse to seek peace and balance in the heated atmosphere of conflict and confusion. An Arbiter is able to stand between two foes, see to the heart of the conflict between them, and bring calmness and reconciliation to the situation.

[P]Arbiters are born negotiators. Whether fully aware of their Force powers or not, they tend to find themselves following the career paths of diplomats and mediators, seeking to bring peace to the galaxy. Some Consulars work with the Rebel Alliance, finding like-minded societies and bringing them into the Rebel fold or helping them to overcome Imperial presure. However, many do their work in secret, laboring with a wide variety of corporations, organizations, and other groups to help bring harmony and tranquility to a wartorn galaxy. Arbiters see the ebb and flow of pressure and belief that perpetuate the violence and conflict bred by miscommunication and misunderstanding. Arbiters seek to bring balance to the galaxy through negotiation and reconciliation.

[P]The Arbiter understand the importance of calmnessm respect and tact while dealing with a diverse array of possible allies and potential enemies. Although many, when confronted with injustice or intransigent negativity, might reach for their lightsaber, an Arbiter''s first recourse will always be discussion and negotiation. When the local situation looks completely hopeless, when ancient grudges or new transgressions threaten to tear a system down into violence and chaos, an Arbiter will be able to find a path through the bedlam, to see a course of action that will restore peace and create an environment conductive to the prosperity and contentment of all.

[P]An Arbiter is skilled in acting as the face of a group, providing an interface between the group and the authorities controlling its current area of operation. An Arbiter can assist her group with social interactions, negotiations, and acquisitions, opening doors that less diplomatic characters may find ndelibly closed. The Arbiter must at all times keep in mind the greater scope of her duties. Peace is always the ultimate goal, but there is often a bigger picture that must be considered. And when the time for negotiation is at and end, even Consulars must be ready to use more direct means, no matter how regretful they may be.', NULL, '["LTSABER","NEG","PERC","XEN"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["SENSDEMO","SAVVYNEG","GRIT","NOBFOOL"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["GRIT","CONGENIAL","TOUGH","REFLECT"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":false}]},{"index":2,"cost":15,"talents":["SAVVYNEG","NOBFOOL","PARRY","SUNDERIMP"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":3,"cost":20,"talents":["CALMAURA","CRUCPOINT","SAVVYNEG","REFLECT"],"directions":[{"right":true,"down":true,"left":false,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["FORCERAT","SAVVYNEGIMP","DEDI","AGGRNEG"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":false,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('ARCHEOLOGIST', 'Archaeologist', '[H4]Archaeologist — The Thirst For Discovery[h4]
Most Explorers are searching for the new—new opportunities, new planets, new civilizations, new marketplaces, etc. Archaeologists, on the other hand, are firmly entrenched in the old. The galaxy is impossibly old, and nigh-infinite millennia have witnessed the rise and fall of countless civilizations. The Archaeologist endeavors to find these lost cultures and unlock the secrets of their history, art, science, and everything else about them. 

[P]Though Archaeologists have a strong focus on their scholastic pursuits and understanding of history, they tend to have a rough-and-tumble approach to dealing with the, inevitable challenges they are likely to face in the field. 

[P]An Archaeologist''s list of bonus career skills is a clear indication of his particular areas of focus: [B]Athletics, Discipline, Knowledge (Education),[b] and [B]Knowledge (Lore)[b]. If this is the character''s starting specialization, he may choose two of these skills and gain one free rank in each without spending additional starting experience. 

[P]Most Archaeologists believe very passionately that what they do is noble and important to the people of the galaxy. They tend to be less concerned with who is currently in charge, except for how the prevailing policies of the current government impact their studies and digs. Unfortunately for the current state of the field, the Empire tends to take a very heavy hand in matters of "revisionist history," preferring to alter findings to best fit its agendas. As such, most Archaeologists either work outside of Imperial channels or wish they did. 

[P]Player Character Archaeologists can easily be the centerpiece of a new campaign, building a team of other specialists to help in a recently embarked-upon expedition. Otherwise, such a character may be between digs and looking either for an expedition to join or "filler work" until he can make the right kinds of contacts. 

[P]Perhaps an archaeology-oriented Explorer joins a group that''s journeying to an area for completely different reasons; he trades his skills and knowledge for the chance to investigate rumors of a potentially valuable find once he gets to where they are going.', NULL, '["ATHL","DISC","EDU","LORE"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["WELLROUND","HARDHD","RESEARCH","GRIT"],"directions":[{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["DURA","TOUGH","RESOLVE","KNOWSPEC"],"directions":[{"right":true,"down":true,"left":false,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["STUNBL","KNOCK","RESPSCHOL","RESEARCH"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":true}]},{"index":3,"cost":20,"talents":["HARDHD","ENDUR","GRIT","KNOWSPEC"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["PIN","DEDI","RESPSCHOL","MUSEUMWORTHY"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('ARMORER', 'Armorer', '[H4]Armorer — The Smith[h4]
To protect others. one must first learn to protect oneself. So goes the logic of Armorers, whose unique combination of aptitudes makes them some of the toughest characters in the galaxy. Equipped with a knack for mechanics and a pre ternatural intuition when it comes to machines. these characters often fight clad in advanced technology and always use available resources to the utmost. Armorers can go toe-to-toe with the greatest threats the galaxy can throw at them. confident that their customized gear and innate resilience will help them shrug off nearly any blow.

[P]Armorers are defined by their ability to survive through a combination of ingenuity and stubbornness. While Protectors draw directly on the Force to avoid harm and Soresu Defenders use lightsabers to deflect incoming strikes, Armorers build a better defense, reinforcing solidly built equipment with the inestimable power of the Force.

[P]Armorers gain [B]Knowledge (Outer Rim), Lightsaber, Mechanics,  and Resilience[b] as additional career skills. These skills help Armorers in getting the tools they need for the job, maintaining and using those implements efficiently, and surviving to do it all again. If this is the character''s starting specialization, he may choose two of these skills and gain one free rank in each without spending starting experience.

[P]Armorers wield a number of talents that enhance their own armor and defenses, letting them survive hits that would fell most of their allies. They are extremely skilled craftspeople, and not only can build and modify their own gear proficiently, but can also use the Force to bolster their handiwork. With sufficient training, Armorers can imbue their armor with the power of the Force, allowing it to repel blows from lightsabers.

[P]Thanks to their sturdy defenses, Armorers often favor close-quarters combat, trusting their protection to see them through to melee range. Though lightsabers are practically legendary in this era of oppression, some Armorers manage to acquire the kyber crystals necessary to forge these weapons. The most skilled Armorers can even use their innate knowledge of the Force to unlock unseen potential in more mundane items, bringing out qualities that others have overlooked. This mystical ability, combined with an Armorer''s natural resourcefulness, means that catching an Armorer unarmed and unready grants only a minimal advantage.

[P]Though they certainly benefit from having a fully stocked machine shop available, Armorers can also do most of their work on the battlefield, scrounging and retrofitting the supplies they need. This flexibility can be a substantial advantage in [B]Force and Destiny[b], for the Empire hounds every step that Force users take, and they must be able to adapt to shifting circumstances and surroundings. If a vessel needs repairing behind enemy lines or a hull breach must be sealed during a firefight, an Armorer is often the best sentient being for the job.

[P]Outside of combat, Armorers can be extremely helpful to their allies. In addition to possessing considerable skill at modifying equipment, they can repair vehicles and other machines that the group needs kept in working order. While Artisans have the edge in refined skill with technology and the deep research into matters involving machines, Armorers can get the job done, and do it under enemy fire.', NULL, '["LTSABER","MECH","OUT","RESIL"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["GRIT","TOUGH","GEARHD","INVENT"],"directions":[{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["SABERTHROW","ARM","GRIT","GEARHD"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":true,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":2,"cost":15,"talents":["TOUGH","ARMIMP","INVENT","MENTTOOLS"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["COMPTECH","TINK","FALLAVAL","ARMSUP"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["FORCERAT","IMBUEITEM","REINITEM","DEDI"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":false},{"right":false,"down":false,"left":false,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('ARTISAN', 'Artisan', '[H4]Artisan[h4]
Some Force users have an innate skill with tools and machines. These skilled artificers can use their skill with the Force to enhance their abilities, and even intuitively understand a machine''s form and function. After all, while tools and machines may not be alive, the Force envelopes everything in the galaxy. Artisans feel the Force that surrounds their tools and the items they work on, using this connection to build creations of wondrous beauty and precision. An Artisan does not create scores of the same item for sale or distribution. Instead, each of his creations is individual and iconic, a true work of art. 

[P]Artisans acquire [B]Astrogation, Computers, Knowledge (Education),[b] and [B]Mechanics[b] as additional career skills. If this is the character''s starting specialization, he may choose two of these skills and gain one free rank in each, without spending starting experience. In order to fully integrate their Force abilities with the devices they manipulate, Artisans must first have a solid understanding of how those tools work. This requires a fundamental educational grounding in the principles of technology. 

[P]Within urban environments, individuals who never learn to recognize their Force talents are prone to follow the Artisan''s path. This is because they are surrounded by technology, and if these individuals take an interest in how things work and how to repair them, their Force abilities may naturally develop in concert. When faced with a broken machine, they can often identify the problem in an intuitive way—some even claim that the machines "speak" to them. Some Artisans live up to the stereotype of the messy inventor, while others remain meticulously neat or even take pains to disguise their craftsmanship from casual observers.', NULL, '["ASTRO","COMP","EDU","MECH"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["SOLREP","FINETUN","MENTTOOLS","TECHAPT"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["GRIT","SOLREP","FINETUN","GRIT"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["INVENT","IMBUEITEM","NATTIN","DEFSLI"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["SOLREP","FORCERAT","DEFSLI","MENTFOR"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":false},{"right":true,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["MASTART","INTUITIMP","DEDI","COMPTECH"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('ASCETIC', 'Ascetic', '[H4]Ascetic — The Quiet Mind[h4]

There are many paths that might lead one to the role of Ascetic. Whether they are particularly sensitive and seek seclusion to contend with some failure that haunts their steps or wish to contemplate the greater role of the Force in the galaxy at large. Ascetics are individuals driven to a calmer, more contemplative approach to their life, their needs, and their place in the galaxy. They do not seek to gather credits, possessions, or laurels, but rather judge their worth by the depth of their understanding of and communion with the Force.

[P]Ascetics receive [B]Athletics[b], [B]Discipline[b], [B]Resilience[b], and [B]Vigilance[b] as additional career skills. Characters who select this as their starting specialization may choose two of these skills and gain one free rank in each without spending starting experience. While most Consulars focus on the acquisition of helpful skills and abilities, Ascetics concentrate on honing their own mind to a razor focus. As a result, they are likely to have a higher strain threshold than any other Consular specialization, and they have the versatility to work their way through almost any difficulty. An Ascetic has spent a considerable time living on the fringes of society, learning to make do with whatever materials and facilities were on hand, regardless of their apparent functionality or crude construction. Ascetics may be out of practice in social interactions and interpersonal communication, but the awareness and resilience they have gained through their trials, as well as the physical strength their chosen path has earned them, can be invaluable to a group when more refined, civilized plans have failed.

[P]An Ascetic may be found almost anywhere, from the urban wasteland and under-cities of the Core Worlds to the most inhospitable and isolated corners of the Outer Rim. The distractions and demands of the outside world can jar even the most focused, powerful minds from the spiritual path. Those who retreat from the nose and the chaos follow the path of the Ascetic. There are times when even the greatest must set themselves apart, focusing on the spheres of the spirit and the mind to the exclusion of all else. By embracing isolation and hardship, many Consulars are able to realize levels of potential that more mundane training techniques could never unleash.

[P]Many Ascetics have chosen their lonely path of deprivation and mediation to plumb the depths of a specific mystery, a troubling event in the balance of the galaxy, or a great personal failing. The growth made possible through this introspection and self-denial means that when Ascetics choose to emerge from their self-imposed exile, they are ideally suited to confront any situation, with the adaptability of hard-won experience. Often Consulars will surface from such isolation to take up a particular cause or purpose, driven from quiet contemplation of the galaxy by a troubling imbalance sensed from the depths of their serenity.

[P]The Ascetic can well prove to be one of the most versatile characters in his group. Between his high strain threshold, demanding physical training, and versatility bred through voluntary deprivation, and Ascetic can often provide flexible, insightful leadership to his group. Although perhaps lacking in some of the more subtle social skills of other Consulars, an Ascetic knows that meditation on the Force can only take one so far. The knowledge earned through such rigorous contemplation must eventually be put to use in the galaxy at large, either through teaching or direct action, to better bring balance to the Force.', NULL, '["ATHL","DISC","RESIL","VIGIL"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["PHYSTRAIN","CONF","GRIT","GRIT"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["GRIT","FORCEPROT","GRIT","GOWITHOUT"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["MEDTRANCE","SLIPMIND","INTENSFOC","PHYSTRAIN"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":false,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":false}]},{"index":3,"cost":20,"talents":["CONF","MINDBLEED","FORCEPROT","IRONSOUL"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":4,"cost":25,"talents":["DEDI","GRIT","EMPTYSOUL","FORCERAT"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":false,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('ASSAS', 'Assassin', '[H4]Assassin — Instrument of Policy[h4]
Whereas most Bounty Hunters focus primarily on the capture of quarry, those who specialize as Assassins are generally tasked with the straightforward proposition of terminating their targets. The selection of additional skills for an Assassin very much points towards his focus: [B]Melee, Ranged (Heavy), Skulduggery,[b] and [B]Stealth[b]. These four skills become additional Career skills. If this is the character''s starting Specialization, he may choose two of these skills and gain one free rank in each, without spending starting experience. Assassins tend to prefer getting in quielty, taking out targets (either up close or sniping from afar), and leaving just as silently as they entered. Their talets are very appropriate for this kind of work.
[P]
Despite their different methods, Assassins still adhere to many of the same ethics and practices of other Bounty Hunters. They take their work very seriously, avoid all needless bloodshed, and honor their contracts to the letter. Some treat their method with reverence, even assigning a certain mystique to it. Others simply see themselves as cold killers, and are just fine with it.', NULL, '["MELEE","RANGHVY","SKUL","STEAL"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["GRIT","LETHALBL","STALK","DODGE"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["PRECAIM","JUMP","QUICKST","QUICKDR"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["TARGBL","STALK","LETHALBL","ANAT"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":3,"cost":20,"talents":["STALK","SNIPSHOT","DODGE","LETHALBL"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":4,"cost":25,"talents":["PRECAIM","DEADACC","DEDI","MASSHAD"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('ATARU', 'Ataru Striker', '[H4]Ataru Striker[h4]
When working alone in a hostile environment, every physical conflict must be resolved quickly and decisively. Frequently, an uncivilized planet completely lacks any sort of medical facilities. In fact, at times, an isolated explorer could be the only sentient being on the world. In such a situation, a minor injury can be deadly. If a conflict is necessary, it is better to resolve it quickly, taking whatever risks are involved, than to fight more conservatively and prolong the risk of injury. The Ataru Striker embraces this approach, throwing himself into combat with every fiber of his being. 

[P]Ataru Strikers acquire [B]Athletics, Coordination, Lightsaber,[b] and [B]Perception[b] as additional career skills. If this is the characters starting specialization, he may choose two of these skills and gain one free rank in ''each, without spending starting experience. This fighting style is highly dependent on the combatant''s ability to quickly assess a situation and use natural athleticism to exploit the environment. In this way, the combatant is able to gain every possible advantage over an opponent. The combination of these edges and the rapid attacks that characterize Ataru martial arts can force a combat to a very quick resolution. 

[P]Practitioners of the Ataru fighting style must be supremely confident in their abilities. They must also be exceptionally athletic and capable of committing all their energy into a very brief conflict. When engaged in a physical conflict, Ataru Strikers fight without remorse but also with little concern for their own safety. Every motion is designed to inflict a flurry of rapid and overpowering attacks against their opponents from myriad angles. Their vicious and unrelenting offense is their best (and sometimes only) defense—most opponents are so busy defending themselves that they have no time to attack in turn. 

[P]However, this style of unrelenting attack can have its disadvantages. An Ataru Striker needs to see his opponent defeated quickly, before he exhausts himself. An individual who can outlast an Ataru Striker can prove to be his deadliest enemy.', NULL, '["ATHL","COORD","LTSABER","PERC"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["CONDITIONED","PARRY","JUMP","QUICKDR"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["DODGE","REFLECT","ATARU","QUICKST"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":false,"up":true}]},{"index":2,"cost":15,"talents":["QUICKST","REFLECT","PARRY","PARRYIMP"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":3,"cost":20,"talents":["DODGE","HAWKSWOOP","SABERSW","CONDITIONED"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["PARRY","DEDI","SABERTHROW","BAL"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":false,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('BEASTRIDER', 'Beast Rider', '[H4]Beast Rider — Mounted Marauders[h4]
Many worlds in the galaxy are too backward, too poor, or have environments too extreme to support modern vehicles. Sometimes, instead of spending credits to adapt a speeder to the cold or create a filter that can keep sand out of a repulsordrive, it is simply easier to use a native mount that has evolved and adapted to local conditions for untold millennia. 

[P]While most any being can ride a trained mount, it is the Beast Rider who can break in wild mounts and train them. Once he has trained a mount, the skilled Beast Rider can coax his mount to perform incredible feats, even in the heat of battle. The Beast Rider is also something of an outdoorsman, and is. a valuable member of a team with or without his creature companion.

[P]Beast Riders might be expert riders on a single type of mount or experienced creature wranglers who have spent time with all manner of riding creatures. Most cultures and militaries, despite the broader reliance on modern machinery, still rely heavily on mounts. The Imperials ride lizard-like dewbacks on desert worlds like Tatooine, while the Rebels famously saddled up tauntauns on Hoth. Indigenous cultures throughout the galaxy depend on Beast Riders, including the bantha-obsessed Tusken Raiders of Tatooine and the ruping riders of Onderon. 

[P]Beast Riders receive [B]Athletics, Knowledge (Xenology), Perception,[b] and [B]Survival[b] as additional career skills. If this is the character''s starting specialization, he gains one free rank in each of two of these skills of his choice, without spending experience. Unlike their fellow Aces, the Beast Rider is at home outdoors, where he can feel the wind on his face. He fits in just as well with the soldiers and scouts of the Rebel Army as with his fellow Aces in starfighters and speeders. 

[P]The Rebellion often assigns Beast Riders as scouts at Rebel bases and outposts, conducting patrols and setting up advance defenses and other contingency measures to prepare for potential Imperial discovery. When an Imperial or one of his allies spots creature tracks, he might think it belongs to a wild creature—whereas, if he sees vehicle tracks, he is very likely to investigate. In battle, mounted cavalry might not be quite as fast, agile, or heavily armed and armored as its mechanized counterparts, but it has several advantages. Creature mounts have better camouflage, more mobility in close quarters, and in battle, Imperial vehicles often ignore them outright. 

[P]Most groups can benefit from a Beast Rider in their ranks. The Beast Rider is second only to the Spy carer''s Scout specialization in matters of wilderness survival and guerrilla warfare. His ability to traverse difficult terrain, capture and train indigenous mounts, and locate food and shelter are critical to a number of Rebel mission profiles. Further, should a team member crash land, or otherwise become stranded, a Beast Rider might be critical to their very survival.', NULL, '["ATHL","PERC","SURV","XEN"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["FORAG","TOUGH","OUTDOOR","BEASTWRANG"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["OUTDOOR","EXTRACK","TOUGH","EXHANDLER"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":2,"cost":15,"talents":["EXTRACK","BEASTWRANG","LETSRIDE","GRIT"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["SPURIMP","SPUR","NATOUT","EXHANDLER"],"directions":[{"right":true,"down":true,"left":false,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":false,"up":true}]},{"index":4,"cost":25,"talents":["SPURSUP","DEDI","GRIT","SOOTHTONE"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":false,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":false}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('BGMHUNTER', 'Big-Game Hunter', '[H4]Big-Game Hunter — The Thrill of the Hunt[h4]
With the skills of a survivalist, the instincts of a bounty hunter, and the courage of a madman, the Big-Game Hunter tends to baffle everyone with his desire to actively track down, confront, and do battle with the most terrifying creatures in the galaxy. He understands and respects the environments he must contend with in order to pursue his quarry, yet he is less interested in where he is going than in what he is going to kill when he gets there. 

[P]Though some true pacifists may take great exception to the notion, Big-Game Hunters tend to believe they are performing a service to the people of the galaxy. They generally seek out truly dangerous and deadly creatures to fight and kill, thus making more areas in the galaxy safe for sentient habitation. 

[P]With a focus on all aspects of the hunt, the bonus career skills for a Big-Game Hunter are [B]Knowledge (Xenology), Ranged (Heavy), Stealth,[b] and [B]Survival[b]. If this is the character''s starting specialization, he may choose two of these skills and gain one free rank in each without spending starting experience. Big-Game Hunters tend to know how to get where their prey is, how to stay alive once they get there, and all about whatever it is they are there to do battle with. 

[P]Of course, there are plenty of hunters who are more than willing to kill pretty much anything that can net them a hefty profit, whether for pelts, horns, organs, or whatever else someone is willing to pay for. There are some hunters who take specific contracts from local governments to thin out a herd of something that is growing too large or to eliminate particularly enraged (and possibly infected) creatures that pose a danger to civilization. 

[P]For a Player Character, a Big-Game Hunter may not seem like a good fit at first. However, his general Explorer capabilities combined with his survival skills and his talent for fighting particularly dangerous foes may well make him a linchpin for a group''s success. Many Big-Game Hunters will take whatever jobs they can find out in the Rim just for the chance to travel to new places and see what there is to hunt.', NULL, '["RANGHVY","STEAL","SURV","XEN"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["FORAG","GRIT","STALK","OUTDOOR"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["TOUGH","OUTDOOR","CONF","SWIFT"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":false,"up":true}]},{"index":2,"cost":15,"talents":["STALK","NATHUN","EXTRACK","HEIGHT"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":false,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":3,"cost":20,"talents":["GRIT","HUNTERQUARRY","QUICKST","EXTRACK"],"directions":[{"right":true,"down":true,"left":false,"up":false},{"right":true,"down":true,"left":true,"up":false},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":4,"cost":25,"talents":["BRNGITDWN","HUNTQIMP","DEDI","SUPREF"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('BLORUN', 'Blockade Runner', '[H4]Blockade Runner[h4]
[B]At a Glance[b]
[BR]The Blockade runner is the pilot that can outrun anything, avoid detection, and generally makes it impossible to be pinned down, or worse, impounded.
[P][B]All-in or Hybrid?[b]
[BR]½ Generic, defensive-leaning Pilot, ¼ Navigator w/ a Focus on Obfuscation, and ¼ Convincing authorities things are “above board”
[P][B]What Should it be the Best At?[b]
[BR]Piloting Defensively
[P][B]What should it be just “good” at?[b]
[BR]Astrogation, 
Social
[P][B]Specs for Comparison / Inspiration[b]
[BR]Pilot (Raw),
Navigator,
Ship Captain
[P][B]Media Touchstones[b]
[BR]Han Solo
[BR]Kay Vess (Star Wars Outlaws)
[BR]Booster Terrik
[BR]Hoban “Wash” Washbourne  (Firefly)', NULL, '["ASTRO","GUNN","PILOTPL","PILOTSP"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["FULLTH","SKILLJOCK","GALMAP","LETSRIDE"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["SKILLJOCK","TRICK","STDI","STRSMART"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":2,"cost":15,"talents":["FULLTHIMP","MUSP","GRIT","GREASE"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["GRIT","FULLTHSUP","DEFDRI","WRHI"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":false},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":4,"cost":25,"talents":["MASPIL","DEDI","BRI","CADR"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('BODYGUARD', 'Bodyguard', '[H4]Bodyguard — Personal Defender[h4]
Hired Guns who choose the Bodyguard specialization are excellent choices for defending both people and places. They tend to be highly capable with all kinds of weaponry, extremely tough and savvy in combat, and exactly the right people to get behind when blaster fire starts flying. 

[P]Their additional Career skills are indicative of their job: [B]Gunnery, Perception, Piloting (Planetary),[b] and [B]Ranged (Heavy)[b]. If this is the character''s starting Specialization, he may choose two of these skills and gain one free rank in each, without spending starting experience. With this array of skills, a Bodyguard can operate anything that shoots, keep a good eye on his surroundings, and can handle any planet-bound craft with great aptitude. This, combined with his talent options, makes him potentially perfect as an armed chauffeur [I]or[i] as a heavy weapons emplacement operator. He also makes a resilient soldier. 

[P]A Bodyguard will have a rather easy time finding work in the Outer Rim, especially if he doesn''t mind looking after the backside of high-ranking criminal scum or corporate operators who are trying to do business without becoming victims. His facility with all kinds of weapons and vehicles make him useful to any number of quasi-legal or criminal operations. 

[P]As part of a group of Player Characters, a Bodyguard is going to be considered more or less a heavy combatant—the guy who stands up front with the biggest gun. However, the combination of skills and talents can be angled towards some different approaches. For example, if there''s any kind of Politico or Trader in the group, a Bodyguard may well be there solely for the purpose of keeping that person alive.', NULL, '["GUNN","PERC","PILOTPL","RANGHVY"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["TOUGH","BAR","DURA","GRIT"],"directions":[{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["BOD","HARDHD","BAR","BRA"],"directions":[{"right":true,"down":true,"left":false,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":2,"cost":15,"talents":["BOD","SIDESTEP","DEFSTA","BRA"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":false,"up":true}]},{"index":3,"cost":20,"talents":["ENDUR","SIDESTEP","DEFSTA","HARDHD"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":4,"cost":25,"talents":["DEDI","BAR","TOUGH","HARDHDIMP"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":false,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('CHARMER', 'Charmer', '[H4]Charmer —  The Smooth Operator[h4]
Confident and elegant, the Charmer employs his wits and wiles with more precision than a laser scalpel. Rather than resorting to uncivilized intimidation tactics or distasteful acts of violence, the Charmer believes the best way to get what he wants is to simply ask for it. A Charmer knows how to talk the talk, possessing natural charisma that makes him irresistible. Struck by the flash of his smile or the wink of his eye, people have a hard time denying anything to the Charmer. 

[P]The Charmer combines the silver tongue of a Politico, the street smarts of a Scoundrel, and the keen mind of a Trader. Where the Politico might rally, chastise. or even bribe to achieve his objective, the Charmer showers his mark with flattery. While the Trader relies on his ability to haggle down a price, the Charmer convinces others that lowering the price is their idea. When a Scoundrel resorts to coercion and violence, a Charmer applies a softer touch to disarm his opponents with words alone. 

[P]In addition to the Smuggler''s eight career skills, the Charmer also receives [B]Charm, Cool, Leadership,[b] and [B]Negotiation[b] as bonus career skills. If this is the character''s starting specialization, he may choose two of these skills and gain one free rank in each without spending starting experience. 

[P]The chief weapon in a Charmer''s arsenal is clearly his undeniable charisma. When coaxing his way into a private club or restricted area, the Charmer knows how to compliment without sounding sycophantic. In rare cases when his debonair appearance and refined taste fails him, the Charmer knows how to resort to negotiation and trickery to get his way, doing so with his own smooth brand of flair and style. The Charmer keeps a cool head in the hottest situations, which often serves as inspiration to others, and he has no qualms with taking a leadership role if it furthers his purposes. Whether or not he knows the right thing to say, the Charmer always knows how to say it. 

[P]Despite all his silvered words, the Charmer is no gilded flower. When all else fails, if the Charmer cannot diffuse the situation before it escalates, or cannot convince others to fight in his place, the Charmer holds his own in combat. In a fight, the Charmer can cause opponents to doubt their motives and lower their guard. The Charmer''s Smuggler career gives him the knowledge to navigate the underworld, the ability to escape a jail cell, and the skill to steal a starship for a quick getaway. 

[P]A Smuggler who chooses Charmer as his specialization is an exceptional choice for nearly any campaign. His emphasis on social interaction makes the Charmer handy in any intrigue-oriented campaign, but his Smuggler fundamentals and ability to negotiate with merchants, distract would-be attackers, or diffuse combat encounters make him a welcome addition to underworld- or combat-focused campaigns as well.', NULL, '["CHARM","COOL","LEAD","NEG"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["SMOOTHTALK","INSPRHET","KILL","GRIT"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["KILL","INSPRHETIMP","CONGENIAL","PLAUSDEN"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":2,"cost":15,"talents":["DISARMSMILE","WORKLIKECHARM","DISARMSMILE","GRIT"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":3,"cost":20,"talents":["SMOOTHTALK","CONGENIAL","JUSTKID","INTENSPRE"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["NATCHARM","DEDI","DONTSHOOT","RESOLVE"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('COLOSSUS', 'Colossus', '[H4]Colossus — Indefatigable and Invincible[h4]
Most Warriors pride themselves on their ability to overcome pain. A Colossus, however, possesses a toughness far beyond that. While many fighters wear their scars with pride, an experienced Colossus ripples with scar tissue, the evidence of wounds enough to kill a normal combatant a dozen times over. Where other Warriors might seek to end conflicts quickly and decisively, a Colossus possesses the stamina, endurance, and strength of will to fight through inconceivable pain and punishment, outlasting the foe matter the odds.
[P]Colossus characters receive [B]Brawl, Discipline, Melee[b], and [B]Resilience[b], as additional career skills.  If this is the character''s starting specialization , the player chooses two of these skills and gains one free rank in each, without spending starting experience. These skills allow Colossi to endure great punishment both mentally and physically, and to ensure that they are prepared for even the most taxing situations and battles.
[P]Knowingly or not, Colossi reflect a number of stoic Force traditions that arose throughout history.  Some of these beliefs influenced the Jedi Order, particularly in teachings of the primacy of the mental and spiritual over the physical. By accepting the transience of physical pain, a Warrior can rise above it. Some arrive at such a state of mind independently, perhaps realizing (aided by a robust constitution) that physical pain is passing, and only makes them stronger.
[P]Becoming a true Colossus is rarely a matter of formal training, and there is no single path. Few sentients have the physical endurance or the mental reserves for this approach to combat. Those who do might hone their natural abilities through a number of means, likely never quite the same. Being a Colossus may mean transcending their natural physical limitations through meditation and focus, maintaining an internal calm even in the midst of ferocious battle. Others take the opposite approach, drawing on their pain and the negative emotions it evokes to fuel themselves in combat. This latter method is representative of those who tread closer to the dark side.

[P]Although all who fit the mold of a Colossus share certain traits when it comes to defense and longevity, they can take very different approaches to dishing out damage. There is no particular fighting style that defines a Colossus''s approach to attacking. Some might heft a heavy blaster, wading heedlessly through enemy fire to un leash a salvo. Others prefer hefty vibro-axes, swords, or other melee weapons, getting up close to enemies and trading blows, confident in their ability to take punishment and give it back in turn. Regardless of their preferred approach. Colossi are sure to have the strength to overcome an opponent with well-placed strikes should the opportunity arise.

[P]Whether by focusing on suffering or by aspiring to higher ideals, a Colossus achieves a preternatural level of physical hardiness and toughness by drawing on the Force. A hardened Force user possesses reserves of willpower to fight on despite agonizing wounds. More importantly, Colossi can allow the Force to flow through them. using it to achieve impossible feats of endurance. They may be blasted and slashed, but their wounds do not bleed. They walk on broken legs and continue the fight, though it might worsen their injuries. They harness their pain, returning it twice over.', NULL, '["BRAWL","DISC","MELEE","RESIL"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["TOUGH","DURA","HARDHD","GRIT"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["TOUGH","DURA","HARDHD","GRIT"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":2,"cost":15,"talents":["TOUGH","DURA","HEADBUTT","ENDUR"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":3,"cost":20,"talents":["TOUGH","UNSTOP","HARDHDIMP","INDOMITABLEWILL"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":4,"cost":25,"talents":["TOUGHENEDIMP","HERO","DEDI","POWERFROMPAIN"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('COMMANDO', 'Commando', '[H4]Commando — Strike the Target[h4]
Commandos are specialists trained to strike the enemy from unexpected directions to do the most damage in the most vulnerable locations. Commando teams are often used like surgical instruments by the commanders who have access to them. A Commando knows how to find a target, attack it, disable it, survive the aftermath, and find his way home. 

[P]Commandos gain [B]Brawl, Melee, Resilience,[b] and [B]Survival[b] as additional career skills. If Commando is the character''s first specialization, two of these new career skills gain a free rank each. Commandos are masters of close combat and surviving in all conditions. They are usually good at sneaking past enemy guards and listening posts as well. 

[P]For any team, a Commando is a fine general-purpose combat specialist to have around. He handles fights well (especially hand-to-hand situations), and can manage in almost any high-stress situation. More often than not, he''s also effective as backup during covert operations. Matters of overall philosophy or strategy rarely concern a Commando; he''s almost always focused on the mission at hand or training to ensure he and his companions survive the next one. 

[P]As stand-up confrontations are normally a losing proposition for the Alliance, the Commandos are some of the most important and effective soldiers fighting for the Rebellion. Their capacity to surgically strike at Imperial targets, as well as their value as guards and support personnel for other specialists operating on behalf of the Alliance, makes any single one of them worth more than a platoon of stormtroopers.', NULL, '["BRAWL","MELEE","RESIL","SURV"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["PHYSTRAIN","GRIT","TOUGH","POINTBL"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["TOUGH","DURA","PHYSTRAIN","STRONG"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["BLO","ARM","NATOUT","FERSTR"],"directions":[{"right":true,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":3,"cost":20,"talents":["TOUGH","HERO","DURA","KNOCK"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":false},{"right":false,"down":true,"left":false,"up":true}]},{"index":4,"cost":25,"talents":["ARMIMP","DEDI","UNSTOP","FERSTR"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('COMMODORE', 'Commodore', '[H4]Commodore — Capital Command[h4]
Each and every capital ship the Alliance has is valuable, which means that each Commodore given one to command has earned tremendous respect and trust. Even those Commodores who are not actually captains of particular ships, instead operating in another key support role, have demonstrated great gifts for strategic thinking and resource management on a large scale. 

[P]Commodores add [B]Astrogation, Computers, Knowledge (Education),[b] and [B]Knowledge (Outer Rim)[b] to their career skills. If this is the first specialization for a PC, two of these four skills gain a free rank when they are chosen. In addition to maintaining extraordinary calm in stressful situations and providing strong guidance to those around him, a Commodore is best served by understanding the incredibly technical aspects of navigating the stars and managing the crucial resources of his ship. 

[P]Commodores tend to spend very little time on any planet, having chosen a path placing them firmly in the stars with hard ship decks under their feet. They relish both the daily challenge of keeping a ship and its crew operating at peak capacity and facing the strategic challenges of capital ship engagements. The greatest Commodores find themselves managing not just a single ship, but a fleet of them, matching wits against their enemy counterparts in a huge game with very deadly consequences for each and every piece in play. 

[P]Effective Commodores are even more precious than Pilots for the Alliance Navy. Anyone showing a capacity for the role likely finds himself groomed heavily for eventual command. The Rebellion faces the might of the Imperial Navy with but a fraction of the tonnage in capital ships, so each one must be commanded by the absolute best.', NULL, '["ASTRO","COMP","EDU","OUT"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["SOLREP","COM","RAPREA","GALMAP"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["KNOWSCH","COMMPRES","GRIT","FAMSUNS"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":2,"cost":15,"talents":["SOLREP","COM","RAPREA","GALMAP"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":3,"cost":20,"talents":["HOLDTOG","COMMPRES","GRIT","MASSTAR"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":4,"cost":25,"talents":["SOLREP","FIRECON","DEDI","GALMAP"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('COURIER', 'Courier', '[H4]Courier — Ensuring Delivery[h4]
Couriers acquire [B]Athletics, Deception, Streetwise[b] and [B]Vigilance[b] as additional career skills. If this is the character''s starting specialization, the player may choose two of these skills and gain one free rank in each without spending starting experience. In order to avoid Imperial entanglements, Couriers must be capable of operating without drawing attention to themselves. As they cannot expect to always succeed, these character must also recognize the signs of trouble and have the ability to act quickly to escape entrapment. Because they often face overwhelming odds, personal speed is typically a higher priority than a trusted weapon.
[P]
Some Couriers prefer to work consistent routes as they shuttle information away from prying Imperial eyes. These specialists need a reliable cover story that they can use repeatedly. They might pose as merchants or transport drivers playing consistent trade routes. In a few instances, a Rebel might even take on the cover profession as a means of obtaining additional income, carrying innocuous cargo to market while smuggling critical information. Such spies go to great lengths to ensure that their business interests are completely legitimate, so that they do not attract any undue attention. They also make sure that those interests are at least marginally profitable. A merchant who loses money consistently for years, after all, is just as likely to draw government attention as one who manages exorbinant profits. These individuals may even establish friendly relationships with the guards along their routes, and their frequent passage through Imperial territory becomes just a part of a station''s routine traffic. In these cases, typically only a subset of their transit include military intelligence.
[P]
Other Couriers deliver critical data to Rebel specialists in a variety of locations instead of adopting a mundane occupation that involves travel on regular routes. Some are enthusiastic adrenaline junkies who call on wild speed and quick thinking to overcome Imperial security. More risk-averse Couriers simply excel at developing good cover stories and staying true to their roles during a mission. Adrenaline junkies or not, these Couriers are unlikely to have any established relationship with the local Imperial guards. Consequently, they must quickly determine how to bypass security or rely on other intelligence sources to prepare for it.', NULL, '["ATHL","DECEP","SW","VIGIL"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["INDIS","SHORTCUT","WELLTRAV","PILOTTRAINING"],"directions":[{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["HIDD","SWIFT","SECWIND","GRIT"],"directions":[{"right":true,"down":true,"left":false,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["GRIT","INDIS","FREERUN","SHORTCUT"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["HIDDENSTORAGEIMP","HIDD","INDISIMP","SECWIND"],"directions":[{"right":true,"down":true,"left":false,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["INCITEDISTRACTION","DEDI","USERTALENT1","NATATHL"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":false}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('CYBERTECH', 'Cyber Tech', '[H4]Cyber Tech — Self-Improvement At Any Cost [h4]
Many people think of the body as a machine. After all, it can fulfill complex functions, must be maintained, and wears down over time. When pieces of the body fail or need to be repaired, cyberneticists can help restore function and improve the quality of patients'' lives. While Cyber Techs focus their craft entirely on replacing the lost or damaged body parts of  patients, others seen no reason not to upgrade and modify bodies as they would other tools.

[P]The Cyber Tech specialization gives a Technician a way to explore the realm of medicine, using technical and biological know how to craft and maintain cybernetics, as well as to integrate them into living bodies. Given this ability to skillfully alter their bodies with cybernetics, most Cyber Techs perform at lease some upgrades on themselves. The degree and subtlety of an individual''s Cyber Techs upgrades tend to depend on the individual''s culture, species and personal beliefs. Within some cultures, extensive cybernetic augmentation is considered unusual or even taboo.

[P]In addition to the Technician''s eight career skills, the Cyber Tech receives [B]Athletics, Cybernetics, Mechanics, Medicine[b] and [B]Vigilance[b] as bonus career skills. If this is the  character''s starting specialization, the Cyber Tech may choose two of these skills and gain one free rank in each without spending starting experience.

[P]Despite the advantages of cybernetics, which many Cyber Tech are quick to point out, most humans and members of many other species tend not to seek out substantial enhancement unless absolutely necessary. Replacing a lost limb with a cybernetic one is common sense, but for most, the prospect of lopping off a healthy limb to replace it with a stronger one is another matter entirely. Still, among most sentient species with the necessary technology, there are those who have reasons for wanting to surpass flesh.

[P]Other groups and individuals hold no such qualms about removing flesh, bones and organs to replace them with what Cyber Techs see as undoubtedly superior components. Ganks, for instance, are a species known for their heavy use of cybernetic augmentation: completely unmodified Gank are very rare. Droids, of course have a special relationship with artificial limbs, and most droids desire periodic part replacements for maintenance.

[P]A Cyber Tech can take on extra cybernetics and can improve augmentations far beyond their normal capacities. Further, a Cyber Tech can assist comrades with medical care and by replacing body parts with cybernetics, though most beings only accept this help after losing a body part - no matter how fervently the Cyber Tech speaks to the virtues of replacing squishy unreliable flesh and organs with cold, sturdy steel.', NULL, '["ATHL","CYBERNETICS","MECH","MED","VIGIL"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["CYBERNETICIST","MOREMACH","ENGREDUN","TOUGH"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["EYEDET","TOUGH","ENERGTRANS","CYBERNETICIST"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["OVERCHARGE","MOREMACH","DURA","SURG"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["OVERCHARGEIMP","UTIL","MOREMACH","SURG"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":4,"cost":25,"talents":["MOREMACH","DURA","OVERCHARGESUP","DEDI"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":false},{"right":false,"down":false,"left":false,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('DEMOLITIONIST', 'Demolitionist', '[H4]Demolitionist — Force of Destruction[h4]
Demolitionists are masters of explosives and Incendiary devices. Often seen as dangerous pyromaniacs, most Demolitionists possess a deep understanding of the physics behind combustion and explosion on an intuitive level as well as an academic one. They are not mindless destroyers, but artists. Demolitionists are adept at wreaking havoc while avoiding being injured by their own handiwork—most of the time. 

[P]A Demolitionist''s additional career skills are [B]Computers, Cool, Mechanics,[b] and [B]Skulduggery[b]. If this is the character''s starting specialization, he may choose two of these skills and gain one free rank in each, without spending starting experience. With this selection of skills, Demolitionists can be much more technically-minded than most Hired Guns. They are also suited to much more than straightforward combat. Demolitionists can excel at setting traps, from improvised trip-wires tied to grenades to sophisticated proximity and timed explosives. Whereas another Hired Gun might go after an enemy in a straight-up fight, a Demolitionist may find a more inventive route, such as rigging a thermal detonator to explode when the target starts up his speeder. Some Demolitionists enjoy the thrill of combat as much as any other Hired Gun. However, they favor flame projectors, grenade launchers, and missile tubes—anything that creates a large blast. 

[P]The work of a Demolitionist is extremely dangerous, as a single misstep can spell doom for the character (and anyone unfortunate enough to be in the general vicinity). In order to succeed, a Demolitionist must be able to keep a clear head and focus on his work, even as blaster bolts fill the air around him. As such, most Demolitionists are adept at staying cool in the most nerve-wracking situations. 

[P]In order to put their skills to the greatest use, Demolitionists must have an understanding of the principles of construction, as well as knowing how to construct their explosive devices. Both of these are where some skill with Mechanics becomes important. By knowing how a machine operates, or the load-bearing points of a structure, a Demolitionist can determine where to place explosives for the greatest effect. Similarly, Demolitionists know how to get the most from their tools, creating larger than expected explosions or causing devastating chain reactions. Demolitionists can use their creative talents for more than sheer destruction, and can usually be counted on to find an inventive route out of a dangerous situation. Of course, sometimes that plan is even more dangerous than the original threat. 

[P]For many groups, having a Demolitionist around is both a blessing and a curse. Demolitionists are very effective both in combat and in any job benefiting from sabotage. However, it is far from unheard of for Demolitionists to cause unintended collateral damage when things go really wrong. Fortunately, experienced Demolitionists rarely make mistakes (even if, in their profession, many mistakes tend to be final). Most individuals operating on the fringe understand that theirs is a life of danger, and think that the benefits of partnering with a skilled Demolitionist outweigh the added risk. Still, some grow weary of keeping a constant eye on their ally lest he get carried away in his destructive interests.', NULL, '["COMP","COOL","MECH","SKUL"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["PWRBLST","GRIT","SELDETON","STEADYNERVES"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["TOUGH","TIME2GO","PWRBLST","GRIT"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["ENDUR","TIME2GOIMP","STEADYNERVES","RAPREA"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":3,"cost":20,"talents":["IMPDET","PWRBLST","GRIT","SELDETON"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["IMPDETIMP","DEDI","MASGREN","SELDETON"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":false,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":false}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('DOCTOR', 'Doctor', '[H4]Doctor — The Gift of Healing[h4]
Of all the types of Colonists who come to the Outer Rim, Doctors probably have the easiest time finding employment. They are in high demand almost anywhere they go. Unfortunately, most of what they are asked to do involves patching up the wounds of the worst kind of beings. 

[P]The Doctor adds [B]Cool, Knowledge (Education), Medicine,[b] and [B]Resilience[b] to his Career skills. If this is the character''s starting Specialization, he may choose two of these skills and gain one free rank in each, without spending starting experience. With these skills, a Doctor brings not only healing and the treatment of illnesses with him, he brings a broad spectrum of knowledge and a solid persona in the face of adversity. 

[P]Most Doctors trade their healing talents for a chance to see more of the galaxy than their time in medical school ever allowed. Their overall motives can be as varied as those of any being, yet they tend to share a common instinct to heal where there is harm. While many will simply take up residence with whatever lord, corporation, or boss will hire them, other Doctors will find a way to get out into the larger galaxy, both to bring help to those in need and to experience life in some fashion. 

[P]A Player Character Doctor is likely to be considered a kind of "combat medic" for the group; this isn''t a bad thing at all, and the role will make him very popular. At the same time, a Doctor can often help with broader issues of understanding or finding things out, especially if there isn''t a Scholar in the group.', NULL, '["COOL","EDU","MED","RESIL"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["SURG","BACT","GRIT","RESOLVE"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["STIMAP","GRIT","SURG","RESOLVE"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":2,"cost":15,"talents":["SURG","GRIT","BACT","PRESPNT"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":3,"cost":20,"talents":["STIMAPIMP","NATDOC","TOUGH","ANAT"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":4,"cost":25,"talents":["STIMAPSUP","MASDOC","DEDI","DODGE"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":false,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('DRIVER', 'Driver', '[H4]Driver — The Need for Speed[h4]
Pilots are great for traveling from one system to another, but it''s the Drivers that move beings around once they hit dirt-side. While nearly anyone can manage the basics of a ground vehicle or a speeder, a Driver is priceless when the blaster bolts start flying or the weather turns particularly nasty. It''s one thing to know how to go forward and back and how to apply the breaks. It''s another thing entirely to know how far one can flip a speeder over to one side without stalling while skirting the wall of a canyon, swerving through rocky outcroppings and avoiding a hail of plasma fire from the swoop gang that''s chasing the group.

[P]Drivers understand the machines they operate, and they are exceptionally skilled with nearly anything that moves from one place on a planet to another, typically demonstrating some higher level of style or finesse. 

[P]In addition to the skills that round out an Explorer, Drivers have access to [B]Cool, Gunnery, Mechanics,[b] and [B]Piloting (Planetary)[b] as their bonus career skills. If this is the character''s starting specialization, he may choose two of these skills and gain one free rank in each without spending starting experience. As always, remember that no starting skill may have higher than two ranks. 

[P]Drivers are highly valued almost anywhere they go. Companies, military and security units, governments, and criminal factions all have a regular need for those who can transport personnel and goods over a planet''s surface. Additionally, more than a few planets in the Outer Rim have traditions of racing of one style or another, and Drivers are naturals for being able to enter such competitions and walk away with a decent purse. Naturally, this depends on their skill and their ability to avoid being killed by other Drivers. 

[P]An Explorer with a Driver specialization is a natural fit for almost any Player Character group. His basic skill set as an Explorer is already helpful, and his talents for moving the group around on a planet automatically make him exceedingly valuable. This is especially true when the inevitable situation arises demanding a quick getaway under a hail of blaster fire.

 [H4]Driver - Steady at the Wheel[h4]
On or above the ground, the Driver makes himself a part of the machine and does things no designer ever put into the specs. Most are good at keeping thier machines going, which is a good thing considering how much they abuse their toys.
[P]
Drivers have the additional starting career skills of [B]Cool, Gunnery, Mechanics,[b] and [B]Piloting (Planetary)[b]; when this is a PC''s first specialization, the player may choose two of these skills in which to gain free rank. Mastery of his machines is a primary focus for a Driver. So many things can go wrong on a planet, especially when piloting a vehicle at insane speeds; being prepared for the worst is also a major part of training for most Drivers.
[P]
Most Drivers are well aware they never get the glory or thanks a starfighter pilot does, but it rarely matters. The bite of atmosphere on the wings or the feel of every bump and groove on the road speaks to them in ways the vacuum of space never could. The sheer variety of vehicles a Driver can control on a planet is a huge draw, each representing yet another opportunity to push a machine to its limit and beyond.
[P]
Within the Alliance, Drivers are highly valued, both for thier capacity to get the most out of the limite planetary combat vehicles avalible as well as for their knack for keeping such machines in one piece (or at least limited number of pieces). In most casesm commanders in the Rebellion know to give a Driver a destination and a goal, and then to get out of the way and let him figure out the best way to get there and get it done.', NULL, '["COOL","GUNN","MECH","PILOTPL"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["FULLTH","ALLTERDRIV","FINETUN","GEARHD"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["GRIT","SKILLJOCK","RAPREA","GRIT"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["FULLTHIMP","TRICK","FINETUN","TOUGH"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["DEFDRI","SKILLJOCK","NATDRIV","GEARHD"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":false},{"right":false,"down":true,"left":false,"up":true}]},{"index":4,"cost":25,"talents":["FULLTHSUP","FULLSTOP","MASDRIV","DEDI"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('DROIDTECH', 'Droid Tech', '[H4]Droid Tech — Creating Sentience[h4]
Droids are prevalent across the galaxy, from the shining spheres of the Core to the dingy backwater worlds far from the center''s light. To most inhabitants of the galaxy, droids are little more than particularly complex tools. However, some organic sentients find a kinship with these mechanical beings, seeing a spark of life in them beyond their shells and circuitry. Whether or not they treat the droids around them as mere objects or as sentient beings. Droid Techs possess an unparalleled skill at inventing, repairing and dealing with droids.

[P]Technicians who become Droid Techs gain access to a wealth of abilities that make them better at creating, repairing and directing droids. On the edges of society, droids often constitute much of the labor force due to their low cost - and for the same reason, these droids are often poorly maintained. A Droid Tech can keep droids functional and organized better than anyone else, whether this means meticulously performing upgrades and customizations on a trusted droid partner or keeping a team of pit droids working at maximum efficiency. Far from official factories and even from well-stocked garages where replacement parts can be found, a Droid Tech can be incredibly valuable.

[P]Droid Techs receive [B]Computers, Cool, Mechanics[b] and [B] Leadership[b] as bonus career skills. If this is the character''s starting specialization, the Droid Tech may choose two of these skills and gain one free rank in each without spending starting experience.

[P]Some Droid Techs are not satisfied to merely maintain mechanical beings, but actually want to create new, unique droids with unprecedented abilities and features. Custom-built droids are not as common as standard models, but they are not especially rare, either. The most skilled Droid Techs can bring extremely complex creations to life, building droids that perform a single task with mechanical precision or versatile models capable of handling any situation the galaxy throws at them. The deep philosophical and ethical ramifications of creating sentient being for a purpose weigh heavily on the minds of a few, of course, but most citizens of the galaxy do not dwell too long on such matters.

[P]In addition to having abilities that facilitate building and repairing droids, Droid Techs are gifted with a knack for convincing droids to actually do things for them. While some droids are well mannered and helpful, others can be ill-tempered, capricious, or even downright cruel - but also too useful to dispense with entirely. Getting difficult droids to work toward the group''s common good can be quite a task, but a skilled Droid Tech is better equipped for this task than anyone else. To this end, in addition to benefiting from a high Intellect, Droid Techs might also find a high Presence characteristic and ranks in the Leadership skill useful. These have the added benefit of making it easier to deal with organic beings - though some Droid Techs prefer to avoid dealing with organics entirely.', NULL, '["COMP","COOL","LEAD","MECH"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["MACHMEND","HIDD","SPKBIN","GRIT"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["DEFTMAKER","EYEDET","GRIT","SPKBIN"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["GRIT","SPKBINSUP","SPKBINIMP","HIDD"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":false,"up":true}]},{"index":3,"cost":20,"talents":["REDUNSYS","MACHMEND","SPKBIN","DEFTMAKER"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":4,"cost":25,"talents":["EYEDET","REROUTEPROC","DEDI","MACHMEND"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('ENFORCER', 'Enforcer', '[H4]Enforcer — Ruthless Thugs[h4]
Enforcers know that achieving results does not always require violence—sometimes the threat of it is enough. Unlike other Hired Guns, Enforcers focus on social interactions as much as combat. They can handle themselves in a fight, to be sure, but prefer to accomplish their objectives through savvy, intimidation, blackmail, and straightforward threats. If they need to fight, however, they can brawl with the best.

[P]Enforcers receive [B]Brawl, Coercion, Knowledge (Underworld),[b] and [B]Streetwise[b] as additional career skills. If this is the character''s starting specialization, he may choose two of these skills and gain one free rank in each, without spending experience. While most Hired Guns focus almost exclusively on combat, Enforcers have a focus in intimidation and both learned and instinctual criminal knowledge. Although they have access to Brawl and other combat skills, for the most part Enforcers are not mindless thugs, but canny operators well-versed in the ins and outs of the criminal underworld. When it comes to navigating this world, few are as knowledgeable or adept as Enforcers. Even when visiting a new planet, Enforcers adapt quickly, picking up instinctively on subtle cues and local slang. 

[P]In most criminal organizations, Enforcers fill the dual role of hired muscle and the "face" of a criminal organization. The Enforcer brings a criminal syndicate''s message to the streets, then ensures that message is followed (and punishes those who stray). Enforcers should have no trouble finding work, whether on the uncivilized worlds of the Outer Rim or in the shady underworlds of the Core planets. Enforcers are a natural fit for organized crime syndicates, where they collect debts and ensure everyone shows the proper respect and deference to bosses and leaders. Many Enforcers practice a certain subtlety, avoiding police forces while enforcing the rules of gangs and criminal organizations. 

[P]While most Enforcers have a fondness for violence, they also display a degree of self-control. Violence is a tool in the Enforcer''s arsenal, and not an end in itself. Unlike some Hired Gun characters, an Enforcer is more likely to try words before violence, though these words may be laced with venom and the threat of imminent violence. However, an Enforcer must always be ready to fight. 

[P]In a group, Enforcers can fulfill much the same combat role as other Hired Guns, but can also take the lead in negotiations and social interactions. With their Knowledge (Underworld) and Streetwise skills, Enforcers can act as guides when the group delves into the criminal underworld, a realm as dangerous for the unprepared as any natural environment. A savvy Enforcer can actually help the group to avoid unnecessary fights by knowing what to say during tense negotiations with dangerous criminals. Enforcers are more likely to take on a social interaction role than some other Hired Guns, since their skills can be put to use negotiating jobs, finding work, and managing social encounters.', NULL, '["BRAWL","COERC","UND","SW"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["TOUGH","INTIM","FEARSOME","STRSMART"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["DURA","STUNBL","NATENF","TALKTALK"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["INTIM","DEFSTA","TOUGH","LOOM"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":false},{"right":false,"down":true,"left":false,"up":true}]},{"index":3,"cost":20,"talents":["SECWIND","STRSMART","WALKWALK","INTIM"],"directions":[{"right":true,"down":true,"left":false,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":false},{"right":false,"down":true,"left":false,"up":true}]},{"index":4,"cost":25,"talents":["FEARSOME","DEDI","BLA","FEARSOME"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('ENTREPRENEUR', 'Entrepreneur', '[H4]Entrepreneur — The Burden of Vision[h4]
Entrepreneurs know that there is only one thing worth investing in—the future. Entrepreneurs are not unlike explorers in the world of business; they want to be the first to open up new markets, to revolutionize industrial practices, or to create new service industries people hadn''t realized they needed, but once sampled, cannot live without. 

[P]Entrepreneurs receive [B]Discipline, Knowledge (Education), Knowledge (Underworld),[b] and [B]Negotiation[b] as additional career skills. If this is the character''s starting specialization, he gains one free rank in each of two of these skills of his choice, without spending experience. While the Entrepreneur is willing to bully, charm, or mislead others to achieve his ends, he prefers to rely on negotiations, bringing to bear facts, graphs, and projections for the future. In this way the Entrepreneur is similar to the Scholar. However, unlike Scholars, the Entrepreneur operates under the assumption that every problem can be overcome with a big enough credit stick. 

[P]Entrepreneurs may be free with their money, but they are never wasteful, and they are always looking for ways to cut costs, even if it skirts regulations. Most savvy businesspeople know that if one only plays by the rules, then one can only ever be as successful as the rules allow. Since the rules are usually written by the established corporations the Entrepreneur competes against, he believes the rules exist solely as a means to restrict progress, stifle innovation, and suppress competition. In short, rules were made to be broken. Even the most upstanding businessperson occasionally contracts operatives for industrial espionage or corporate intelligence gathering, and even if he morally objects to that behavior, he needs to know how to defend against it. 

[P]It is said that a sucker is born every second, and the Entrepreneur takes great pains to make certain he is never one of them. In all of his dealings, the Entrepreneur must remain vigilant against conversational traps laid by opponents during delicate negotiations. Preparedness is always a part of the plan, so that risk is mitigated and no circumstances result in absolute failure. 

[P]Every group can benefit from counting an Entrepreneur among its number. Their ability to negotiate a favorable deal in any number of circumstances, and the resources at their disposal, make Entrepreneurs invaluable members of the team. They make excellent leaders, and any party who allows an Entrepreneur to negotiate on its behalf will be pleased with the results. The Entrepreneur can also act as team quartermaster, outfitting the group with specialized, hard-to-find equipment with little notice, and both his pool of contacts and credit pouch are deep enough to keep the party informed on almost any subject.', NULL, '["DISC","EDU","NEG","UND"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["SOUNDINV","PLAUSDEN","RAPREC","GRIT"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["RAPREC","WHEEL","SOUNDINV","WHEEL"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":false},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":2,"cost":15,"talents":["GREASE","THROWCRED","BOUGHT","SOUNDINV"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["SOUNDINV","TOUGH","MASMERC","KNOWSOM"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":false},{"right":true,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["NATMERCH","INTENSFOC","DEDI","SOUNDINV"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('EXECUTIONER', 'Executioner', '[H4]Executioner — Dealing Efficient Death[h4]
Seekers often focus on survival in hostile settings where they must rely solely on their own abilities. Such self reliance can also be reflected in their combat abilities, as each shot or strike must end a battle as swiftly as possible. Merely wounding or dissuading a foe is not sufficient in these cases, as often only one party can leave the encounter alive. Executioners embody this focus on precise lethality. Many become feared across systems for their effective means of eliminating any threat that requires removal. Determining which threats deserve their deadly and personal attention, though, can make for complex judgment calls. Such decisions and the methods by which they render them can also lead Executioners down the path to the dark side.
[P]Executioners are perhaps the embodiment of the Seeker career as apex predator, and they excel at the art of death. While other careers and specializations can produce effective fighters. Executioners are more concerned with maximizing the damage they inflict to ensure a quick, definitive end to their conflicts. Given their emerging connection to the Force there are few who can match these lethal characters'' ability to achieve this goal.
[P]Executioners receive [B]Discipline[b], [B]Melee[b], [B]Perception[b], and [B]Ranged (Heavy)[b] as additional career skills, reflecting their deadly and efficient application of violence. Characters who select this as their starting specialization may choose two of these skills and gain one free rank in each without spending starting experience.
[P]Others might view Executioners as brutal killers, but this is a simplistic view. Killing is often the outcome of combat, but Executioners might attempt to avoid conflict altogether as their aim is only for a fatal end for their target. This could even mean a target is eliminated by long range fire or a decisive lightsaber strike before even becoming aware of any danger. When eliminating one saves hundreds of others or frees entire villages from suffering, many Executioners see their work as perhaps distasteful, but certainly necessary.
[P]Executioners are not always grim, dispassionate assassins, though many are driven by intellect rather than emotion. Some may view their calling as a righteous one, celebrating each threat they remove before it can harm others. Others might see each lethal act as a step toward redemption for past sins. Inflicting death should never be an easy act, however. Those who trivialize it or become too emotionally attached to their goals are at risk of becoming enthralled by the dark side of the Force—which some Executioners might not realize until far too late.', NULL, '["DISC","MELEE","PERC","RANGHVY"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["GRIT","QUICKST","TOUGH","QUICKDR"],"directions":[{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["MINDMAT","HUNTERQUARRY","GRIT","LETHALBL"],"directions":[{"right":true,"down":true,"left":false,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":false},{"right":false,"down":true,"left":false,"up":true}]},{"index":2,"cost":15,"talents":["LETHALBL","HUNTQIMP","QUICKST","PRECAIM"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["TERRKILL","PRECAIM","MARKDEATH","DEATHBLOW"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["LETHALBL","ESSENKILL","FORCERAT","DEDI"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":false}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('FIGUREHEAD', 'Figurehead', '[H4]Figurehead — Charismatic Leaders[h4]

Figureheads generally come from civilian backgrounds and aren’t necessarily a part of the Alliance Military’s chain of command. They rely on their reputations, political connections, and charisma to accomplish their goals. Though their aims might not align perfectly with those of the other Commander careers, the respect they command due to their political legacies ensures that they continue to be a motivating factor in both political and military circles within the Rebel Alliance. Examples of Figureheads in the Rebel Alliance include Mon Mothma and the late Bail Organa, as well as his adopted daughter, Princess Leia Organa. 

[P]Figureheads receive [B]Cool, Leadership, Negotiation,[b] and [B]Knowledge (Core Worlds)[b] as additional career skills. If this is the character’s starting specialization, the player may choose two of these skills and gain one free rank in each without spending experience. Many Commanders focus their social aptitudes on skills that help them get people to do what they want, such as Coercion. Figureheads, on the other hand, get what they want through subtle manipulations, preferring to persuade those under their command to do what must be done.

[P]Much of a Figurehead’s repertoire consists of personal fortitude, as bearing the hopes and fears of their people is a Figurehead’s primary focus. Cool is especially important, for it allows a Figurehead to gain the trust and admiration of subordinates. Figureheads’ demeanor must inspire those who admire them, allowing their followers to overcome their personal qualms—including fear—in order to strike a blow against the Galactic Empire. Whether this inspiring quality applies to a Figurehead’s physical appearance depends on the character’s personal style; many Figureheads have turned their scars and the wounds they’ve suffered into inspirational messages all their own.

[P]Figureheads who take a more active role in resisting the Empire''s oppression often do so through leadership and inspiration. The confidence and know-how of a trained leader is much more convincing under fire than good looks and a pithy slogan. Seeing action in combat also serves to bolster a Figurehead’s reputation within the military, as Figureheads not only know how to “talk the talk,” but to “walk the walk” as well.

[P]As many Figureheads got their start in the political arenas of the Core Worlds, it’s no surprise that most of them know a thing or two about where they’ve come from. Not only do they have extensive knowledge of Core World political systems—including those of the now-defunct Republic—but they also have information about which Core Worlds systems are more or less opposed to the Empire. Such information can be valuable when deciding which systems to approach for help or determining where a group of Rebels in a pinch might be able to seek refuge.', NULL, '["COOL","CORE","LEAD","NEG"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["GRIT","RESOLVE","CONF","COM"],"directions":[{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["COM","INSPRHET","CALMCOMM","GRIT"],"directions":[{"right":true,"down":true,"left":false,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":2,"cost":15,"talents":["COMMPRES","GRIT","INSPRHETIMP","POSSPIN"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":false},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["RESOLVE","CONF","CONFIMP","COMMPRES"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":4,"cost":25,"talents":["INTENSPRE","NATLEAD","DEDI","COMMPRESIMP"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('FORCEADHERENT', 'Force Adherent', '[H4]Force Adherent — Indomitable Believers[h4]

Force Adherents worship the Force and accept its influence over the galaxy.  The Force binds all living things, and those who surrender to this idea are able to reach a level of perception unknown to the common sentient.  Even those without sensitivity to the Force have benefited from this acceptance.  through this belief, force Adherents are capable of overcomming extreme adversity.

[P]The additional acareer skills a PC recieves when taking the Force adherent universal specialization are [B]Melee[b], [B]Discipline[b], [B]Knowledge (Lore)[b], and [B]Vigilance[b].  Finding purpose and strength in their belief in the Force, such PCs are bastions of belief in these dark times.

[P]Belief in the Force is most commonly associated with the Jedi legends, but multiple cultures throughout the galaxy recognize the same phenomenon.  For example, the Lasat whom many believe to be extinct, worship the Ahsla, a personification of the light side of the Force, and acknowledge the Bogan, a personification of the dark side of the Force.  Gand findsmen utilize techniques that outsiders view as directly related to the Force as well.

[P]For sentients seeking purpose, turning to the Force can provide guidance. Whether their seeking is triggered by a general sense of meaninglessness or a specific personal loss, the idea of the Force is a reassuring constant.  for these individuals, the rituals, practices, and holy places of Force worship give direction.  Making pilgrimages to established Force locations like Jedha, for instance, is frequently an integral part of these Force Adherents'' journeys.  However not all force Adherents come to their worship for meaning or guidance.

[P]To those who have seen or heard about the incredible deeds of Force-users, such as the Jedi, worship of the Force tantalizes with the possibility of unlocking that strength.  Unfortunately for those who seek this power, not all individuals are sensitive to the force.  Regardless, those who pursue Force worship earnestly find a strength they can unlock within themselves.

[P]By developing their understanding of the Force, Force Adherents become more in tune with the galaxy.  Even if they cannot tap into the Force directly, they learn to listen to the life around them; where most sentients hear only noise, Force Adherents hear the spiritual call and response of the entire range of beings in the area.  In addition, Force Adherents meditative contemplation and training allow them to push their bodies past normal limitations.  an unwavering belief in the providence of the Force can even eliminate fear of failure, because all is as the Force wills it.

[P]Force Adherents'' worship and training make them more-than-capable , and their knowledge of the Force is practically unrivaled. Due to their enhanced perceptions and reflexes, they are capable of anticipating opponents'' actions in combat.  They excel at evading attacks and delivering precise blows.  challenges to Force Adherents are challenges to the flow of the Force itself.', NULL, '["DISC","LORE","MELEE","VIGIL"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["RESOLVE","DISCIPLEOFLORE","GRIT","PUSHASIDE"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["DISCIPLEOFLORE","ASFORCEWILLS","PRECSTR","EXTENDREACH"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["CONF","HARDHD","CONF","DODGE"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":false},{"right":true,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["DISCIPLINEDSOUL","GRIT","DODGE","RESOLVE"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["FORCEWILL","SUPREF","SIXSENSE","DEDI"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":false}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('FORCESENSITIVEEMERGENT', 'Force Sensitive Emergent', '[H4]Force Sensitive Emergent[h4]
The Rebel Alliance stands for the restitution of the values and structures that were set aside during the rise of Emperor Palpatine. As Force users have been among those persecuted under the Imperial regime, many of them sympathize with the goals of the Rebellion. As a result of this, one of the Rebel Alliance''s most underestimated assets is a cadre of amateur Force-sensitives who could prove decisive in the struggle against the Empire. Or at least, they would be if they were properly identified and trained. 

[P]Within the ranks of Rebel organizations, Force-sensitives are safe from the Empire and have access to one of the few remaining societies in the galaxy that still openly acknowledges and encourages an understanding of the light side of the Force. While the Jedi Order has been shattered by the Empire, there are many within the Rebel Alliance who remember them and their teachings. While few Force-sensitives are ever fortunate enough to receive training from an actual Jedi, at least in the Alliance they can learn about the Order''s traditions and techniques from sympathetic sources. 

[P]While they were regarded by the citizens of the galaxy as a benevolent order dedicated to the promotion of peace and harmony throughout the galaxy, the Jedi Knights also had a well-deserved reputation as fierce warriors, particularly when it came to close-quarters fighting with their signature weapon, the lightsaber. While few Force-sensitives hope to develop such prowess, or come to possess a lightsaber of their own, they do tend to develop some skill at martial arts. In fact, a little training in hand-to-hand combat is recommended, both as a method of self-protection and because the associated regimen is said to help put one in the right frame of mind to contemplate the Force. 

[P]The Force-Sensitive Emergent specialization does not have any career skills associated with it. When a character purchases this specialization, he automatically receives a Force rating of 1 (if he did not already have it). However, if the character already has a Force rating of 1 or higher, it does not improve when he purchases the Force-Sensitive Emergent specialization. 

[P]Just like other specializations, the Force-Sensitive Emergent specialization can be taken at character creation or at any subsequent point. This represents the fact that some Force-sensitives do not become aware of their potential until a relatively late stage of their lives.', NULL, '[]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["INSIGHT","UNCANSENS","INDIS","GRIT"],"directions":[{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["UNCANREAC","TOUGH","SLEIGHTMIND","SLEIGHTMIND"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":false}]},{"index":2,"cost":15,"talents":["UNCANSENS","UNCANREAC","GRIT","INDIS"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":3,"cost":20,"talents":["TOUGH","SENSDANG","TOUCH","BAL"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["INVIG","FORCEWILL","FORCERAT","DEDI"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('FORCESENSITIVEEXILE', 'Force Sensitive Exile', '[H4]Force Sensitive Exile[h4]
The Jedi are gone, the vast majority hunted down and destroyed by the Emperor and his minions. If any survive, they do so in hiding at the farthest edges of the galaxy. The Galactic Empire regards the ability to use the Force as a crime punishable by the harshest measures. In a few short decades, most of the galaxy has forgotten the Jedi, and dismissed the Force as an ancient religion. For many, this is by far the safest option. 

[P]However, although the Empire has purged the Jedi, not all who use the Force have been hunted down and killed. The galaxy is simply too large to track down every Force-sensitive being, and the Emperor''s infamous Order 66 and the hunts that followed primarily concerned themselves with pursuing true Jedi and their descendants and allies. In the hidden corners of the galaxy, those who can touch the Force remain hidden, hunted, and outcast... but alive. 

[P]The Force Sensitive Exile specialization does not have any career skills associated with it. However, when a character purchases this specialization, he automatically receives a Force rating of 1, if he did not already have it. If he already has a Force rating of 1 or higher, it does not increase. 

[P]Although technically someone is Force sensitive from birth, it can take a great deal of time for him to realize he has this power. For this reason, the Force Sensitive Exile specialization can be taken during character creation or at any later point, just as any other specialization. 

[P]The Force Sensitive Exile is not just any Force-sensitive being; he is one who survived the purges. He may have been a young Padawan or even a minor Jedi who managed to flee the Empire and hide. He may also have been a child, hidden by friends or family. Whatever the case, he''s spent the last decades in a hostile galaxy. His formal training is likely to be limited or even non-existent, and he uses his powers carefully or not at all. Even his mastery of the Force is shaped by his experiences—his powers focus more around concealment and control than flashy displays of ability.', NULL, '[]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["UNCANSENS","INSIGHT","FORAG","UNCANREAC"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["CONV","OVEREM","INTENSFOC","QUICKDR"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":true}]},{"index":2,"cost":15,"talents":["SENSDANG","SENSDEMO","BAL","TOUCH"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":3,"cost":20,"talents":["STRSMART","UNCANSENS","UNCANREAC","STRSMART"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["SIXSENSE","FORCERAT","DEDI","SUPREF"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('FRINGER', 'Fringer', '[H4]Fringer — Discovering Possibilities[h4]
Part negotiator, part astrogator, and savvy in the ways of the galaxy beyond the Core Worlds, the Fringer is a jack-of-all-trades. He focuses on knowing how to find what he needs and how to get where he needs to go. He''s got the gift of gab when it''s time to talk, and the awareness and reflexes to maneuver away when it''s time to run. 

[P]The additional Career skills for a Fringer are indicative of his diversified nature: [B]Astrogation, Coordination, Negotiation,[b] and [B]Streetwise[b]. If this is the character''s starting Specialization, he may choose two of these skills and gain one free rank in each, without spending starting experience. Fringers are skilled navigators and rugged survivalists. 

[P]Many Fringers are excellent pilots, some rivaling even Smugglers in terms of talent. They are also highly prized for their ability to navigate ships through the unknown ranges of the Outer Rim. Fringers can also be tough, wiry, and nimble, surprising any would-be assailant with their ability to avoid getting hit and avoid getting caught. 

[P]A Player Character Fringer stands a good chance of being either the primary or secondary pilot for a group; he''ll certainly be the likely choice for handling astrogation duties. He may also be the one the group turns to when it comes to dealing with employers, or finding a job in the first place. If someone needs to go into a starport or town to handle business, the Fringer should definitely be a part of that excursion.', NULL, '["ASTRO","COORD","NEG","SW"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["GALMAP","STRSMART","RAPREC","STRSMART"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["SKILLJOCK","GALMAP","GRIT","TOUGH"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":false},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["MASSTAR","DEFDRI","RAPREC","DURA"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["RAPREC","JUMP","GRIT","KNOCK"],"directions":[{"right":true,"down":true,"left":false,"up":false},{"right":true,"down":true,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":4,"cost":25,"talents":["DEDI","TOUGH","DODGE","DODGE"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('GADG', 'Gadgeteer', '[H4]Gadgeteer — Connoisseur of Tech[h4]
Considering how often a single Bounty Hunter finds himself faced with terrible odds (more often than not, an acquisition has friends or employees who work hard to protect him), it''s not surprising how many specialize in high-tech gear and weapons. The Gadgeteer excels at presenting himself as a one-person battle force, at least for a short time. Using both the latest tech and his own personally-modified gear, a Bounty Hunter with this specialization can be hard to stop.
 
[P]Gadgeteers add the skills [B]Brawl, Coercion, Mechanics,[b] and [B]Ranged (Light)[b] to their repertoire of class skills, making them ranged combat experts, effective technicians, and masters of surveillance. If this is the character''s starting Specialization, he may choose two of these skills and gain one free rank in each, without spending starting experience. Gadgeteer talents lean heavily towards gear use, taking down targets, and adapting to tough situations. 

[P]Gadgeteer-specialized Bounty Hunters are in many ways the ultimate hybrid of tech expert and combatant; for smaller groups, this may be a perfect choice. Gadgeteers—especially those that are operating as Independent Bounty Hunters—have little trouble signing on for nearly any job. After all, the credits they need for that next nifty piece of tech have to come from [I]somewhere[i].', NULL, '["BRAWL","COERC","MECH","RANGLT"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["BRA","TOUGH","INTIM","DEFSTA"],"directions":[{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["SPARECL","JURY","POINTBL","DISOR"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":false},{"right":false,"down":true,"left":false,"up":true}]},{"index":2,"cost":15,"talents":["TOUGH","ARM","NATENF","STUNBL"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":false},{"right":false,"down":true,"left":false,"up":true}]},{"index":3,"cost":20,"talents":["JURY","TINK","DEADACC","STUNBLIMP"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":false},{"right":false,"down":true,"left":false,"up":true}]},{"index":4,"cost":25,"talents":["INTIM","DEDI","ARMIMP","CRIPV"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":false},{"right":false,"down":false,"left":false,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('GAMBLER', 'Gambler', '[H4]Gambler — The Wild Card[h4]
When the chips are down, the Gambler holds all the cards. Like the devious Thief, the Gambler loves misleading others and taking big risks to profit. Like the clever Trader, the Gambler has a knack for convincing others to part with their valuables for next to nothing. The Gambler has a unique variety of tricks up his sleeve to deceive or misdirect opponents, keeping them guessing as to whether he has a winning or losing hand. However, the Gambler knows that there is no such thing as a losing hand; winning is all about knowing how to play the cards that have been dealt. 

[P]The Gambler knows how to play all the most popular games of chance; however, he also recognizes there is far more to winning than just knowing the rules. His ability to identify subtle clues in the body language, mannerisms, voice patterns, and behavior of his opponents gives the Gambler all the information he needs to decide when to make his move. The Gambler prides himself on being unpredictable, denying his opponents any hints to his intentions with his stone-cold expression. Whether the situation is a game of sabacc, betting on Podraces, or talking a thug out of blasting his companions, the Gambler has a strategy, and rarely the one people expect. 

[P]The list of a Gambler''s bonus career skills clearly shows his strong suit lies in sleight of hand and trickery: [B]Computers, Cool, Deception,[b] and [B]Skulduggery[b]. If this is the character''s starting specialization, he may choose two of these skills and gain one free rank in each without spending additional starting experience. By doubling down on skills that allow him to keep his opponents guessing, the Gambler ensures the odds are always stacked in his favor. As a competent liar, the Gambler is not above using a skifter to win a hand if the stakes are high enough. 

[P]A Gambler may not always look like much, but looks can be deceiving. The Gambler is an excellent actor, always able to project an air of calm confidence so he seems as cool as carbonite even when he is as tense as an Alderaanian on an ImpStar. A great Gambler knows to never count his credits at the table, so to speak, but sometimes playing hurt can throw his opponents. Some Gamblers love baiting their opponents by looking vulnerable just so they can gloat while raking in the pot. A fool and his money are soon parted, and the Gambler is always happy to oblige. 

[P]The Gambler is a fantastic specialization for playing a number of character types in a variety of settings. A player could create an aboveboard, aristocratic Core dweller participating in high-stakes betting just for thrills; a suave, small-time card shark flitting about the Colonies scamming amateur players; or a downtrodden Smuggler dropping his last fifty credits into the pot trying to win enough to repair his ship. He is not limited to playing games, however, as a Gambler fits into any setting where fists full of credits or unbelievable thrills are up for grabs. The negotiation skills of the Gambler could make him the brains of a trade or smuggling operation. A Thief may even supplement his abilities with Gambler to mingle among high society and case locations for upcoming jobs.', NULL, '["COMP","COOL","DECEP","SKUL"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["CONV","GRIT","TOUGH","UPANTE"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["GRIT","SECCHANCE","DEDI","DOUBLEORNOTHINGSUP"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":false}]},{"index":2,"cost":15,"talents":["SECCHANCE","CONV","FORTFAVORBOLD","NATROG"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":true}]},{"index":3,"cost":20,"talents":["UPANTE","UPANTE","CLEVERSOLN","SECCHANCE"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["DOUBLEORNOTHING","SMOOTHTALK","NATNEG","DOUBLEORNOTHINGIMP"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('GUNNER', 'Gunner', '[H4]Gunner — Always on Target[h4]
For the Gunner, the output of a vehicle or ship weapon is the ultimate expression of projected power. He sees mastery of such weapons as a way for a single person to show the Empire what it means to fight for freedom and justice, and to do so to great effectiveness. He also sees his role as the defender of all who ride with him in whatever vehicle he''s crewing. 

[P]Gunners gain [B]Discipline, Gunnery, Ranged (Heavy),[b] and [B]Resilience[b] as additional career skills; they get a free rank in two of these if this is their first specialization. Gunners are often faced with terrifying odds or unknown threats requiring nerves of steel. When their positions are overrun, hand-to-hand fighting is often the only choice they have. Larger blasters and similar ranged weapons are also often of interest to the Gunner. 

[P]Whether the Gunner is laying down a field of fire from the door of a transport ship in a hot landing zone or firing pinpoint volleys at a star cruiser''s shield generators, he is more than comfortable with the idea of possessing large amounts of firepower. He knows the value of what he does, and the sheer thrill of unleashing so much devastation with each pull of the trigger is very satisfying. The resultant explosion of an enemy target is a payoff worth far more than any moment of glory. 

[P]Proficient Gunners are a true asset in the Alliance, and the best ones are usually assigned to the most important defensive posts, assault vehicles, and ships. In most battles with the Empire, every single shot counts. It''s the Gunner''s job to make sure it counts heavily and with great purpose.', NULL, '["DISC","GUNN","RESIL","RANGHVY"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["DURA","GRIT","OVERDEF","DEPSHOT"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["TOUGH","BRA","SPARECL","TRUEAIM"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":2,"cost":15,"talents":["DURA","ENDUR","JURY","OVERDEF"],"directions":[{"right":true,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":3,"cost":20,"talents":["TOUGH","ENDUR","BRA","EXHPORT"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":4,"cost":25,"talents":["HERO","JURY","DEDI","TRUEAIM"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('GUNSLINGER', 'Gunslinger', '[H4]Gunslinger — The Quick Draw[h4]
The Outer Rim is an immense region of countless worlds, sometimes lawless but always dangerous. Life on the galactic frontier teems with vicious creatures and heartless criminals who would not think twice about gunning down innocent civilians. Bred from conflict and necessity, this is the galaxy where the Gunslinger lives and breathes. He is the best there is with a blaster, and he won''t hesitate to show it.

[P]The Gunslinger knows better than most that making a living in the Outer Rim Territories is a constant struggle. He needs to be fast on the draw to stay alive. The Gunslinger and his beloved sidearm are inseparable, but he often carries a holdout weapon when stuck in a hostile, target-rich environment. To face off with a Gunslinger is a dangerous and foolish proposition. 

[P]The bonus career skills for the Gunslinger are [B]Coercion, Cool, Knowledge (Outer Rim),[b] and [B]Ranged (Light)[b], all of which he uses to survive on the fringe. If this is the character''s starting specialization, he may choose two of these skills and gain one free rank in each without spending additional starting experience. The Gunslinger has lethal aim and an attitude to match, making him one of the deadliest beings in the Outer Rim. 

[P]A Gunslinger often has a special bond with his favorite weapon. His knack for gunplay often earns him a reputation that puts him at odds with other bandits who want to prove their mettle. This lifestyle is second nature to the Gunslinger, so he knows how to keep his cool when threatened. When some thug sticks a blaster in his face, the Gunslinger doesn''t flinch. He shoots first and skips asking questions. 

[P]The Gunslinger often needs to remain one step ahead of the law, and so he wanders the Outer Rim in search of his next job. The hard life of the galactic frontier is not all gunfights, so the Gunslinger takes on work wherever he can find it. The Gunslinger uses his underworld contacts to secure odd jobs for a variety of criminal groups. Gunslingers also use their piloting knowledge to take on freight or smuggling jobs. 

[P]A Gunslinger character can fill countless roles within a campaign. He might find work onboard a bulk freighter defending crew and cargo from pirates. A Bodyguard might opt to pick up the Gunslinger specialization on the side to improve his ability to defend his spoiled Coruscanti debutante client. A Tapani nobleman taking up pistols in a duel to maintain the honor of his house might also find the Gunslinger specialization invaluable.', NULL, '["COERC","COOL","OUT","RANGLT"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["GRIT","QUICKST","RAPREA","QUICKDR"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["LETHALBL","GRIT","QUICKST","QUICKDRIMP"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":2,"cost":15,"talents":["TOUGH","CALLEM","DODGE","SORRYMESS"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["CONF","LETHALBL","GUNSBLAZING","RAPREA"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["DEDI","SPITFIRE","NATMAR","DEADACC"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":false}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('HEALER', 'Healer', '[H4]Healer[h4]
Consulars are often drawn to their career by a strong sense of compassion. In many, this is expressed by a desire to mitigate bodily harm and cure the sick. A Healer trains to do so, recognizing that helping the individual can be just as important as helping the entirety of galactic civilization. 

[P]Healers gain access to the additional career skills of [B]Discipline, Knowledge (Education), Knowledge (Xenology),[b] and [B]Medicine[b]. If this is the character''s starting specialization, he may choose two of these skills and gain one free rank in each without spending starting experience. 

[P]For some physicians, healing is focused entirely on the problems of the body. They treat injuries with a detached, clinical approach. A Healer, however, is driven by compassion and affinity with the Force. Because of this, a Healer takes a holistic approach toward medicine. Many Healers learn techniques that use the Force to fuel the body''s natural recuperative abilities—sometimes transforming a potentially lethal injury into one that is survivable. They also seek to calm and heal the wounded spirit just as thoroughly as healing the wounded physical form. 

[P]Many Healers have very strong philosophical compunctions against physical violence. As they spend so much of their lives attempting to heal injuries, they can be extremely reluctant to inflict them. Consequently, those who study this specialization exclusively are less likely to gain abilities that are devoted to combat. Some Healers, however, can take the time to develop defensive techniques, believing that dangerous situations are often the ones in which they are most needed.', NULL, '["DISC","EDU","MED","XEN"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["SURG","HEALTRANCE","RAPREC","PHYSICIAN"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["PHYSICIAN","PHYSICIAN","GRIT","HEALTRANCE"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":2,"cost":15,"talents":["HEALTRANCE","GRIT","KNOWHEAL","RAPREC"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":false},{"right":false,"down":true,"left":false,"up":true}]},{"index":3,"cost":20,"talents":["SURG","HEALTRANCEIMP","CALMAURA","TOUGH"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true}]},{"index":4,"cost":25,"talents":["DEDI","NATDOC","FORCERAT","CALMAURAIMP"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":false}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('HEAVY', 'Heavy', '[H4]Heavy — Overwhelming Firepower[h4]
For a Heavy, size really does matter. These characters prefer to use the biggest guns possible, and usually have the physique to match. Heavies are often physically impressive, a necessity for effectively wielding the heaviest man-portable weapons. Heavies are inevitably found at the front in combat, as allies back away and give them space. 

[P]The list of additional career skills for a Heavy consists of [B]Gunnery Perception, Ranged (Heavy),[b] and [B]Resilience[b]. If this is the character''s starting specialization, he may choose two of these skills and gain one free rank in each, without spending starting experience. This straightforward list of skills allows a Heavy to do primarily one thing: wield large, dangerous weapons. From heavy blasters to missile tubes, Heavies favor big, loud, and devastating weaponry. Using such weapons is often punishing for the wielder, and characters must possess great fortitude in order to wield such weapons extensively. A high Resilience skill is often a side effect of the Heavy''s actions, rather than the result of conscious training. Lugging around heavy weapons builds stamina, and simply dealing with the recoil provides a workout. 

[P]Heavies generally approach combat in the most direct way possible—stealth and duplicity are not becoming of a walking arsenal. Similarly, Heavies tend to be very straightforward in their dealings. This bluntness sometimes comes across as a lack of intellect, though few would be brave enough to say so to the Heavy''s face. There may be some truth to the perception that Heavies sacrifice brains for brawn, but as with all generalizations, there are many exceptions. In a galaxy of double-crosses and altered deals, steadfastness and blunt honesty can be seen as virtues. 

[P]While some Heavies may work as independent operators, most find themselves as a permanent addition to a group. Heavies can easily find a place among a mercenary band. Having a Heavy in a group is a great boon. The mere sight of the heavy weapons they carry can ensure that no one hassles them, and a single Heavy—when properly equipped—is easily a match for numerous foes. 

[P]In a Player Character group, a Heavy fulfils a similar role to that of a light battle tank in a military force. Heavies can often deal out enough damage to wipe out entire groups of enemies single-handedly, and are also typically able to absorb a great deal of punishment. Heavies must have a high Brawn in order to wield heavy, cumbersome weapons, which helps them to shrug off damage, and also allows them to wear heavy armor that may be too encumbering for other characters. A Heavy''s skills and talents are narrowly focused, but they make him a master of ranged combat.

    [H4]Heavy — Untold Devastation[h4]
The Empire marches to war with massive machines of death, designed not only to crush their foes but also any hopes of victory they might represent. The Rebel Alliance, for its part, is short on such material. While its starfighters and capital ships are able to directly contend with those of the Empire, the Rebel Alliance must fight most of its ground battles with infantry, supported only by entrenchments and light airspeeders. Many of its operations rely entirely on infantry. To this end, it must have troopers whose expertise and equipment allow them to take down even the most heavily armored targets. Heavies are the Soldiers best suited to carrying and operating these crucial big guns.', NULL, '["GUNN","PERC","RANGHVY","RESIL"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["BURLY","BAR","GRIT","TOUGH"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["BAR","BRA","SPARECL","DURA"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":false},{"right":false,"down":true,"left":false,"up":true}]},{"index":2,"cost":15,"talents":["SIDESTEP","BURLY","HERO","TOUGH"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["BRA","BAR","RAINDEATH","HEROICRES"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":true}]},{"index":4,"cost":25,"talents":["BURLY","DEDI","ARM","HEAVYHITTER"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":false}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('HERMIT', 'Hermit', '[H4]Hermit — Communing with the Living Force[h4]
While most Seekers are often solitary and self-reliant by nature, some go beyond this simple tendency toward reclusion and desire to operate independently. A life isolated from the impositions and irritations of outsiders is instead the goal for them, so that they can develop their abilities and connections to the Force in relative calm. Free from outside distractions, these Hermits can further themselves in ways previously unimaginable to them. Those who can be convinced to rejoin society can be of great value, not only in their use of the Force but also in dealing with wilderness survival and deadly creatures.
[P]For Hermits, solitude is not necessarily a result of abhorring social interactions or lacking any skills with them. Some Hermits might have even sought remote life to escape from outside entanglements. They may have had crushing debts, had bounties placed on their heads, or even deserted from the Imperial military. Hermits who desire seclusion after discovering their nascent Force abilities may use their isolation to more fully concentrate on uncovering the secrets of their mysterious new powers. Meditation can not only help them become more in tune with the Force, but also strengthen their connection with nature and the surrounding wildlife.
[P]Hermits are not only solitary and self-reliant, but also seek to maintain their isolation against intruders and others who would disturb their reclusive existence. Some even hone their ability to avoid others to a great extent, the better to escape unwanted attention. To represent this, Hermits receive [B]Discipline[b], [B]Knowledge (Xenology)[b], [B]Stealth[b], and [B]Survival[b] as additional career skills, allowing them to better develop their connections not only with the Force, but also with local flora and fauna. Characters who select this as their starting specialization may choose two of these skills and gain one free rank in each without spending starting experience.
[P]Despite their previously isolated ways of life, Hermits are powerful additions to groups. When parties are stranded in harsh environments, whether sweltering jungles or barren ice wastelands, Hermits likely feel they are returning to their homes. Many find such locations more relaxing than the intense industry and frantic pace of typical cities especially in Core Systems. Their skills in dealing with these wilderness regions makes them invaluable for ensuring the party''s survival when the characters venture into the wilds.
[P]Hermits'' skills in uncivilized areas also comes into play when facing dangerous animals or untamed creatures the group desires to use as steeds. Living in the wild, Hermits often develop close bonds with their fellow creatures and can form companionships that might last lifetimes. Many of these Seekers use their Force abilities, possibly unconsciously, to strengthen established connections with animals as well as to form new ones.
[P]Despite having lived in isolation for long periods, Hermits are not unprepared for conflict. Most have maintained themselves well, simply in order to survive in an unforgiving wilderness where weather and even local plant life can be as hostile as any sentient enemy. Dealing with dangerous creatures and honing themselves to avoid such attacks can turn Hermits into equally dangerous combatants. Overall, this solitude can build powerful individuals, able not only to thrive in the harshest of environments but also to aid others unprepared for life outside advanced urban settings.', NULL, '["DISC","STEAL","SURV","XEN"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["FORAG","SOOTHTONE","GRIT","ONENAT"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["CONDITIONED","GRIT","MENACE","ANIMALBOND"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["ENDUR","CONDITIONED","SURVFIT","GRIT"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["FORCERAT","ANIMALBONDIMP","HARASS","FORCECONN"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":4,"cost":25,"talents":["GRIT","NATOUT","FORCERAT","SHROUD"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('HOTSHOT', 'Hotshot', '[H4]Hotshot — The Loose Cannon[h4]
Where the Ace Pilot uses hard-won skill, technique, and by-the-book tactics, the Hotshot is naturally gifted, overly aggressive, and makes the rest up as he speeds along. For the Hotshot, risk-taking isn''t just a style of flying, it''s a way of life. You can always depend on a Hotshot to go for it when he sees an opportunity to achieve a goal. There are few things in the galaxy more impressive than watching a Hotshot when everything is going his way, though it''s best to switch channels on the comms, because the only thing a Hotshot likes more than his own flying is bragging about it afterward.

[P]The Rebellion has a nearly endless supply of new Hotshot bush pilots accustomed to racing T-16s on their backwater homeworlds, but very few Hotshot veterans. These courageous freedom fighters prefer improvisation to careful planning, much to their commanders'' chagrin. Those Hotshots whose luck never seems to run out quickly become heroes and legends to the rank and file of the Rebel Alliance. 

[P]Hotshots receive [B]Cool, Coordination, Piloting (Planetary),[b] and [B]Piloting (Space)[b] as additional career skills. If this is the character''s starting specialization, he gains one free rank in two of these skills of his choice, without spending experience. The Hotshot keeps his head in the face of overwhelming odds, and has a great degree of control over his chosen vehicle. Finesse and precision flying, combined with the Hotshot''s unrestrained bravery, mean that Hotshots prefer to go after the toughest or biggest groups of enemies first, diving headlong into the thickest part of the battle. 

[P]The Hotshot is all about taking the big risks, both in combat and in life. He rarely considers the consequences or the alternatives. When he sees a chance, he takes it without blinking. This unpredictable and often irrational behavior, combined with the raw talent and control a Hotshot has in the cockpit, makes him a lethal adversary. Of course, there is no reward without risk, and sometimes the Hotshot risks too much. If not for the support of their allies, most Hotshots would probably have died a dozen times over. 

[P]The Rebellion usually puts Hotshots through their paces in simulators before letting them get into a real fight. However, the Rebels can''t afford to keep their best combat Aces sidelined for long. Command usually assigns Hotshots to X-wing or A-wing squadrons, or to other light, maneuverable vehicles that take full advantage of a Hotshot''s preternatural skill. Veteran Hotshots are usually retired once their value as a symbol eclipses whatever good they might do on the battlefield. High Command often parades them around on low-risk, high-visibility missions, or transfers them to training commands. 

[P]Any group can benefit from the honed dogfighting skills of a Hotshot. However, despite the Hotshot''s predilection for flying into combat ahead of his squadron, he works best when he has a team not far behind, cleaning up whatever enemies the Hotshot misses. A vehicle formation with a Hotshot in the lead usually results in a costly engagement for the enemy, as long as the Hotshot''s luck holds out.', NULL, '["COOL","COORD","PILOTPL","PILOTSP"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["SHORTCUT","HIGHGTRAIN","SKILLJOCK","GRIT"],"directions":[{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["SECCHANCE","GRIT","SHORTCUT","HIGHGTRAIN"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["DEAD","HIGHGTRAIN","GRIT","INTENSPRE"],"directions":[{"right":true,"down":true,"left":false,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":3,"cost":20,"talents":["SECCHANCE","CORSEND","KOITURN","GRIT"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":4,"cost":25,"talents":["DEADIMP","CORSENDIMP","DEDI","SHOWBOAT"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('HUNTER', 'Hunter', '[H4]Hunter[h4]
Far from the civilized parts of the galaxy, there are many predators that can endanger sentient life. Some of these are animals that prey upon anything digestible. Others are malicious and twisted individuals who enjoy a savage and bloodthirsty existence. Hunters are Force adepts who are uniquely capable of tracking, confronting, and slaying these creatures, particularly those who hide in the wilds, far from civilization. 

[P]Hunters acquire [B]Coordination, Ranged (Heavy), Stealth,[b] and [B]Vigilance[b] as additional career skills. If this is the PC''s starting specialization, he chooses two of these skills and gains one free rank in each. These ranks do not cost experience. Hunters need to be able to sneak up on their targets, move through difficult terrain, and be constantly alert to their surroundings. Many hunters train with ranged weapons so that they can strike their targets from far away. 

[P]Most Hunters initially embark upon their careers focused on animal prey. Few, however, engage in this practice out of a desire to prove their mettle or a thirst for blood. Rather, their connection to the Force often lets them differentiate between predators that hunt out of necessity from those that are actively malicious. A Hunter does not normally interfere in the natural cycle of life, but he''s more than willing to restore balance by eliminating a predator that kills needlessly and destroys natural habitats. Sadly, these foul and twisted animalistic intelligences also have their parallels within sentient beings. All too often, a Hunter finds himself hunting intelligent quarry; this can prove to be the most dangerous game of all.', NULL, '["COORD","RANGHVY","STEAL","VIGIL"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["RAPREC","HUNT","EXTRACK","TOUGH"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["TOUGH","EXTRACK","HUNT","UNCANSENS"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":false}]},{"index":2,"cost":15,"talents":["SIDESTEP","KEENEYED","NATHUN","UNCANREAC"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":3,"cost":20,"talents":["RAPREC","SOFTSP","SIXSENSE","RAPREC"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["SIDESTEP","DEDI","INTUITSHOT","FORCERAT"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('IMPERIALACADEMYCADET', 'Imperial Academy Cadet', '[H4]Imperial Academy Cadet — Rebellious Students[h4]

The Empire trains cadets to be effective and unquestioning soldiers.  To its dismay, some of its most promising students are not willing to blindly obey.  For many of the former aspiring Imperial Pilots, Officers, and stormtroopers who have deserted after gaining firsthand exposure to the Empire''s practices, the Empire is an undeniable evil that must be opposed.

[P]The additional career skills a PC receives when taking the Imperial Academy Cadet universal specialization are [B]Knowledge (Warfare)[b],  [B]Leadership[b], [B]Piloting (Space)[b], and [B]Ranged (Light)[b].  Having left their training institutions at some point in their past, these PCs are ready to fight against an Empire they once believed in, but now believe only that it must be overthrown.

[P]To many individuals in these times, the Empire represents stability and order.  It is responsible for having saved them from the Separatists and the traitorous Jedi Order.  The Imperial military, specifically, offers opportunities to serve that body in addition to the promise of patriotic fulfillment, exploration, and power.  For those who haven''t experienced the Empire''s oppression, these can be powerful motivators to join up.  Many adventurous souls daring to escape the inevitability of a life without excitement or advancement have looked to the Imperial academies as a way to venture into the wider galaxy.  Depending on the academy, however, even getting accepted can be a highly competitive affair, in which only the most naturally talented candidates have a chance-unless, of course, a candidate''s family is connected.

[P]Once a cadet is accepted, the glowing veneer of the Empire can begin to flake away.  While cadets have the opportunity to gain knowledge in a variety of fields, the study of warfare is the most heavily emphasized.  a select few are groomed to become pilots, but many only benefit from the combat training to become stormtroopers.  during training, instructors often encourage and even reward peer sabotage in order to foster callous behavior  and direct their charges'' loyalty only to the Empire.  Despite this practice, unyielding cadets occasionally emerge who did not resort to such underhanded tactics and refused to be properly molded during training.  When these cadets come to the attention of their instructors, however, it is not uncommon for them to suddenly vanish.

[P]For some who remain, knowing that their life will consist of following strict orders, regardless of the harm to peaceful civilians, quenches any desire to continue.  after participating in theoretical or training operations to supress unruly citizens, it becomes inpossible for such cadets to ignore these operations in practice.  For those who abandon the military but don''t rebel immediately, the continued abuse they witness can be more than enough to motivate them to join the resistance movement.  A few rebel cells have been known to assist disillusioned cadets in their defections.  After fleeing their academy, former cadets are able to see the transgressions they may not have noticed before joining.

[P]Imperial Academy Cadets are effective agents against the Empire because their training helps them to anticipate and exploit the Imperials'' common tactics.  Any mechanical blueprint a rogue cadet has been exposed to becomes a liability to the Empire.  Any glimpsed prototypes lose their element of surprise, and any protocol learned can be exploited for covert missions.  To disrupt the enemy, one must know the enemy, and these cadets know the Empire all too well.', NULL, '["LEAD","PILOTSP","RANGLT","WARF"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["GRIT","VEHTRAIN","CONDITIONED","KNOWSPEC"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["KNOWTHEENEMY","BYTHEBOOK","DEFDRI","TACTTRAIN"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["FORMATIONTACTICS","COM","FULLTH","KNOWSCH"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":true,"down":true,"left":true,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["FORMATIONTACTICSIMP","BYTHEBOOK","CONDITIONED","KNOWSPEC"],"directions":[{"right":true,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":true,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["NATSCH","TARGETEDFIREPOWER","BYTHEBOOK","DEDI"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":false}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('INFILTRATOR', 'Infiltrator', '[H4]Infiltrator — Finding the Secrets[h4]
When most people hear the word Spy, the operatives of this specialization are what come to mind. Infiltrators endeavor to place themselves in the very den of the beast, usually sneaking or lying their way in undetected. All too often, Infiltrators face the worst possible odds without the benefit of direct backup, and frequently without a way out if they are discovered by the wrong people at the wrong time. 

[P]Infiltrators gain [B]Deception, Melee, Skulduggery,[b] and [B]Streetwise[b] as their additional career skills; taking this as the first specialization for a PC grants a free rank in two of these skills. Masters of covert work, Infiltrators know how to con or lie their way past almost anyone, and they know all of the tricks necessary to break into and out of secure locations, as well as everything else needed for underhanded operations. They tend to prefer silent and deadly attacks, often best accomplished with hand-to-hand weapons. 

[P]An Infiltrator rarely relies upon brute force or direct confrontation to accomplish his goals. Instead, he uses stealth, guile, subterfuge, and disguise to integrate himself among his enemies. He gains access to sensitive areas, talks to the right people, and employs every other available tactic to obtain valuable information, steal important secrets and assets, and leave behind a target who is reeling from his efforts. 

[P]Lately, Infiltrators are used by the Alliance as part of special strike teams sent throughout Imperial-controlled space, where they are used in combined operations intended to disrupt the Empire''s plans while gathering information at the same time. For more direct combat missions, Infiltrators tend to operate in a support role. When the mission calls for subterfuge and more covert operations, Infiltrators are often the ones in charge.', NULL, '["DECEP","MELEE","SKUL","SW"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["GRIT","DODGE","FRENZ","DEFSTA"],"directions":[{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["STUNBL","GRIT","SOFTSP","JUMP"],"directions":[{"right":true,"down":true,"left":false,"up":false},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":2,"cost":15,"talents":["KNOCK","FRENZ","GRIT","DODGE"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":true,"left":true,"up":false},{"right":false,"down":true,"left":false,"up":true}]},{"index":3,"cost":20,"talents":["NATBRAW","TOUGH","STUNBLIMP","DEFSTA"],"directions":[{"right":true,"down":true,"left":false,"up":false},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":4,"cost":25,"talents":["DEDI","CLEVERSOLN","MASSHAD","NATROG"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('INSTRUCTOR', 'Instructor', '[H4]Instructor — Head of the Class[h4]

When it comes to showing the untested masses of the galaxy how to fight and win, an excellent Instructor is crucial. After all, handing untrained enlistees a blaster and sending them into the thick of combat is a good way of getting them killed before they’ve even had a chance to make a difference. Instructors ensure that no one is sent to fight the Empire before they’re ready, preventing Rebel blood from being spilled in vain. Though their own role is primarily one of support, Instructors must also be proficient in the skills they impart to their students, making them effective soldiers when they are inevitably called to fight.

[P]Instructors receive [B]Discipline, Medicine, Ranged (Heavy)[b], and [B]Knowledge (Education)[b] as additional career skills. If this is the character’s starting specialization, the player may choose two of these skills and gain one free rank in each without spending experience. Not all Instructors need to be combat- ready, but most of those employed by the Rebel Alliance have, by necessity, at least some combat capability available to them. An Instructor must also have enough empathy to identify with students and to discern which areas they excel in and where they require improvement.

[P]It takes intense control to maintain a professional demeanor and concentrate on the job at hand, both for Instructors and for their recruits. Order must be maintained both on and off the field so that would-be soldiers aren’t cowed by the sights, sounds, and demands of combat. Imparting discipline to their students, especially if they’ve never held a weapon, is crucial if Instructors want to see them survive the rigors of warfare.

[P]Some Instructors are also well versed in the use of Medicine. Not only is first aid a skill that every soldier should possess, but injuries occur all too often during intensive training. Passing on the basics of Medicine to recruits ensures that trainees can save not only their comrades, but themselves as well. If training recruits to use medpacs and synthflesh to patch up wounds is all an Instructor is assigned to do, then Medicine may very well be that character’s primary focus.

[P]Every soldier must learn how to shoot, so many Instructors are also accomplished marksmen. Trainees not only need to know how to fire their weapon with the intention of hitting the enemy, but they must also learn how to care for and maintain it under battlefield conditions. Drilling recruits with a blaster comprises the basics of infantry training. Initial training is with an unloaded weapon, to get recruits comfortable with carrying it, used to its weight, and vaguely uncomfortable when it’s not within reach. Many hours of port-arms and awareness drills are held before a recruit is allowed to fire a fully charged blaster downrange at a target.

[P]Though it seems to go without saying, Instructors must be well educated. Being skilled at conveying their knowledge to their students is an important part of their job description. When integrated with a Rebel cell or combat unit, Instructors can be a benefit to everyone they serve with. As teachers, they must be able to demonstrate the correct way to do something under any circumstances. It’s highly unlikely that they wouldn’t be able to show everyone a trick or two when the chips are down.', NULL, '["DISC","EDU","MED","RANGHVY"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["CONDITIONED","PHYSTRAIN","BOD","GRIT"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["TOUGH","ENCWORD","CONDITIONED","STIMSPEC"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":2,"cost":15,"talents":["PHYSTRAIN","MASINST","BOD","BODIMP"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["FLDCOMM","GRIT","STIMSPEC","TOUGH"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["FLDCOMMIMP","NATINST","THATHOWDONE","DEDI"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('INTERROGATOR', 'Interrogator', '[H4]Interrogator — Ensuring Answers[h4]
Interrogators acquire [B]Charm, Coercion, Medicine,[b] and [B]Perception[b] as additional career skills. If this is the character''s starting specialization, the player may choose two of these skills and gain one free rank in each without spending starting experience.
[P]
In order to successfully question a target, an Interrogator needs to have some background info about the subject, possibily including personality traits, loved ones, and interests, in addition to knowing what type of information to seek. Personal history is critical to gaining leverage over a target. Interrogators must be versed in a range of information extraction techniques so that they can determine the best method for a particular foe. Physical coercion can work effectively against some enemies, but for others, psychological attacks are far more effective. Recognizing the best technique and having the appropriate tools readily available makes each interrogation faster and the results more reliable.
[P]
A physically imposing questioner may rely upon violence, and this technique can sometimes be effective. However, it is invariable cruel. Further, Imperial officers are trained to resist these techniques, reducing their efficacy. Additionally, some subjects recognize that the consequences for giving in to this type of torture can be as severe as those for resisting it. For these reasons, the most effective of interrogations eshew physical techniques for social ones.
[P]
Many Interrogators instead use a combination of Charm and Deception to effectively draw information from their subjects. They may intimidate through threats—often to the subject''s friends, family, or special interests—rather than direct violence. Demonstrations of power over those other parties can provide additional leverage, though such demonstrations may be fabricated as necessary.
[P]
Either type of Interrogator may educate allies on the best way to resist enemy questioning, something even non-combatants in the Alliance may face at some point. This may involve working with students in simulated questioning sessions, but it can also incorporate observation of the Interrogator at work . Crucial to either approach is having students watch people while they are breaking, partly so that the students can recognize what this looks like, but also to help them identify the types of leverage that might be used against them, so that they can work to mitigate the effectiveness of those tactics.', NULL, '["CHARM","COERC","MED","PERC"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["INTIM","GRIT","SURG","NOBFOOL"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["BADCOP","GRIT","SURG","GOODCOP"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["RESISTQUESTIONING","BADCOP","NOBFOOL","KNOWTHEIRWEAKNESS"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":true}]},{"index":3,"cost":20,"talents":["RESISTQUESTIONINGIMP","INTIM","KNOWTHEIRWEAKNESS","KNOWTHEIRWEAKNESSIMP"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["PRESPNT","EXHAUSTIVEQUESTIONING","MADEYOUTALK","DEDI"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":false}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('INVESTIGATOR', 'Investigator', '[H4]Investigator — A Living Chronicle[h4]

Investigators examine unsolved crimes, using their knowledge and skills to figure out the who, what, when, where, and why. They don''t seek this information merely to satisfy some obsession over the ugly side of society but rather to honor the victims by bringing the perpetrators to justice.
[P]Investigators receive [B]Knowledge (Education)[b], [B]Knowledge (Underworld)[b], [B]Perception[b] and [B]Streetwise[b] as additional career skills. Characters who select this as their starting specialization may choose two  of these skills and gain one free rank in each without spending starting experience.
[P]Investigators piece together what has been lost or stolen by uncovering the past. Weaving the stories of what happened into a living chronicle, they discover secrets and untangle lies. Only by understanding the how and why of a crime can Investigators bring the one who did it to justice.
[P]Since crimes are inflicted upon (and inflicted by) people these acts leave an impression in the Force. Particularly violent crimes leave a strong disturbance. Extremely evil crimes leave a wound—a cold, dark space that frightens the unwary and consumes the foolhardy. Investigators can tease out details from those impressions, unwinding them so they can heal. In many ways, investigators are physicians for the souls of communities, solving festering mysteries, airing out toxic secrets, and cauterizing hidden crimes.
[P]These violent impressions can also affect individuals. Even if they haven''t witnessed the crime in question, investigators have heard rumors, have felt their community suffer, and can read their peers with the insight of an insider. In many ways, a community functions as a single, living organism, and damage to that organism reverberates in both predictable and surprising ways. By tracing those symptoms, Investigators get to the source.
[P]Investigators have many tools in their kits besides the Force. Understanding the local customs and language, being familiar with the unspoken rules of a community, and knowing how to bluff their way into a back-room requires knowledge and social skills. Slicing a security camera picking a lock to search an apartment, or staking out a person of interest in an investigation means breaking laws without getting caught. And sometimes—oftentimes—successfully sneaking into and out of a building can bring the Investigator one step closer to the truth.
[P]The greatest tools of Investigators, though, can often become their greatest weaknesses. Their emotions can help them understand a person''s motives giving context to a fact. If a perpetrator killed a dangerous drug lord, is that persona  murderer or a savior? However, emotions can cloud an investigator''s judgment. If the good friend who saved a life turns out to be a slaver, is it betrayal to turn that friend in? Finally, the constant exposure to suffering can burn out even the most stalwart Investigators.
[P]In the final analysis, Investigators see crime and victimization as a corruption of the Force. They feel the Force as something that flows through people, affecting their health, psychology, and well-being. A corruption of the Force makes people angrier, more fearful, and more likely to lash out and harm others. These constant cuts caused by crime chip away at a society wounding the Force until the whole society falls to the dark side. Airing out the source of the wound allows the society to finally heal.', NULL, '["EDU","PERC","SW","UND"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["STRSMART","KEENEYED","UNCANSENS","GRIT"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["TALKTALK","GRIT","STRSMART","TOUGH"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":2,"cost":15,"talents":["TOUGH","KEENEYED","STRSMART","RECSCENE"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["SENSEADV","UNRELSKEP","CLEVERSOLN","SENSESCENE"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":true,"down":true,"left":true,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":4,"cost":25,"talents":["VALFACT","DEDI","STRSMARTIMP","FORCERAT"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":false,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('JUYOBERSERKER', 'Juyo Berserker', '[H4]Juyo Berserker — Controlled Rage[h4]
In the latter days of the Jedi order, Padawans studied six forms of lightsaber combat, ensuring familiarity with all.  Few Jedi, however, were trusted to study the seventh, the highly restricted Juyo form.  The Juyo Berserker is a Warrior who fights with this dangerously aggressive and ferocious manner of lightsaber combat.  A Juyo Berserker could have formal training in Form VII, but the specialization can also apply to a self-taught fighter who harnesses natural rage and ferocity to overcome foes in an all-out offensive.

[P]Juyo Berserkers receive [B]Coercion, Discipline, Lightsaber[b], and [B]Melee[b] as additional career skills.  If this is the character''s starting specialization, the player chooses two of these skills and gains one free rank in each, without spending starting experience. While Juyo is undoubtedly an aggressive form of combat by the standards of the Jedi, it nonetheless requires at least the modicum of control necessary to wield a lightsaber effectively and - relatively- safely.  Compared to the other lightsaber forms in use by the Jedi in the latter days of the Republic, however, Juyo is reckless, Walking this fine line is not dissimilar from the way in which Juyo practitioners balance dangerously close to the dark side of the Force.

[P]While a Juyo practitioner may appear calm, the form requires intense emotions to fuel its rapid, unpredictable, powerful strikes.  Some Juyo Berserkers - particularly adherents of the Jedi Code, which calls for tranquility and detachment - conceal the emotions raging below the surface.  Others, including Sith, fully embrace the anger that drives Juyo and grants it power, snarling like frenzied animals as they lay into their opponents.
[P] For Force sensitives in the age of the Empire, it is all too easy to give in to frustration, anger, and hate when forced into a confrontation.  They might unknowingly find themselves mimicking the Juyo style. These sentients might be aware of the conflict raging within them- the struggle between unbridled emotion and stability-or they might remain dangerously ignorant of the path to the dark side of the Force.

[P]A Juyo Berserker focuses on offense nearly to the exclusion of all else. This approach leaves the Berserker vulnerable should an opponent find the opportunity to counterattack, and so a Juyo practitioner must match the foe''s skill in pure ferocity. Juyo fighters particularly risk being overwhelmed by greater numbers; a Berserker must be able to lay about with the blistering relentlessness of many Warriors- or of the deadly predator from which the form draws its name.

[P]Jedi who practiced Juyo were careful to balance inner
darkness with the tranquility offered by the light side of the Force. It was in this way that Mace Windu developed the Vaapad variant, a form that allowed him to channel his inner darkness toward positive outcomes, to harness his anger without allowing it to control him.  For Warriors bereft of the doctrines of the Jedi this balance is difficult. Without it, a tragic outcome could be all but inevitable.', NULL, '["COERC","DISC","LTSABER","MELEE"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["TOUGH","PARRY","GRIT","INTIM"],"directions":[{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["INNERPEACE","PARRY","VAAPADCONTROL","LETHALBL"],"directions":[{"right":true,"down":true,"left":false,"up":false},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":false},{"right":false,"down":true,"left":false,"up":true}]},{"index":2,"cost":15,"talents":["BAL","LETHALBL","QUICKST","EMBRACEHATE"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":false},{"right":false,"down":true,"left":false,"up":true}]},{"index":3,"cost":20,"talents":["INNERPEACE","INTIM","JUYOSAVAGERY","QUICKST"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":4,"cost":25,"talents":["PARRY","EMBRACEHATE","DEDI","MULTOPP"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('MAGUS', 'Magus', '[H4]Magus — Following a Different Path[h4]
[P]To hear of a Magus, even during the time of the Galactic Republic, would be a rare event; to meet one, even more so. The Jedi Order, in its waning days, had become quite conservative regarding explorations into the Force. The Jedi either avoided or outright fought the myriad of sects and cults exhibiting mystical powers throughout the galaxy. The Force, they reasoned, was all they needed. Other teachings and experiments deviated too much from  the clear path of the Jedi and thus danced too close to illusion and self-deception, leading to temptations toward the dark side of the Force.

[P] Paradoxically, a Force user may be more likely to become a Magus during the Galactic Civil War. With hope and the light in short supply, some disciples may be more open and willing to seek out so-called forbidden knowledge. A Magus develops and collects a hodgepodge of strange rituals and odd practices to commune with the Cosmic Force. They have no training, but at the same time, they have no teachings that would convince them not to t ry. The danger, of course, comes from a lack of oversight. Without a guiding hand or proper self-reflection, a Magus has a greater chance to experiment with powers fueled by the dark side of the Force.

[P]The Magus receives [B]Coercion, Discipline, Knowledge (Lore)[b], and [B]Medicine[b] as additional career skills. When starting with this specialization, the Magus may choose two of these skills and gain one free rank in each.

[P] Knowledge, especially forbidden knowledge, fuels the Magus.  Unrestricted by the Jedi Order, defiant of the Galactic Empire, the Magus seeks a connect ion to the Force through knowledge. The source of that knowledge doesn''t matter; rituals, objects and places of power, and ancient religious and magical texts all hint at a singular source of energy. While some Magi crave knowledge for its own sake, most explore the Magus path in order to control the Force itself.

[P]If the Force flows through everything and is a part of everything, then by manipulating the Force, the Magus can manipulate reality. The Force can be used to make matter, affect matter. affect life, and perhaps... even create life.  With this power, the Magus can do amazing and impossible things. No, not impossible, for nothing is impossible if one believes in the Force.
[P]This confidence, however, is the biggest trap for Magi. They can do impossible things, yes, but It is the Force that allows them to do so, not their knowledge or talent. Despite what they may think, Magi still have mortal trappings. They have histories, memories, early thoughts, and emotions that can never be truly removed. Hubris may be the greatest enemy for Magi. This hubris can trick Magi Into thinking that pushing here or pulling there might be for the good of all, or for the good of the Force, but in reality, they are manipulating the Force for their own selfish needs. Many a Force-using tyrant became a Magus before falling to the dark side.', NULL, '["COERC","DISC","LORE","MED"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["HEALTRANCE","TOUGH","CONF","RESOLVE"],"directions":[{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["CONF","HEALTRANCE","CHANNELAGONY","SECRETLORE"],"directions":[{"right":true,"down":true,"left":false,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["HEALTRANCEIMP","SECRETLORE","RESOLVE","KNOWPOW"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":false}]},{"index":3,"cost":20,"talents":["CHANNELAGONY","MINDMAT","TOUGH","CHANNELAGONY"],"directions":[{"right":true,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":false}]},{"index":4,"cost":25,"talents":["POWEROFDARK","DEDI","TRANSMOGRIFY","FORCERAT"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('MAKASHI', 'Makashi Duelist', '[H4]Makashi Duelist[h4]
The presence and showmanship that can come naturally to all Mystics reflects itself in the way of a duelist. For practitioners of Makashi, dominating a combat through one''s presence is just as important as dominating it through martial prowess, and the Makashi Duelist is the ultimate expression of that art. 

[P]Makashi Duelists acquire [B]Charm, Cool, Coordination,[b] and [B]Lightsaber[b] as additional career skills. If this is the character''s starting specialization, he may choose two of these skills and gain one free rank in each, without spending starting experience. This combination reflects the showmanship and presentation so intrinsic to the duelist''s art. A true Makashi Duelist must always fight with poise and grace, never showing the slightest strain and keeping complete control over his facial expressions and his body''s most minute movements. 

[P]Though some detractors may dismiss this fighting style as overly foppish and vain, a Makashi Duelist remains an exceptionally potent combatant. Those detractors forget that the Makashi form was developed to fight against other lightsaber-armed opponents. At its heart, Makashi focuses on one goal: to meet an enemy with a sword or lightsaber and slay him. A true Makashi Duelist never loses sight of this goal, and all his flourishes and feints are but means to an end. Movements that work to deflect and exhaust an opponent—particularly if the foe is not prepared for battle with a Force-sensitive—can soon leave an enemy frustrated with the entire experience. As the opponent becomes increasingly worn down, the Makashi Duelist soon finds an opportunity to exploit the foe''s exhaustion. 

[P]A Makashi Duelist''s force of personality, rather than natural athleticism, often drives his combat technique. Elements of personal flair become an effective means of disorienting and distracting an opponent during a battle. Sometimes a verbal misdirection can be every bit as effective as a physical one, leaving an opponent open to a single master stroke.', NULL, '["CHARM","COOL","COORD","LTSABER"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["GRIT","RESDISARM","GRIT","PARRY"],"directions":[{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["PARRY","MAKTECH","DUELTRAIN","FEINT"],"directions":[{"right":true,"down":true,"left":false,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":false,"down":true,"left":true,"up":false}]},{"index":2,"cost":15,"talents":["PARRY","FEINT","PARRY","PARRY"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":3,"cost":20,"talents":["INTENSPRE","PARRYIMP","GRIT","DEFTRAIN"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["DEDI","SUMDJEM","MAKFIN","MAKFLOUR"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('MARAUDER', 'Marauder', '[H4]Marauder — Up Close and Personal[h4]
Marauders don''t necessarily mind shooting their opponents, but they would much rather get mixed up in a melee, weapons in hand, smashing and slashing their way through. Marauders are tough—probably the toughest combatants in any conflict. They tend to take a great deal of punishment while dealing out far more to any who dare go against them. 

[P]A Marauder''s list of additional Career skills is not at all surprising: [B]Coercion, Melee, Resilience,[b] and [B]Survival[b]. If this is the character''s starting Specialization, he may choose two of these skills and gain one free rank in each, without spending starting experience. Marauders make excellent "leg-breakers," among other things, and they usually know quite a bit about how to survive in most situations. In combat, they are masters of dishing out and taking lots of damage. 

[P]Marauders may come from low-tech worlds, where advanced weaponry simply wasn''t an option for them. Alternately, they might come from a culture where melee combat is considered far more honorable and worthy, and they keep to their traditions. Moreover, many pirates and raiders of starships favor melee weapons in order to avoid damaging vital systems aboard a ship they''re in the middle of trying to take. 

[P]A character who chooses to be a Marauder might be an ex-pirate. Alternatively, he could be in the adventure to make money in the only way he can—with his fists. It could be that he''s simply along for the ride, ready to bash his way through whatever adventure he encounters.', NULL, '["COERC","MELEE","RESIL","SURV"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["TOUGH","FRENZ","FERSTR","LETHALBL"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["FERSTR","TOUGH","HERO","KNOCK"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["ENDUR","LETHALBL","TOUGH","FRENZ"],"directions":[{"right":true,"down":true,"left":false,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":3,"cost":20,"talents":["TOUGH","FERSTR","NATBRAW","LETHALBL"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":true,"down":true,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["FRENZ","ENDUR","DEFSTA","DEDI"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":false}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('MARSHAL', 'Marshal', '[H4]Marshal — The Burden of Peace[h4]
Criminals might run and criminals might hide, but the Marshal won''t rest until he drags them back to town in binders. The presence of a strong Marshal is often the only thing keeping a colony from plunging into chaos. The Marshal has a gift for extracting information from witnesses and confessions from criminals, and separating lies and irrelevant information from the truth. Should suspects turn violent, the Marshal is equally adept at talking criminals into a pair of binders or blasting them into oblivion.

[P]Marshals receive [B]Coercion, Knowledge (Underworld), Ranged (Light)[b] and [B]Vigilance[b] as additional career skills. If this is the character''s starting specialization, he gains one free rank in each of two of these skills of his choice, without spending experience. Where most Colonists are forced to rely on talking their way out of trouble, the Marshal finds that his blaster speaks almost as well as he does. Most law officers know that holding the weight of the law over a potential witness is the quickest way to modify his attitude. Marshals can throw the weight of their authority around to get answers. There is little government oversight on the fringe, and often a Marshal''s word is the law. 

[P]Equally as important is the Marshal''s knowledge of crime and criminal elements, especially those operating within his jurisdiction. A Marshal who doesn''t take the time to familiarize himself with the local malcontents isn''t going to be very good at his job. And when it comes time to go toe to toe with those criminals, the Marshal is ready. Most Marshals know how to use the blasters at their hips. 

[P]The Marshal makes for a great leader in combat-oriented groups, or can provide some muscle to non-combat groups while still participating in social and investigative encounters. Marshals strike a great balance between social skills and combat, allowing them to speak on behalf of combat-oriented parties without being a liability when blaster bolts start flying. Their ability to sort fact from fiction makes them difficult to manipulate, and their gritty determination can carry an entire group that would have otherwise given up hope of success.', NULL, '["COERC","RANGLT","UND","VIGIL"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["HARDHD","GRIT","STRSMART","TOUGH"],"directions":[{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["DURA","GOODCOP","BADCOP","QUICKDR"],"directions":[{"right":true,"down":true,"left":false,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":2,"cost":15,"talents":["HARDHD","GRIT","GOODCOP","POINTBL"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":3,"cost":20,"talents":["DURA","UNRELSKEP","BADCOP","POINTBL"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":4,"cost":25,"talents":["HARDHDIMP","UNRELSKEPIMP","DEDI","NATMAR"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":false},{"right":false,"down":false,"left":false,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('MARTIALARTIST', 'Martial Artist', '[H4]Martial Artist[h4]
From the Kage Warriors of Quarzite to the enforcers of the Black Sun, organizations and cultures across the galaxy have developed their own unique hand-to-hand combat styles to use their species'' physiology to greatest effect. Over decades, centuries, and millennia, these combat forms become more than mere means of inflicting violence; generations of practitioners work to make them into art forms, philosophies, and ways of life. A desire to practice self-defense can become a belief in the value of self-betterment and the innate potential of others, though not all ideologies develop along such lines. More than a few Bounty Hunters have picked up techniques from martial arts styles across  the galaxy to help their hunts. Some are shining examples of their school''s philosophies and traditions, but others are disgraced students, or have never even trained formally, earning their skills through hard experience on the battlefield.
[P]In addition to the Bounty Hunter''s eight career skills, the Martial Artist receives [B]Athletics[b], [B]Brawl[b], [B]Coordination[b], and [B]Discipline[b] as bonus career skills. If this is the character''s starting specialization, the Martial Artist may choose two of these skills and gain one free rank in each without spending starting experience.
[P]A Martial Artist benefits first and foremost from a high Brawn rating to empower the Brawl skill. However, Willpower is an extremely useful secondary characteristic, as it not only gives the Martial Artist the higher strain threshold needed to activate the specialization''s many talents that use strain as a resource, but also the ability to face intimidating foes up close without flinching. Further, talents like Mind Over Matter benefit from a higher Willpower, and let the Martial Artist fight even longer without becoming exhausted. Finally, the  Martial Artist benefits greatly from investing in the Coordination skill, as talents like Martial Grace and Coordination Dodge let the Martial Artist supplement raw strength with finesse both offensively and defensively.
[P]Unlike characters from most other specializations built around close-quarters combat, Martial Artists does not need a weapon to fight competently. Martial Artists generally value precision over brute strength and strive to execute efficient unarmed strikes. By wasting as little energy as possible, they can deliver extremely forceful blows even when unarmed. This is reflected in talents like Precision Strike, which lets Martial Artists exhaust and weaken foes as they see fit rather than by chance. Martial Artists also seek to leverage their enemies'' strength against them in battle with talents like Overbalance, which allows them to throw foes off-balance after they attack. Martial Artists also have access to Parry to mitigate damage, and can even use Parry when unarmed.
[P]This unique combination of precise offense and controlled defense allows Martial Artists to contend with some of the toughest fighters in the galaxy. Of course, not every battle is worth fighting, and a trained Martial Artist knows to assess not only the enemy but also the situation before deciding whether to join the fray. Many schools of martial arts teach the idea that fights are to be avoided, and that the ideal way to win a battle is to avoid having it in the  first place. Unsurprisingly, this attitude is less prevalent amongst Bounty Hunters who wield martial arts as their profession demands a certain amount of violence, but some still apply these over-arching principles to a certain degree.', NULL, '["ATHL","BRAWL","COORD","DISC"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["IRONBODY","PARRY","GRIT","PRECSTR"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["PARRY","TOUGH","MARTIALGRACE","GRIT"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":true,"down":true,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["UNARMPARRY","GRAPPLE","IRONBODY","PRECSTRIMP"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":3,"cost":20,"talents":["OVERBAL","TOUGH","MINDMAT","GRIT"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":4,"cost":25,"talents":["COORDODGE","DEDI","NATBRAW","PRECSTRSUP"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":false},{"right":false,"down":false,"left":false,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('MECHANIC', 'Mechanic', '[H4]Mechanic — Making Stuff Work[h4]
Depending on who is asked, Mechanics are either the glue that holds everything together or the grease that makes it all go. Most Mechanics would tell you they do both, and then get back to work. 
[P]The additional career skills of a Mechanic indicate his practical versatility: [B]Brawl, Mechanics[b] (of course, and this gives him the opportunity to have two starting ranks in the skill), [B]Piloting (Space),[b] and [B]Skulduggery[b]. If this is the character''s starting Specialization, he may choose two of these skills and gain one free rank in each, without spending starting experience. Pragmatic and tough are two key traits that come out of a Mechanic''s talent tree, as are the many ways he is capable of fixing what''s broken and being prepared for any mechanical contingencies that arise. 

[P]While it is relatively easy to find a Mechanic almost anywhere in the galaxy, it''s considerably more difficult to find a good one, and even harder to find one that can be trusted. Ship captains will literally travel across systems to get to a Mechanic they can trust to do a good job for them, which is why Mechanics tend to be in high demand. 

[P]A Mechanic that''s hooked up with the typical Player Character group has likely decided he doesn''t want to spend all of his time in a work pit or engineering hangar. He probably wants to see a bit of the galaxy and get some flight time in. Fortunately, Mechanics tend to pick up a few things about how to take care of themselves in tough situations, and given a few minutes and some random devices, they may well cobble together a rather explosive means of dealing with real problems.

 [H4]Mechanic — Making Things Go[h4]
Virtually no Alliance military unit can function without a competent Mechanic, due to the constant wear-and-tear on the mechanical and technical assets the unit relies upon to do battle. Mechanics do everything from minor tune-ups and adjustments to massive overhauls and repairs. They are both the gear of the Alliance machine and the grease that makes it run smoothly.
[P]
Mechanics gain four additional career skills--[B]Brawl, Mechanics, Piloting (Space),[b] and [B]Skulduggery[b]. They gain a free rank in two of these (as long as this is the first specialization chosen). Tough and pragmatic, Mechanics tend to be able to take care of themselves in a fight, and they know the best places to get what they need when normal supply chains fail. They''re also usually capable of flying or driving whatever they fix.
[P]
Most Mechanics are definitely "in the field" types. While they prefer to have a good place to work where they can keep their tools, they don''t want to be too far away from the unit they support to do any good. A military-minded mechanic always has a solid, portable kit for his tools and is ready to go into the line of fire to get a desperately needed tank or heavy cannon back up and running before the enemy overruns the position.
[P]
Many Alliance commanders are loath to promote their Mechanics, but this isn''t due to a lack of confidence in a Mechanic''s abilities or a failure to follow orders (though Mechanics in the Rebellion do have a reputation for being a surly, independent lot). Instead, such commanders fear that promotion will lead to their unit''s loss of the service of a highly valued member for the team. Fortunately, most Mechanics have little use for rank, and even less use for the paperwork and bureaucracy that upper-echelon types have to deal with. They''d much rather take wrench in hand and get to work.', NULL, '["BRAWL","MECH","PILOTSP","SKUL"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["GEARHD","TOUGH","FINETUN","SOLREP"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["REDUNSYS","SOLREP","GEARHD","GRIT"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["SOLREP","ENDUR","BADM","TOUGH"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["CONT","SOLREP","FINETUN","HARDHD"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":4,"cost":25,"talents":["NATTIN","HOLDTOG","DEDI","HARDHDIMP"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('MEDIC', 'Medic', '[H4]Medic — Save the Team[h4]
The Alliance cannot afford to fight a war of attrition the way the Empire can. The enemy can pour thousands of stormtroopers and other forces into a meat-grinder of a battle, taking horrific casualties, without blinking an eye over its losses. Every soldier of the Rebellion is, on the other hand, a valuable asset whose loss Alliance High Command feels keenly. The Medic serves to prevent as many of those losses as possible. 

[P]Medics go into the field with [B]Knowledge (Xenology), Medicine, Resilience,[b] and [B]Vigilance[b] as additional career skills; if this is the first specialization taken, two of these four begin with a free rank. Medics know how to keep their head when everyone else is panicking, and they know how to be prepared for any contingency. They are skilled at treating the wounds of anyone in their unit, regardless of species. 

[P]Many folks think Medics are inherent pacifists. While a Medic might prefer to save a life rather than take it, most realize the necessity of fighting and violence for a greater cause, and are more than ready to strike down an enemy in order to save a comrade. Medics tend to see no one as expendable, which can make them difficult to deal with when a commander wants to pull a team out of a situation and there''s a chance any of those on the deck could still be alive. 

[P]The vast majority of Alliance troopers greatly revere the Medics in their units, knowing these brave men and women are often the only thing standing in the way between them and death. Alliance Medics are famous for taking ridiculous risks in the middle of terrible battles just for the chance to save one more Rebellion fighter.', NULL, '["MED","RESIL","VIGIL","XEN"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["FORAG","STIMSPEC","GRIT","SURG"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["TOUGH","SURG","STIMSPEC","BACT"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":false},{"right":true,"down":true,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["WELLROUND","GRIT","STIMAP","MASDOC"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":false}]},{"index":3,"cost":20,"talents":["DODGE","NATDOC","STIMAPIMP","STIMSPEC"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":4,"cost":25,"talents":["ANAT","DEDI","ITSNOTTHATBAD","STIMAPSUP"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":false,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('MERCENARY', 'Mercenary Soldier', '[H4]Mercenary Soldier — Master of War[h4]
If the Marauder is the melee master, and the Bodyguard is the all-around weapons and gear trooper, the Mercenary Soldier is the warfare expert. An adept of both ranged combat and military tactics, he is a leader of warriors in combat and a deadly combatant himself. 

[P]Mercenary Soldiers add the career skills of [B]Discipline, Gunnery, Leadership[b] and [B]Ranged (Heavy)[b]. If this is the character''s starting Specialization, he may choose two of these skills and gain one free rank in each, without spending starting experience. A Mercenary Soldier can be a true mental rock in critical situations. He is a deadly foe all on his own, and deadlier still if he has a force to lead in battle. 

[P]Mercenary Soldiers are the most likely to have come from prior service with a larger organization, and they almost certainly had at least a non-commissioned officer role with that force. They have a keen grasp of both tactics and strategy, though they will tend to focus more on the former as a Matter of practicality and survival. Even in less formal situations, a Mercenary Soldier will tend to show a high degree of personal discipline and order. 

[P]In a Player Character group, it will not be out of the question for a Mercenary Soldier to take charge, at least in situations where combat is likely. Though his leadership skills are not as comprehensive as other specializations, they are uniquely focused for combat.', NULL, '["DISC","GUNN","LEAD","RANGHVY"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["COM","SECWIND","POINTBL","SIDESTEP"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["SECWIND","CONF","STRONG","POINTBL"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["FLDCOMM","COM","NATMAR","SNIPSHOT"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":3,"cost":20,"talents":["FLDCOMMIMP","GRIT","TOUGH","LETHALBL"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["DEADACC","TRUEAIM","DEDI","TRUEAIM"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('MODDER', 'Modder', '[H4]Modder — Obsessive Innovation[h4]
If someone keeps disassembling and reassembling the rest of the crew''s weapons, armor and gear without permission, it''s a safe bet that the culprit is the team''s Technician. If those items actually seem to work better afterward, that Technician might well be a Modder. Modders are chronic tinkerers, and most Modders would rather add features to machines they already have than build new ones. By turning their engineering prowess toward relentlessly repairing, optimizing, testing, calibrating and re-repairing mechanisms around them. Modders make any piece of technology their own - even if it isn''t, strictly speaking, theirs.

[P]A Modder can be extremely versatile; in some ways a modder specializes in generalizing. By spending less time and energy learning how to build devices from the ground up, a Modder can focus on how to optimize and customize all sorts of devices - from weapons to ships, droids to personal gear. Of course, one project might hold a Modder''s interest more than others, at least for a while. The Modder''s talents allow a character to focus heavily on a single project or flit from one exciting upgrade to another at a moment''s notice. Whether it''s a starship engine or a shiny new blaster, a Modder can probably find a way to make it better.

[P]Modders receive [B]Gunnery, Mechanics, Piloting (Space),[b] and [B]Streetwise[b] as bonus career skills. If this is the character''s starting specialization, the Modder may choose two of these skills and gain one free rank in each without spending starting experience.

[P]Many teams of renegades and rogues benefit from having a Modder around, as this character can offer a number of unique upgrades to starships and vehicles as well as better access to attachments for  weapons. Modders can certainly be competent pilots and combatants in their own right. Modders who seek out battle in person benefit from a high Agility. With or without an investment in this characteristic though, combat-oriented Modders are most effective when backed up by teams of specialists carrying the souped-up firepower and piloting the uniquely customized ships that only Modders can provide.', NULL, '["GUNN","MECH","PILOTSP","SW"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["TINK","RESOLVE","KNOWSOM","SIGVEH"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["GEARHD","TINK","FANCPAINT","LARGEPROJ"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["RESOURCEREFIT","RESOLVE","LARGEPROJ","TOUGH"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["JURY","HIDD","TINK","GEARHD"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["JURY","DEDI","NATTIN","CUSTLOAD"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":false,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('NAVIGATOR', 'Navigator', '[H4]Navigator — Guiding to Safety[h4]
Seekers are often at the forefront of exploration, pushing back the edges of the unknown across planets and systems throughout the galaxy. Most view the mission itself as more important than the plotting needed to undertake it, and determining its best method and route unimportant when compared to what awaits at the destination. Others, though, see these as perhaps at least as important, and certainly more personally rewarding. Navigators represent those Seekers who devote themselves fully to these aspects from charting hyperspace passages or plotting overland routes. No matter the environment, none can match Navigators when they set about deciding a course. When Navigators use the Force their abilities might even appear more reliant on fantastic luck than skill to the uninitiated.
[P]Navigators are often excellent pilots as well, but these Seekers are generally more interested in the best way for their vehicle to arrive safely an expeditiously than in its firepower or maneuverability. Some of these individuals may have spent their entire lives in space, moving from ship to ship or working one specific area filled with hazardous asteroids or nests of black holes. Most travel extensively, regardless of their origins, always seeking out new uncharted regions in need of their abilities.
[P]Navigators receive [B]Astrogation[b], [B]Knowledge (Outer Rim)[b], [B]Perception[b] and [B]Survival[b] as additional career skills, representing their skills at locating and mapping out pathways, both planetary and stellar. Characters who select this as their starting specialization may choose two of these skills and gin one free rank in each without spending starting experience. The addition of Astrogation allows Navigators to truly excel in outer space, where they can help ensure the group arrives speedily and accurately to distant star systems.
[P]Navigators are also excellent on planets, charting routes over sea, land, and air, as well as even orbital voyages. Their skills are especially critical on uncharted worlds, but they are  also valuable in urban settings, which can be as unfathomable as any dense jungle or endless steppe. When the PCs need to find the fastest, safest, or least conspicuous way to reach their destination, Navigators are whom they turn to invaluable in chases, whether the PCs are trying to run down their quarry or escape pursuit, Navigators can give a group the edge it needs by locating the most efficient route.
[P]Navigators are often driven to find such routes on their own, and might become irritated when inferior passages are used. Not resting until the best path is discovered and followed, they soon become bored when success is achieved, as there is no challenge in following an established route. For some Navigators, this is a never-ending quest, and they are always seeking to shave just one light year from a hyperspace lane, or an hour from a city crossing, something that can always happen as they become more proficient with the Force. The Force can also allow them to offer guidance of a less tactical and more spiritual nature at times as well, something that can also aid the PCs in their adventures.', NULL, '["ASTRO","OUT","PERC","SURV"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["STUDPLOT","EXTRACK","SHORTCUT","GRIT"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["GALMAP","SHORTCUTIMP","PLANMAP","PREEMAVOID"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":2,"cost":15,"talents":["SHORTCUT","SWIFT","UNCANSENS","TOUGH"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["GALMAP","HOLNAV","FORCERAT","PLANMAP"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["ONEUNI","INTUITNAV","MASSTAR","DEDI"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":false}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('NIMAN', 'Niman Disciple', '[H4]Niman Disciple[h4]
Even the most accomplished of negotiators can see negotiations fail and come to violence. In the time of the Republic. many Jedi peacemakers trained with the lightsaber to prepare themselves for that eventuality. Today, Consulars who wish to do the same can focus on self-defense and gain a working knowledge of lightsaber combat by following the path of the Niman Disciple. 

[P]Niman Disciples gain the additional career skills of [B]Discipline, Leadership, Lightsaber,[b] and [B]Negotiation,[b] and if this is the PC''s starting specialization, the PC gains one rank in each of two of these skills. They remain focused on working with groups of individuals to come to a peaceful accord, but they acknowledge that the road to that accord may be fraught with danger. These skills can make surviving in a treacherous environment much more possible. 

[P]Due to Consulars'' naturally compassionate nature, this path centers on developing defensive measures in concert with negotiation techniques. In general, the associated combat techniques are focused on survival and defense instead of attack. Also, due to the Consulars emphasis on mental discipline and self control, the Niman Disciple puts more emphasis on integrating his Force abilities into his fighting style, using the Force as his ally to defeat dangerous foes.', NULL, '["DISC","LEAD","LTSABER","NEG"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["PARRY","NOBFOOL","REFLECT","GRIT"],"directions":[{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["DEFTRAIN","NIMTECH","TOUGH","PARRY"],"directions":[{"right":true,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":2,"cost":15,"talents":["PARRY","SENSDEMO","REFLECT","DEFTRAIN"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["SUMDJEM","REFLECT","DRAWCLOSER","CENTBEING"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["DEDI","FORCEASSAULT","FORCERAT","CENTBEINGIMP"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('OPERATOR', 'Operator', '[H4]Operator[h4]
To catch a target, a Bounty Hunter must be fast, and even the swiftest sentient being cannot hope to outrace a speeder or starship on foot. An Operator prefers to undertake all pursuits from within a vehicle or spacecraft, keeping the target in sight with deft maneuvering and on the run with withering firepower. In a high-speed chase, few characters can match an Operator''s expertise, and fewer still are prepared for the arsenal of daring moves and dirty tricks she can unleash.
[P]In addition to the Bounty Hunter''s eight career skills, the operator receives [B]Astrogation[b], [B]Gunnery[b], [B]Piloting (Planetary)[b], and [B]Piloting (Space)[b] as bonus career skills. If this is the character''s starting specialization, the Operator may choose two of these skills and gain one free rank in each without spending starting experience.
[P]A high Agility rating always benefits an Operator, especially when paired with a solid investment in Gunnery and Piloting (Planetary) or Piloting (Space), depending on the Operator''s preferred vehicle. An Operator also benefits from an investment in Intellect, as this characteristic is used for both the Astrogation skill—critical in tracking quarry across the galaxy—and for the Mechanics skill.
[P]Even if the Operator is not the groups technical expert, having a strong Intellect and a rank or two of Mechanics means that the Operator can make repairs on the fly. After all, most Operators put their craft through its paces (and even push beyond its limits from time to time). Knowing how to fix an overtaxed engine can be the difference between staying on the trail and drifting for weeks, waiting for a repair team to arrive. Any Bounty Hunter who has spent time adrift in space knows full well the value of being able to perform one''s own repairs.
[P]Operators are sometimes lone wolves, chasing their targets across the gulfs between the stars with no company but a trusty ship. However, many Operators are part of teams of bounty hunters, conveying their comrades on to the location of their foes and running starship interference while they capture targets on the ground. Some such Operators are loathe to leave their ships entirely, though disembarking from time to time is usually unavoidable on the hunt.
[P]Unlike many other specializations focused on piloting, Operators need to disable enemy ships rather than just destroy them. The Operator specialization gives a character access to numerous talents that help bring targets to a halt, including Debilitating Shot, Hindering Shot, Overwhelm Defenses, and Offensive Driving. All of these abilities are useful for taking down fleeing starships—or, in a pinch, disabling the vessels of rival bounty hunters pursuing the same quarry.', NULL, '["ASTRO","GUNN","PILOTPL","PILOTSP"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["GRIT","GALMAP","SHORTCUT","OVERDEF"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["FULLTH","PLANMAP","GRIT","DEPSHOT"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":false},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["SKILLJOCK","ALLTERDRIV","OFFDRIVE","GRIT"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["LETSRIDE","SHORTCUT","GRIT","OVERDEF"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["DEDI","SHORTCUTIMP","SKILLJOCK","HINDERSHOT"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":false,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('OUTLAW', 'Outlaw Tech', '[H4]Outlaw Tech — Making Things Better[h4]
Outlaw Techs are the specialists others call on when they want something out of the ordinary. A blaster that works beyond factory tolerances? No problem. A transponder that identifies a smuggler''s freighter as a religious pilgrimage craft? It''ll cost a few credits, but sure. A protocol droid altered to carry out an assassination? Just how big is that credit line, anyway? 

[P]The Outlaw Tech adds the following to his available career skills: [B]Knowledge (Education), Knowledge (Underworld), Mechanics,[b] and [B]Streetwise[b]. If this is the character''s starting Specialization, he may choose two of these skills and gain one free rank in each, without spending starting experience. This gives him the opportunity to have two starting ranks in Mechanics, if he also chooses that as one of his free starting career skill ranks. With his talents, the Outlaw Tech is adept at doing fantastic things with technology that he probably shouldn''t. He''s also tough, clever, and adaptable. 

[P]Outlaw Techs find the Outer Rim very comfortable. They''re able to practice their unique style of work with far less chance of running afoul of Imperial agents or other repressive government restrictions. They also find it far easier to make the contacts and get the kinds of customers that really appreciate their services. Of course, it''s a lot harder to get true state-of-the-art equipment, but making do with what''s on hand is a specialty of the Outlaw Tech. 

[P]Outlaw Techs in a Player Character group will be highly prized, especially for their ability to make all kinds of improvements on other characters'' gear. They are also adept at keeping ships and vehicles operational, and in some situations, they''re as handy at acquiring certain goods as some Explorers. Without a Smuggler in the group, an Outlaw Tech may be the best bet for dealing with the local black markets.', NULL, '["EDU","UND","MECH","SW"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["TINK","UTINNI","SPKBIN","TINK"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["SOLREP","GRIT","UTINNI","TOUGH"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["UTIL","SIDESTEP","BRA","DEFSTA"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["JURY","SPKBIN","INVENT","JURY"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":4,"cost":25,"talents":["INVENT","DEDI","KNOWSCH","BRA"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":false},{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('PADAWANSURVIVOR', 'Padawan Survivor', '[H4]Padawan Survivor — Fugitive Apprentices[h4]

Order 66 effectively erased the Jedi from existence, but a small handful of Padawans across the stars managed to escape.  These young apprentices watched their closest allies suddenly turn and cut down Jedi and Padawans without warning.  The remaining Padawan Survivors have been forced to hide their burgeoning abilities and enter a hostile galaxy alone and unprepared for life outside the Jedi Order.  However, a few have begun to emerge to fight back against the Empire that betrayed them.

[P]The Padawan Survivor universal specialization does not have any career skills associated with it.  When characters purchase this specialization, they automatically receive a Force rating of 1.  If such characters already have a Force rating of 1 or higher, it does not improve when they purchase the Padawan Survivor specialization.  Wary of a galaxy that has turned hostile, Padawan Survivors still put their faith in the Force as they were trained to do so from a young age.

[P]As former apprentices, these Padawans had been on the path to becoming Jedi Knights.  They received training in using the Force and a range of fighting techniques.  Unfortunately, their training was dominated with classroom lessons , and few had actual practical field experience unless they were allowed to join their masters in the Clone Wars.  Not only was their formal training abruptly cut short, but the availability of Jedi knowledge was severely limited after the issuing of Order 66.  That day was one of the darkest in the galaxy''s history, and it devastated the rare Padawans who lived through it.

[P]When the Jedi were branded as traitors and their order destroyed, those rare Padawans still alive were stranded with no resources and no support: their mentors were slain, their former clone trooper allies were hunting them at the Empire''s behest, and they had no one from whom they could seek aid.  In order to survive, these former apprentices were forced to seek no-questions-asked jobs or to subsist on their own.  Not all managed to remain hidden, though, with the might of the Empire and the newly-formed Inquisitorius after them at every turn.

[P]While on the run, temporary allegiances were often all that was practical, as lasting bonds proved nearly impossible to maintain, especially when Padawans revealed their abilities.  Saving a friend with the Force would frequently result in the friend''s abandonment out of fear of the Empire.  Only those already willing to defy the Empire would take that chance.  A rebel cell, for instance, could take in Force users because the lives of its members were forfeit already.  For Padawan Survivors, whose lives had been shattered by the Empire, rebellion was an exceptionally tempting opportunity.

[P]Having access to an almost-extinguished source of power, Padawan Survivors are capable of unbelievable acts.  Capable fighters and practiced at disappearing, they are able to effectively supplement a covert squad of rebel fighters or smugglers alike.  the Force is a powerful ally, and these former Padawans are eager to use it again openly if it means honoring their dead masters and tearing down Imperial rule.', NULL, '[]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["PARRY","CONSTVIGIL","STRSMART","NOBFOOL"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["TOUGH","REFLECT","SLEIGHTMIND","SECRETSOFTHEJEDI"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":2,"cost":15,"talents":["PARRY","BAL","SMOOTHTALK","MASSHAD"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":false},{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["DISORIENTSTRIKE","UNCANREAC","SMOOTHTALK","TRUSTNOONE"],"directions":[{"right":true,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":true},{"right":true,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["SECRETSOFTHEJEDIIMP","TEMPLETRAINING","FORCERAT","DEDI"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('PATH', 'Pathfinder', '[H4]Pathfinder[h4]
Few are as capable of exploring a planet and discovering its secrets as a Pathfinder. The combination of Pathfinders'' Force talents and their training enables them to quickly and precisely complete a search, even under the most adverse conditions. A Pathfinder can survive in a hostile wilderness for weeks or months, living off the land with minimal supplies and possibly a faithful companion animal. In fact, some Pathfinders are said to be able to bond with their companions through the Force, communicating with them mentally, seeing through their senses, and even directing their actions. 

[P]Pathfinders acquire [B]Medicine, Ranged (Light), Resilience,[b] and [B]Survival[b] as additional career skills. If this is the character''s starting specialization, he may choose two of these skills and gain one free rank in each, without spending starting experience. These skills are focused on complementing the Seeker''s career skills, so that the character becomes even more capable of operating independently. The addition of Medicine is primarily for personal benefit but can also be useful in aiding the character''s companions. 

[P]Some Pathfinders follow this career because they discover they have a knack for independent survival. This is most commonly true for Force-sensitive Individuals who matured on primitive and uncivilized planets. If his small community was surrounded by hostile wilderness, a character is certain to have spent his youth exploring that environment—likely making friends with many of the wild animals present there. Pathfinders'' natural abilities likely led them to a position of some responsibility within their tribe. Their roles might have included securing the safety of the surrounding wilderness and maintaining any trails leading to agricultural resources or other necessities needed by the community''s residents. 

[P]Others who follow the Pathfinder career do so out of a preference for the company of animals over that of sentient beings. Through their Force abilities, some learn to establish effective communications with the relatively primitive minds. In these interactions, they find that they enjoy the sincerity and straightforward nature of wild creatures.', NULL, '["MED","RANGLT","RESIL","SURV"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["GRIT","KEENEYED","FORAG","SWIFT"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["KEENEYED","OUTDOOR","TOUGH","OUTDOOR"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["ANIMALEMP","ANIMALBOND","GRIT","SLEIGHTMIND"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":false},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":false}]},{"index":3,"cost":20,"talents":["MENTBOND","FORCERAT","QUICKMOVE","TOUGH"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":false}]},{"index":4,"cost":25,"talents":["SHAREPAIN","ENDUR","NATOUT","DEDI"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":false,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":false}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('PEACE', 'Peacekeeper', '[H4]Peacekeeper[h4]
Across the galaxy, there are always tyrants, and those unlucky enough to suffer under their rule. Some Guardians take direct action through military force to attempt to overthrow such despots. Other Guardians see wars ravaging planets and harming the weak and defenseless. They step in to defend those innocents, and enforce peace at the tip of a lightsaber. These Guardians are often known as Peacekeepers. 

[P]Peacekeepers acquire [B]Discipline, Leadership, Perception,[b] and [B]Piloting (Planetary)[b] as additional career skills, and if this is the PC''s starting specialization, the PC gains one rank in each of two of these skills. This combination ensures that they can recognize threats and respond to them in an effective and timely manner. Skilled Peacekeepers must be able to effectively delegate assignments to allies while reserving themselves to confront the challenges for which they are most adept. 

[P]Many Peacekeepers only assume this specialization after they have been thrust into a position of authority—sometimes repeatedly. Because of their naturally protective personalities, these Guardians want to do everything in their power to protect their friends. Often, they decide the best choice is to become the best leader they can, out of a sense of responsibility rather than a desire for power. 

[P]Characters who pursue the Peacekeeper''s path seldom limit their activities to a single region. Often once one region has been pacified or a tyrant overthrown, a Peacekeeper sets his sight on the next challenge and leads his friends and fellow freedom fighters to overcome it. Under the shadow of the Empire, Peacekeepers are always needed.', NULL, '["DISC","LEAD","PERC","PILOTPL"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["COM","CONF","SECWIND","COMMPRES"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["COMMPRES","TOUGH","SECWIND","CONF"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":true,"down":true,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["TOUGH","ENHLEAD","COM","FLDCOMM"],"directions":[{"right":true,"down":true,"left":false,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":3,"cost":20,"talents":["STNERV","SECWIND","TOUGH","FLDCOMMIMP"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":true,"down":true,"left":true,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["UNITYASSAULT","DEDI","FORCERAT","NATLEAD"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('PERFORMER', 'Performer', '[H4]Performer — The Burden of Art[h4]
The Performer must always be the center of attention, and if all eyes aren''t on the Performer, he has ways to make them shift their focus. For them, all the world is a stage, and the Performer is always putting on a show. They can lie with more sincerity than even the Politico, and do so as easily as if they were running lines for a one-man showing of the Kallea Cycle. They can be as charming as a diplomat, and leave their targets enchanted and completely manipulatable. And far too many people underestimate the strength many Performers must possess for acrobatics, athletics, and even live theater. 

[P]Performers receive [B]Charm, Coordination, Deception,[b] and [B]Melee[b] as additional career skills. If this''Is the character''s starting specialization, he gains one free rank in each of two of these skills of his choice, without spending experience. The Performer often leans on pouts, winks, warm smiles, and well timed physical contact mixed with outright lies to get whatever he wants from whomever he wants. He draws on the best lines from the greatest works of literature, theater, and holo from millennia past, and always has a unique, flattering compliment for any being from whom he might want something. 

[P]Other Performers may rely on different tactics in their interactions. A cutting comedian or brilliant actor can hurl a litany of insults that cut to the core of most beings, making them question their worth and their right to deny the Performer what he wants. Unfortunately, these almost psychotic breaks are just as likely to be directed against their closest allies and assistants as enemies. The Performer knows how to use this to his advantage, though, and can create a scene to distract a bouncer while his friends sneak into a club that would otherwise never have granted them access. 

[P]However, there is often more to a Performer than just words. Performers may include dancers, acrobats, jugglers, and other individuals who must possess impressive coordination and be at peak physical condition. Their acrobatic abilities can give some Performers an unexpected edge in a fight. In addition, many have been trained in martial arts and the use of stage weaponry for roles in theater or holovids. The agility and overall fitness required to perform on stage means they are often in great shape, and as such, it is not uncommon for the Performer to be the last one standing when the dust settles. 

[P]Whether the character is a galaxy-famous magician or merely the member of a traveling troupe of acrobats, the players can build their entire party around a Performer. Performers need an agent, bodyguards, assistants, technicians for their performance, a pilot, perhaps a personal physician, and certain friends or family for their entourage. Performers are able to take the lead in social situations and provide support during combat, but can also take a back seat to a diplomatic leader able to wrangle him. The only downside to including a Performer in the party is that whatever his specialty, he makes his living through some sort of acting. Once can never be sure what a Performer thinks about everyone else.', NULL, '["CHARM","COORD","DECEP","MELEE"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["SMOOTHTALK","KILL","DISBEH","CONV"],"directions":[{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["DISBEH","CONGENIAL","DODGE","JUMP"],"directions":[{"right":true,"down":true,"left":false,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":false}]},{"index":2,"cost":15,"talents":["DISBEH","INTENSPRE","NATATHL","SECWIND"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":3,"cost":20,"talents":["SMOOTHTALK","DISBEHIMP","GRIT","TOUGH"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":false},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["BIGGESTFAN","DECEPTAUNT","COORDODGE","DEDI"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('PILOT', 'Pilot', '[H4]Pilot — A Galaxy of Destinations[h4]
Plenty of folks know how to fly a starship, but a Smuggler who specializes as a Pilot develops a relationship with his ship, and it becomes an extension of his wit and his will. He can make a plodding old transport run far above its performance ratings, and given time and some modifications, he can turn it into one of the fleetest and most maneuverable craft ever to take to the stars. 

[P]A Pilot is naturally focused on mastering his craft, and his additional career skills show it: [B]Astrogation, Gunnery, Piloting (Planetary),[b] and [B]Piloting (Space)[b]. If this is the character''s starting Specialization, he may choose two of these skills and gain one free rank in each, without spending starting experience. A Pilot''s talents further reinforce his dominance in the cockpit. 

[P]Pilot is another specialization that rarely leads to unemployment. If a Pilot doesn''t already have his own ship (and the inevitable Obligation that goes with it), he will likely be able to sign on with any number of groups, criminal or otherwise. Once he establishes his competency at the controls, he''ll be able to get some fairly choice assignments. A Player Character Pilot will be considered indispensable to his group, especially after the first space battle or ship-related crisis.

    [H4]Pilot — Bound for the Stars[h4]

Out among the stars, engines screaming through  the cockpit whiel performing a maneuver that would send lesser beings into seizures or unconsciousness, only then is the Pilot truly himself. While the sheer joy of flying is often rewarding, most Pilots gain true satisfaction when they pit themselves and their machines against an aggressor force and duel it out in the blackness of space.

[P]For Pilots, [B]Astrogation, Gunnery, Piloting (Planetary),[b] and [B]Piloting (Space)[b] are additional career skills. In addition to being skilled at flying and knowing where to go, Pilots must also be exceedingly tough and trained to endure the harshest conditions if they are going to have the remotest chance of living when the worst happens.

[P]No one denies the special place Pilots have in a military organization, least of all the Pilots themselves. Most have at least a certain amount of cockiness (sometimes bordering on arrogance), which is to be expected when a person wraps a few tons of machinery around himself and hurls into the void of space to regularly risk instant vaporization. The average life expectancy of a typical Alliance starfighter Pilot engaged with Imperial forces is extremely low; only by being the very best does a Pilot stand a chance of survival or success.

[P]Not suprisingly, true Pilots are considered a precious commodity in the Alliance. Commanders are often seen as being too cautious in deplying them; each mission is almost gaurenteed to cost a few lives and a few machines. The Rebellion ultimately stands or falls on the capacity of its Pilots to face the overwhelming odds of the Empire''s best and somehow be better.', NULL, '["ASTRO","GUNN","PILOTPL","PILOTSP"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["FULLTH","SKILLJOCK","GALMAP","LETSRIDE"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["SKILLJOCK","DEAD","GALMAP","RAPREC"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["FULLTHIMP","DEADIMP","GRIT","NATPIL"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["GRIT","FULLTHSUP","TRICK","DEFDRI"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":false},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":4,"cost":25,"talents":["MASPIL","DEDI","TOUGH","BRI"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('PIRATE', 'Pirate', '[H4]Pirate — Nefarious Opportunists[h4]

Pirates care about helping themselves, and they do not care how they do it.  They''ll lead a crew to attack well-stocked spaceships.  They''ll recruit a naive idealist to steal contraband so they can sell it at a profit.  some pirates have even seen that there are greater potential rewards-such as ending the ever-increasing Imperial stranglehold over their independence-in working as somewhat reliable rebels.

[P]The additional career skills a PC receives when taking the Pirate universal specialization are [B]Coercion[b], [B]Deception[b], [B]Knowledge (Underworld)[b], and [B]Skullduggery[b].  These PCs know the galaxy is a dangerous and unforgiving place, and are always ready to exploit this fact and make serious credits.

[P]For these cunning "entrepreneurs" unafraid to break a few rules, take some risks, and resort to violence, anyone else''s gains can become their own.  The first law of piracy is that everything belongs to whomever can take it.  However this is an honorable profession; it''s just business, and never personal.  At least, until someone else makes it personal.

[P]While Pirates work for their own gain, the best opportunities require at least temporary support.  Inside contacts, talented slicers, and reliable pilots can be invaluable-as are plenty of hired muscle to back up threats.  Skilled Pirates are adept at manipulating those they work with (and anyone in their way) to achieve their goals, often via coercion and leveraging their dangerous reputations.  some might never need to fire a blaster, such is their terrifying renown, while others delight in violence that normal society does not allow.

[P]Unrestricted by standard conventions of right and wrong, the methods that Pirates can use vary widely.  Taking what they want is easy when no one else is left standing, so violence is frequently a first resort.  If violence alone can''t work, or is impractical, they rely on cunning.  Pirates might propose mutually beneficial agreements to secure assets essential to completing a job.  Whether or not the deals are balanced or the Pirates even hold up their end is of little concern to them.  this doesn''t mean that some Pirates won''t develop long-term arrangements, but often both parties are aware that such deals are strong only as long as both sides profit handsomely.  Even so, most Pirates value their independence too much to be tied down for long, even to lucrative outsiders.

[P]Regardless, Pirates sometimes find themselves aiding fledging anti-Imperial cells.  these desperate, outnumbered bands have few legal options for support.  Many come to rely on the experience of Pirates for help-especially in learning how to survive outside the law and in finding unsavory but useful contacts.  what might start purely as business dealings can grow to a more lasting association over exciting times, shared conflicts, and a few bottles of something jointly stolen.  whether a band of Pirates commits to a group of rebels for profit, shared aggression against the Empire, or pure boredom may never be known, but Pirates'' aid can keep such groups alive and fighting long after others have fallen.

[P]Pirates can be duplicitous, conniving, violent con-artists, but they are almost always effective.  Whether they are finding criminally-profitable jobs or manipulating their own comrades to make them more effective against the Empire, Pirates are constantly twisting situations to gain the most benefit.  They almost always focus the benefit for themselves first, but sometimes it can spill over to their allies.', NULL, '["COERC","DECEP","SKUL","UND"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["BLA","TOUGH","QUICKDR","KNOWSTHEROPES"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["GREASE","TOUGH","FEARSOMEREP","COMMPRES"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":true,"down":true,"left":true,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["BLA","DOUBLETALK","STRSMART","INTIM"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["FEARSOMEREP","INTENSPRE","COMMPRES","STNERV"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["PREPTOBOARD","ALTEREDDEAL","NATROG","DEDI"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":false}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('POLITICO', 'Politico', '[H4]Politico — The Gift of Leadership[h4]
If there is one thing a Politico knows how to do better than anyone else in the galaxy, it''s talking. He can talk to anyone about anything in any necessary way. What others accomplish with might and fear, a talented Politico may well achieve with a few well-placed words and a decent plan. 

[P]Politicos gain the Career skills of [B]Charm, Coercion, Deception,[b] and [B]Knowledge (Core Worlds)[b]. If this is the character''s starting Specialization, he may choose two of these skills and gain one free rank in each, without spending starting experience. A Politico might join a discussion, speech, or debate in any number of ways. With his talents, he might act to inspire greatness in those around him, or he might know just what to say to cut an opponent to the core, diminishing his confidence and leaving him vulnerable. 

[P]Politicos in the Outer Rim are usually up to something; ambition is hardwired into their very being. They may not yet know what they wish to accomplish, but when they see an opportunity to achieve some kind of greater goal, they will turn all their will and personality towards achieving it. Politicos might sign on to temporarily work for another, but they will not long be happy in a subservient role. Leadership is the core of who they are. 

[P]In a group, the Politico works best as the front-man, or the "face." More than anyone, he is best suited for initial contacts with any being or group, and he''s the best to have at any negotiation, social gathering, or interrogation. There are even times when he can bring up morale in combat and crisis situations, though the palace throne room, corporate board room, or casino floor tend to be better battlefields for him.', NULL, '["CHARM","COERC","DECEP","CORE"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["KILL","GRIT","PLAUSDEN","TOUGH"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["INSPRHET","KILL","SCATH","PLAUSDEN"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["DODGE","INSPRHETIMP","SCATHIMP","WELLROUND"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":false},{"right":true,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["GRIT","INSPRHETSUP","SCATHSUP","NOBFOOL"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":4,"cost":25,"talents":["STNERV","DEDI","NATCHARM","INTENSPRE"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('PROPAGANDIST', 'Propagandist', '[H4]Propagandist — From a Certain Point of View[h4]
Truth is often a matter of perspective, and Propagandists serve the Rebel Alliance by skewing this perspective in favor of their cause. To the Propagandist, truth is just as much worth pursuing as it is worth manipulating. Whether simply leaking the right facts to shift public opinion or creating outright fabrications to demoralize the enemy, a Propagandist understands the power of perception.

[P]Propagandists gain [B]Charm, Deception, Knowledge (Warfare),[b] and [B]Perception[b] as additional career skills. If this is the character''s starting specialization, he may choose two of these skills, gaining one free rank in each without spending starting experience. Propagandists leverage Perception to uncover the truth and use Charm or Deception to spin it to benefit the Rebel Alliance. Some Propagandists focus more on either weaving compelling rhetoric or telling believable lies, while others prefer to gain ranks in Charm and Deception equally, giving them maximum flexibility. 

[P]Propagandists play an important role in the Galactic Civil War. Even as the battles rage on and above many oppressed worlds, the Rebel Alliance wages an equally important struggle for the support of the galactic citizenry. While the Empire''s evil is obvious to most, few possess the courage to stand against such a brutal enemy. Propagandists must sway these people, distributing persuasive information as far and wide as possible, inspiring heroism in everyday citizens. 

[P]Ideally, a Propagandist reveals truths that the Empire would conceal: galactic atrocities, corruption, and the terrible cost of its policies. However, few Propagandists deal strictly in truth as such, more likely distributing misinformation to enrage the oppressed. Criticizing the ethics of such tactics is difficult when they serve the cause so effectively. Propagandists might argue that small lies expose much greater truths that the Empire tries to conceal. For some, news is as much a business as a political pursuit, while for others, propaganda is of paramount importance.

[P]In a group of Player Characters, a Propagandist can act as a master of information collection, interviewing civilians and even military personnel for rumors and secrets. Perhaps even more importantly, by planting information in the right ears, a skilled Propagandist can demoralize enemies, manipulating them into believing untruths. For this, a Propagandist is well served by a high Cunning and a high Presence.', NULL, '["CHARM","DECEP","PERC","WARF"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["GRIT","POSSPIN","INKNOW","CUTQUEST"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["INKNOW","POSSPINIMP","POSSPIN","TOUGH"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true}]},{"index":2,"cost":15,"talents":["BADPRESS","WELLROUND","GRIT","CONF"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":3,"cost":20,"talents":["TOUGH","CONF","DODGE","INFORM"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["POSSPIN","DEDI","INKNOWIMP","INKNOW"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('PROPHET', 'Prophet', '[H4]Prophet — A Cantor for a Choir[h4]
The Jedi Order''s proselytizing ebbed and flowed , much as the Force did throughout the Old Republic. Understanding of the Force couldn''t be pressured upon a student without causing resentment and anger, which promises a fall toward the dark side. So for Prophet s. they proselytized not to convert, but to offer a voice of hope and an opportunity to learn about the power of the Force.
[P]Now, with the Jedi Order destroyed and the Galactic Republic shattered, Prophets carry a fervor not seen before In the history of the galaxy. To them, their knowledge of the light side of the Force reflects the struggle against the dark. If the Galactic Empire is the shadow blotting out the stars, then Prophets are single points of light, hoping to ignite a candle here and there to light up the sky.

[P] Prophets gain the following additional career skills: [B]Charm, Coercion, Deception[b], and [B]Leadership[b]. Characters who start with this specialization first get one rank in two of these skills without spending experience.
[P]Like Advisors, this specialization directly interacts with people, granting them insight and counsel when needed. Unlike Advisors, Prophets address the crowd, not the individual. Their message has to reach as many ears as possible, in the hope that their ideas or warnings catch fire. Prophets influence communities, cities, or even planets if given a medium and a message.
[P]The medium comes in a variety of forms: a sermon on a soapbox or an altar, a HoloNet posting or recording, flyers or tracts passed from hand to claw, or even images on a poster, painting, or pirate transmission. It doesn''t matter what medium, only the passion and truth of the message.
[P]The message might be filtered through a religious lens, but not always. Prophets are keyed into the Cosmic Force more keenly, and images of the future provide wisdom, guidance, and, for followers, an identity. Since Prophets are only mortal, they can only try to interpret with mortal concepts and metaphors. They then have to translate that message into simple language, further diluting the content. The next person''s limited understanding then further alters t hat message. The real question is whether this constant alteration by verbal or visual transmission distorts the message or enhances it just as the Force intended.
[P]Prophets who use their abilities for evil or selfish ends have an easier time now during the Galactic Civil War. Those suffering from the Empire''s rule want a voice of hope to give them a reason to live on, and as long as the message doesn''t violate Imperial restrictions on religion or political sedition , Prophets can enjoy a safe (and profitable) career. Even on planets free from the Empire, other sources of oppression (slavery, Hutt influence, corporate interests, and the like) may drive people to a religious charlatan, especially one who can produce miracles.
[P]Even well -meaning Prophets should be wary, since it is much too easy for them to insert their own desires, needs, or fears into t heir visions, distorting them into their own ends, manipulating t heir followers into believing their own egos.', NULL, '["CHARM","COERC","DECEP","LEAD"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["GRIT","OVERWHELMINGAURA","RAPREC","CONGENIAL"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["SCATH","PLAUSDEN","INSPRHET","RAPREC"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["RAPREC","OVERWHELMINGAURA","GRIT","TWISTWORD"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":false}]},{"index":3,"cost":20,"talents":["FEARSOME","GRIT","INSPRHETIMP","CONGENIAL"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":true,"down":true,"left":false,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":4,"cost":25,"talents":["OVERWHELMINGAURAIMP","FORCERAT","FONTOFPOWER","DEDI"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":false,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('PROTECT', 'Protector', '[H4]Protector[h4]
Guardians are often driven by their compassion for the plights of those who cannot protect themselves. Protectors ensure these innocents never come to harm. Few are tougher than a Protector, and even fewer can get through his guard to attack those he defends. Even if his charges do suffer harm, the Protector possesses basic medical knowledge to heal their wounds. 

[P]Protectors gain the additional career skills of [B]Athletics, Medicine, Ranged (Light),[b] and [B]Resilience[b]. If this is the characters starting specialization, he may choose two of these skills and gain one free rank in each, without spending starting experience. This combination enables the character to assist those who are in need during a crisis. These skills complement many of the talent selections, so that the Protector remains capable of effectively shielding others from suffering harm without sacrificing his own capabilities. 

[P]Protectors could be considered bodyguards, but their efforts are seldom limited to protecting a single individual. Instead, Protectors are more likely to defend the needy on a larger scale. Often, they function as rescue workers, using their medical knowledge to stabilize injuries in the field and then providing additional protection. In other cases, Protectors may shelter refugees or other victims fleeing terrible situations. holding the line until the innocents can escape to safety. When a Protector does defend a single individual, It is likely because a great threat—even another Force user—pursues the person. 

[P]Some Protectors might come to master their abilities while working in a military or law enforcement role. Some Force techniques might manifest spontaneously as they instinctively act to keep companions safe. This could be particularly relevant for individuals who have not recognized their connection to the Force. Its presence might enable them to save an ally from danger in a seemingly inexplicable fashion. However, once these individuals realize the power they have, they must decide whether to continue their career and keep it a secret, or leave the life they''ve known and explore their new abilities.', NULL, '["ATHL","MED","RANGLT","RESIL"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["TOUGH","BOD","GRIT","TOUGH"],"directions":[{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["PARRY","PHYSICIAN","STIMSPEC","FORCEPROT"],"directions":[{"right":true,"down":true,"left":false,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["REFLECT","STIMSPEC","HEIGHT","CENTBEING"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["CIRCLESHELTER","FORCEPROT","GRIT","BOD"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":4,"cost":25,"talents":["CENTBEING","FORCERAT","DEDI","BODIMP"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('QUARTERMASTER', 'Quartermaster', '[H4]Quartermaster — Managing the Resources[h4]
An old military saying goes something like this—"Empty stomachs make for poor soldiers." The Quartermaster''s job is to ensure this doesn''t happen to the troops he supports. He also must ensure that weapons, ammunition, medical supplies, and everything else needed gets where it should be and into the right hands. Managing the flow of logistics is one of the most difficult tasks in any military organization, and the Quartermaster is the master of it. 

[P]Quartermasters gain [B]Computers, Negotiation, Skulduggery,[b] and [B]Vigilance[b] as additional career skills. If this is a PC''s first specialization, two of these four skills begin with a free rank each. Searching and manipulating data to their unit''s benefit is a trick many Quartermasters employ, as is finding (and stealing) necessary resources when the cupboards are otherwise bare. Anyone involved in supply is inherently enamored of preparedness at all times. 

[P]The greatest commanders in any military place extraordinary emphasis on supply, relying heavily on their Quartermasters to see to it that logistical needs are met at all times. An otherwise-successful campaign will come to a screeching halt, perhaps even degrading into a terrible rout, if supply lines are not maintained and the warriors engaged with the enemy lose access to food, ammunition, and other vital needs. The Quartermaster understands the unique and challenging puzzle of finding, securing, and moving assets, and he seeks to fulfill his unit''s needs no matter what is required.

[P]One of the greatest challenges for the Alliance is that of supply; the best Quartermasters in service to the Rebellion are indispensable assets. As long as other Alliance units are not endangered by their actions, Quartermasters are given great leeway in their methods for acquiring needed resources and getting them to the front lines. Many of the best Quartermasters indulge in more than a little larceny, often targeting criminal organizations and even the Empire itself to get what they need.', NULL, '["COMP","NEG","SKUL","VIGIL"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["KNOWSOM","SMOOTHTALK","WHEEL","GRIT"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["SMOOTHTALK","GREASE","MASMERC","TOUGH"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":false},{"right":false,"down":true,"left":false,"up":true}]},{"index":2,"cost":15,"talents":["GRIT","WHEEL","BOUGHT","GRIT"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":3,"cost":20,"talents":["KNOWSOM","SOUNDINV","SOUNDINV","INTENSFOC"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":4,"cost":25,"talents":["DEDI","NATNEG","SUPREF","TOUGH"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":false},{"right":true,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('RACER', 'Racer', '[H4]Racer — Eyes to the Future[h4]
Racers race. Whether by landspeeder, airspeeder, starship, or on foot, the Racer speeds forward to be the first, and the fastest. However, the Force grants not only extra sensory insight about the race, but also guides Racers to think about what the race means.

[P]Racers receive [B]Cool[b], [B]Coordination[b], [B]Piloting (Planetary)[b] and [B]Piloting (Space)[b] as additional career skills. Characters who select this as their starting specialization may choose two of these skills and gain one free rank in each without spending starting experience.

[P]For these characters, racing is less about speed and more about knowing their position in time and space. Racers don''t ask how to get somewhere, they intuit their arrival at their destinations. In many ways, they  push to understand the future in relation to the positioning of self. The Force, racing forward in time, in its own way, has carved a path that Racers must follow.

[P]With the Force, physical obstacle aren''t obstacles per se. They represent perceptual shadows on the fabric of space time. Racers use the Force to peer into these shadows, seeing not only what exists in the shadow, but also when such interactions exist in the shadow. If they don''t exist in the shadow at all, Racers avoid them. They were either never supposed to be there or their life possibly ended before then. If Racers know they don''t exist at some point in a  potential future, then they can pick a future in which they do.

[P]As their skills develop, this perception extends from their own relative position to those of other living beings. Racers become predictive not only about their own place in space-time, but also about other beings'' places relative to them. This allows Racers an eerie ability to be at the right place at the right time to intercept an individual. Catching a bounty just before the target escapes or rescuing a person in need at just the right time is an incredible benefit to the community. In the wrong hands, this talent can be terrifying, as dark side Force users employ it to talk their target stalking and harassing with a looming presence at every turn.

[P]Obviously, Racers must have a calm demeanor and steady hands, even if the adrenaline rush and excitement of a race would shake the steeliest nerves. Anger can push them to excessive aggression, and fear can lead to hesitation at the wrong moment. Mistakes cost lives, not just for Racers'' lives but also those of other pilots, audience members, pit crew and innocent bystanders. Many Racers claim to attain a paradoxical stillness in the middle of a race, achieving a transcendental oneness with vehicle, speed, and self. At this point, the Force flows naturally through them. However, ordinary, practiced skill in piloting a starship or speeder is a must, even Racers can''t rely on the Force alone.

[P]Podracing is the first obvious practical application for this specialization. The Racer specialization also can be useful with everything from racing on foot to racing starships. For  Racers, notions of time, space and position become almost meaningless. Racers can be twelve parsecs away from a target but close to interception with a fast hyperdrive, while those on foot may be only a yard away but separated by a high, impassable durasteel wall. Which one of these Racers is closer to the goal?', NULL, '["COOL","COORD","PILOTPL","PILOTSP"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["GRIT","SKILLJOCK","CONDITIONED","SHORTCUT"],"directions":[{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["SHORTCUT","FULLTH","SHORTCUT","CONDITIONED"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":false}]},{"index":2,"cost":15,"talents":["SKILLJOCK","FULLTHIMP","FREERUN","FREERUNIMP"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":false}]},{"index":3,"cost":20,"talents":["GRIT","FULLTHSUP","FORCERAT","BETTERLUCK"],"directions":[{"right":true,"down":true,"left":false,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":false}]},{"index":4,"cost":25,"talents":["SUPHUMAN","DEDI","SHORTCUTIMP","INTUITEVA"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":false}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('RECRUIT', 'Recruit', '[H4]Recruit[h4]
Due to [B]Age of Rebellion''s[b] focus on the Galactic Civil War, most groups of PCs find themselves embroiled in conflict very quickly. Against a force like the Empire, any form of military training can mean the difference between life and death. While the Alliance isn''t as organized or regimented as the Empire, they do try to give a decent number of their members some form of combat training. This training helps to enhance the Rebels'' chance not only to survive in combat but to fight effectively to achieve their goals. 

[P]The Recruit specialization is a universal specialization, and the experience cost to take it is ten times the total number of specializations that the character would have after adding the new specialization. While this means that the specialization costs the same as a career specialization, note that universal specializations are not career specializations. 

[P]The additional career skills a PC receives when taking this specialization are [B]Athletics, Discipline, Survival,[b] and [B]Vigilance[b]. Alliance operatives who go through this training enhance their physical fitness, awareness, and general competency at a wide variety of skills. Those who commit extra time and effort can also enhance their abilities with weapons and ground vehicles, as well as their general knowledge of the many worlds to which they may end up traveling. 

[P]Characters from almost any career can benefit from becoming a Recruit and gaining some basic military training. Small teams of specialists going up against the Empire''s best will likely need to call upon every scrap of combat ability they collectively possess to survive dramatic fights for their very lives. 

[P]The Alliance strongly recommends such training for any Rebels who are actively going into the field, regardless of their career, goals, or role in a team. Even Diplomats are actively encouraged to undergo military training; they do no good to anyone if they cannot come back alive from their latest efforts to negotiate a treaty or acquire supplies. Becoming a Recruit might not make a character a full-fledged special forces hero, but it certainly doesn''t hurt.', NULL, '["ATHL","DISC","SURV","VIGIL"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["BASICTRAIN","SECWIND","OUTDOOR","TACTTRAIN"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["SECWIND","VEHTRAIN","WELLTRAV","TOUGH"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":2,"cost":15,"talents":["QUICKDR","GRIT","TOUGH","SPARECL"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":3,"cost":20,"talents":["SECWIND","JUMP","GRIT","CREATKILL"],"directions":[{"right":true,"down":true,"left":false,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["DYNFIRE","DEDI","TOUGH","ENDUR"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":false}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('RETIREDCLONE', 'Retired Clone Trooper', '[H4]Retired Clone Trooper — Decommissioned Soldiers[h4]

Literally bred for battle, these warriors were the bulk of the Republic''s fighting force in the Clone Wars.  Exceptionally trained, they were invaluable allies to the Jedi Order until they were manipulated into betraying its members.  As the clones'' accelerated aging process continues unabated, their life spans are reaching their ends, but they remain effective, tactically minded warriors whom none should underestimate.

[P]The additional career skills a PC receives when taking the Retired Clone Trooper universal specialization are [B]Discipline[b], [B]Knowledge (Warfare)[b], [B]Ranged (Heavy)[b], [B]Ranged (Light)[b], [B]Resilience[b], and [B]Vigilance[b].  Player Characters who take this universal specialization must be human males, given that they were once clone troopers, but gain a wider set of career skills from their Kaminoan training.  Such PCs have seen too much war, but realize that the Empire cannot be stopped unless they lend their skills to the battle.

[P]Clone troopers were grown on Kamino using the human bounty hunter Jango Fett as their genetic template.  These clones were engineered with an accelerated growth rate in order to become effective combatants in a significantly reduced period of time, and they had inhibitor chips installed to prevent unintended violent outbursts-or at least that was the official reason.  While the troopers developed, there were given extensive generic combat training in addition to specific training at pilots, gunners, shock troopers, and a variety of other specializations.  Possessing the ability for creative thought, clone troopers were significantly more effective than the mass-produced, programmed droids they were sent to combat.

[P]During the Clone Wars, clone troopers became battle brothers; after surviving countless battles together, they established a fierce loyalty not only for each other but also for their Jedi generals.  Without the contributions of both the clone troopers and Jedi, the Republic would have had no chance of winning.  the bond appeared unbreakable to all.

[P]Near the end of the war, Chancellor Palpatine branded the Jedi as traitors and ordered the clone troopers to eliminate their Jedi commanders, no questions asked-and they did.  almost no Jedi or Padawans survived.  soon afterward, due to their accelerated aging, the clone troopers were decommissioned and replaced with non-clone stormtroopers, who lacked their intensive training.  Once retired, some clone troopers were horrified about their execution of Order 66.  a few went as far as removing their inhibitor chip, blaming it for making them follow the order, since troopers who had it removed it beforehand did not carry out the order.

[P]Today a handful of these soldiers still survive and grapple with the consequences of their actions.  Whether due to shame for their role in Order 66, anger against the Empire, or a desire to continue to fight for their Clone Wars ideals, a few have abandoned their leisure to fight in the nascent rebellion.  Retired Clone Troopers are powerful allies despite their age.  Not only do they retain their tactical combat knowledge and training, but they have striven to maintain their genetically imbued physical conditioning as well.  this enhanced by the practical skills derived from their years of fighting and winning battled.  as former soldiers of both the Republic and the Empire, they also know the location of multiple abandoned military bases scattered across the galaxy.  Experience is power, and Retired clone Troopers are steeped in it.', NULL, '["DISC","RANGHVY","RANGLT","RESIL","VIGIL","WARF"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["TOUGH","STEADYAIM","SPARECL","GRIT"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["COMBATVETERAN","DURA","SWIFT","FAMSUNS"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":false},{"right":true,"down":true,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["GRIT","STIMSPEC","TOUGH","DURA"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":3,"cost":20,"talents":["PERSISTARGET","PWRBLST","COMBATVETERAN","PWRBLST"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["DEDI","COMRADESINARMSIMP","COMRADESINARMS","ENDUR"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":false}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('RIGGER', 'Rigger', '[H4]Rigger — Vehicular Innovator[h4]
While most Rebel Aces operate standard vehicles maintained by engineering crews, a surprising number bring their own private vehicles with them into a fight. The Rigger doesn''t believe in risking his life from the seat of a stock-class anything, and is always adding, tweaking, and fine-tuning his vehicle not only to achieve the highest performance, but also to bring unexpected surprises with him to the battlefield.

[P]Considering how outnumbered the Rebels find themselves in almost every engagement, it is no wonder that some of the Rebel Aces have taken it upon themselves to increase their survivability by learning about their vehicle. Riggers tend to have the highest rate of survivability in combat, and their offensive output at the start of a combat engagement can sometimes end a fight before it begins. 

[P]Riggers receive [B]Gunnery, Knowledge (Underworld), Mechanics,[b] and [B]Resilience[b] as additional career skills. If this is the character''s starting specialization, he gains one free rank in each of two of these skills of his choice, without spending experience. The Rigger is fascinated with the golden age of innovation in starship engineering that exists during the Galactic Civil War. He keeps up to date with the latest technical journals and even trolls shadowfeeds, following his favorite engineers. He has a number of friends in the underworld''s outlaw tech community, who provide parts and kits to test on his vehicle of choice. If his ship is somehow blasted and left adrift, leave it to the Rigger to find some way to get it moving again. 

[P]The Rigger is resilient in the face of a challenge, and usually turns to technology to find a solution to most problems he might encounter. The Rigger believes in his customized ship''s ability to outperform any other vessel on the battlefield. He has painstakingly fine-tuned it to fly faster and further, hit harder, and take more punishment than the competition. Despite his impressive ability to mitigate damage done to his ship, a Rigger is a cautious pilot, and bemoans every dent and scratch his ship accrues during a battle. If a Rigger finds he is still somehow outgunned, he can jury-rig a special trick for the enemy on the fly to regain the technological advantage. 

[P]Most every team can benefit from a Rigger within their unit. Riggers bring a technological expertise that can apply to a variety of circumstances, and in combat, their vehicles are extremely durable offensive juggernauts. Riggers are also the only Ace to possess underworld contacts, which can prove useful for supplies, information, and even allies during missions. The biggest asset a Rigger brings to a team, though, is the element of surprise. Imperials don''t expect an X-wing to have replaced its astromech slot with a bomb-bay—until the ordnance is already detonating across their carrier''s bridge.', NULL, '["GUNN","MECH","RESIL","UND"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["BLA","TOUGH","GEARHD","LARGEPROJ"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["GRIT","FANCPAINT","SIGVEH","LARGEPROJ"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":false,"up":true}]},{"index":2,"cost":15,"talents":["BLA","OVERAMMO","TUNEDTHRUST","BOLSTARMOR"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":false,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":3,"cost":20,"talents":["TOUGH","CUSTCOOL","GEARHD","FORTVAC"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":4,"cost":25,"talents":["DEDI","TUNEDTHRUST","NOTTODAY","REINFRAME"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('SABOTEUR', 'Saboteur', '[H4]Saboteur — Making Thing Stop[h4]
Almost anathema to the usual technician''s mentality, the Saboteur specializes in disrupting and destroying technical and mechanical assets. His job is to diminish the enemy''s capacity to wage war by denying the enemy use of its weapons and vehicles. Of course, it takes a high degree of understanding about how something works in order to ensure it ceases working, or better still, to ensure it never works again. 

[P]For a Saboteur, [B]Coordination, Mechanics, Skulduggery,[b] and [B]Stealth[b] are all additional career skills, and if this is the first chosen specialization, the PC gains a free rank in two of these. Saboteurs are, by nature, covert operation specialists with a strong need to be able to sneak in and out of enemy facilities. In addition, they understand that disrupting the computer networks that run such facilities is a key to success. 

[P]Blowing things up is a popular way to commit sabotage, and Saboteurs are often the best at handling demolitions tasks (often using a combination of Mechanics and Skulduggery). However, there are many other ways to disrupt and destroy machinery, and the Saboteur knows them all. Most often, he will seek a way to cause the most damage and the most chaos at just the right moment. For the Saboteur (especially one with a sense of style), timing is everything. 
[P]The Alliance makes quiet yet effective use of its Saboteurs. Though terrorism is not a part of the battle plan (and is expressly forbidden by Mon Mothma and the rest of the Alliance Council), acts of military sabotage are known to be highly effective in evening the odds before a battle. Most commanders in the Rebellion will simply indicate a target and a time frame, allowing the Saboteur to use his creativity and resourcefulness to achieve the objective.', NULL, '["COORD","MECH","SKUL","STEAL"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["RESOLVE","SECWIND","GRIT","RAPREC"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["GRIT","PWRBLST","TOUGH","SECWIND"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":true,"down":true,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["TIME2GO","RAPREC","RESOLVE","HARDHD"],"directions":[{"right":true,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":3,"cost":20,"talents":["TIME2GOIMP","PWRBLST","SELDETON","TOUGH"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":false},{"right":false,"down":true,"left":false,"up":true}]},{"index":4,"cost":25,"talents":["DEDI","MASGREN","SELDETON","HARDHDIMP"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('SAGE', 'Sage', '[H4]Sage[h4]
Many Consulars know the universal truth: knowledge is power, and understanding a situation can give one a decisive advantage. This holds just as true when resolving disputes or negotiations as it does on the battlefield. A Sage focuses on studying the world around him, recognizing that information offers tremendous advantages to himself and his allies. He then uses that power to help change the hearts and minds of others to achieve his goals. 

[P]Equal parts scholar and diplomat, Sages gain the additional career skills [B]Astrogation, Charm, Cool,[b] and [B]Knowledge (Lore)[b]. If this is a PC''s first specialization, the PC gains one rank in each of two of these skills. Sages see knowledge and understanding as the basis for long-term peace and harmony. It is their belief that hatred often springs from ignorance. When a sentient comes to appreciate the backgrounds of another being''s beliefs and practices, it becomes far easier not only accept that being but to feel compassion for him. 
[P]Some researchers may become lost in their academic pursuits, obsessing over dry facts while blind to the plight of the weak and helpless. Not so a Sage, who maintains connections to those around him via the Living Force. The Force provides a means of grounding Sages'' studies so that they keep what they learn in perspective, always mindful of how they can use their knowledge to help others.', NULL, '["ASTRO","CHARM","COOL","LORE"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["GRIT","KILL","RESEARCH","GRIT"],"directions":[{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["SMOOTHTALK","RESEARCH","CONF","KNOWSPEC"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":false}]},{"index":2,"cost":15,"talents":["VALFACT","SMOOTHTALK","KNOWSPEC","ONEUNI"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":false}]},{"index":3,"cost":20,"talents":["FORCERAT","GRIT","PREEMAVOID","KNOWSPEC"],"directions":[{"right":true,"down":true,"left":false,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":4,"cost":25,"talents":["BAL","FORCEALLY","NATNEG","FORCERAT"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":false,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('SAPPER', 'Sapper', '[H4]Sapper — To Construct and Destroy[h4]
Sappers have a versatile role in the Alliance. These personnel are responsible not only for building encampments, installations, landing areas, and more to support the war against the Empire. but also for seeking out and destroying many of the same that the enemy possesses. This means these combat Engineers must combine stealth, survival skills, and situational awareness to find suitable locations and analyze defensive possibilities, as well as using the
same skills to probe for enemy structural weaknesses that can be exploited with suitable explosives.

[P]Sappers receive [B]Athletics, Knowledge (Warfare), Mechanics,[b] and [B]Survival[b] as additional career skills.  Characters who select this as their starting specialization may choose two of these skills and gain one free rank in each without spending starting experience.

[P]Once Sappers find a good location for construction, they must deal with the logistical demands of supplies. Construction efforts mean they have three bosses that will never agree: the environment, the laws of physics, and their commander. Sappers prioritize each differently, and that decision can make or break a construction project.   As with most support
jobs, when Sappers do an excellent Job, no one notices. Alliance soldiers don''t give a second thought to a warm bunk and good lighting in a base, for example, or pilots to a spacious and smooth-floored hangar If these aren''t present, however, Sappers get the blame (and also the overnight repair duties) .


[P]Sappers do see battle, perhaps more so than any other support personnel save medics.  Command sends Sappers to sneak up to enemy fortifications to find weaknesses and entry points This work often requires a hands-on inspection of the enemy base, looking for cracks in walls, exposed power lines or sewage pipes, or unattended guard rotations and resupply schedules. A scouting mission requires stealth or a cover identity, and Sappers must avoid capture or death from guards or automated security systems while successfully mapping the enemy''s weak points.

[P]Sappers who survive initial scouting missions must then infiltrate enemy sites to set explosive charges, carefully cut away security grids, or perform another act of sabotage, al l while avoiding being killed by blaster fire or a mistimed explosive charge. Even if capture or death is unavoidable, Sappers must press on, as the lives of many of their comrades depend on their sacrifice.

[P]After all that. Sappers who survive may still have to pick up a blaster and join the rest of the soldiers in storming the fortification. Perhaps the operation went off without a hitch, and the Alliance has provided evac to carry Sapper teams back to safety. Many refuse to retreat. They can still carry a weapon, and every body counts in battle. In the end, Sappers risk their lives three times over.', NULL, '["ATHL","MECH","SURV","WARF"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["CONSTSPEC","TOUGH","DURA","GRIT"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["KNOWSCH","CONT","CONSTSPEC","PWRBLST"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["GRIT","DURA","IMPDEF","PWRBLST"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":false}]},{"index":3,"cost":20,"talents":["UTIL","STRONG","IMPDET","MASGREN"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["WEAKFOUND","DEDI","IMPPOS","MASTDEMO"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":true,"down":false,"left":true,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('SCHOLAR', 'Scholar', '[H4]Scholar — The Gift of Knowledge[h4]
[P]At first, the idea of a Scholar wandering with a bunch of ne''er-do-wells in the Outer Rim might seem a bit odd, if not downright ridiculous. However, with all of the dangers and wonders of "a thousand thousand worlds,'' having someone around who actually knows something more than how to reload a heavy blaster could be exceedingly useful under any number of circumstances. This is especially true when a group is faced with something truly unknown, or needs to find something that simple tracking alone cannot locate.

[P][B]Knowledge (Outer Rim), Knowledge (Underworld), Knowledge (Xenology),[b] and [B]Perception[b] are the Scholar''s bonus career skills from his specialization. If this is the character''s starting Specialization, he may choose two of these skills and gain one free rank in each, without spending starting experience. These skills emphasize both his role as a font of information and his keen awareness of his surroundings. 

[P]Even in the Outer Rim, there are those who have a keen respect for knowledge and learning. Even criminal overlords find having some "brains" around helps them when they want to expand their operations or exploit a new opportunity. Other Scholars, however, are far more interested in getting out into the galaxy, seeing for themselves the things they wish to study, and digging around in ancient places for the lost knowledge they want to uncover. 

[P]A Scholar in a group is very likely of the field researcher variety; seeking allies with physical capabilities who can defend him is a matter of simple expediency. It may be that he''s signed on with some kind of operation that actually has no direct impact on his research, but the group is likely to travel to places he wishes to go, which suits his desires well.', NULL, '["OUT","UND","XEN","PERC"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["RESPSCHOL","SPKBIN","GRIT","BRA"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["RESEARCH","RESPSCHOL","RESOLVE","RESEARCH"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["COD","KNOWSPEC","NATSCH","WELLROUND"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":false},{"right":true,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["KNOWSPEC","INTENSFOC","CONF","RESOLVE"],"directions":[{"right":true,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":4,"cost":25,"talents":["STRGEN","MENTFOR","DEDI","TOUGH"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('SCIENTIST', 'Scientist', '[H4]Scientist — Making New Things[h4]
With a fraction of the resources and funding of the Empire, the Alliance is constantly forced to find creative solutions to problems. These problems include matters of supply, housing, transport, effective weaponry and defenses, and a host of others. The people they turn to for those creative solutions are those who are trained and driven to identify a need and seek out a technical solution to it—in other words, Scientists. 

[P]The additional career skills for Scientists are [B]Computers, Knowledge (Education), Knowledge (Lore),[b] and [B]Medicine[b]. If this is a first specialization, the PC gains a free rank in two of these skills. Unsurprisingly, Scientists are among the most educated people in the galaxy, with a wide range of advanced knowledge in areas such as medicine and celestial mechanics. 

[P]Most Scientists pursue their work in labs, rarely venturing out into the greater galaxy. Their lives are spent on theories and research, pondering the latest mysteries of the universe comfortably away from conflict and strife. Some Scientists, however, seek the satisfaction of bringing their theories and their ideas into the galaxy in order to help others. They design solutions, help create of the technology to implement those solutions, and actively test and use those solutions alongside others who are also trying to help make life better.

[P]Though Alliance officials prefer to keep Scientists in the rear echelons, as far away from danger and risk as possible, there are more than a few who insist on being the ones to test their new devices directly in the held. Further, some Scientists sign on with the Rebellion for the express purpose of taking the fight to the Empire; they''re just as prepared to fire a blaster at a stormtrooper as they are to devise a way to improve the power flow for that blaster to do more damage.', NULL, '["COMP","EDU","LORE","MED"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["KNOWSPEC","RESPSCHOL","RESEARCH","SPKBIN"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["RESEARCH","KNOWSPEC","HIDD","TINK"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":false},{"right":true,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["RESPSCHOL","MENTFOR","SPKBIN","INVENT"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":false},{"right":true,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["NATSCH","STRGEN","INVENT","TINK"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":false},{"right":true,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["INTENSFOC","CAREPLAN","DEDI","UTIL"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('SCOUND', 'Scoundrel', '[H4]Scoundrel — A Galaxy of Marks[h4]
Part con artist, part gunslinger, and part cantina brawler, the Scoundrel is quick-witted, quick on his feet, and quick to get himself into a great deal of trouble at the drop of a hat. He doesn''t care one whit for rules or laws, except where he can use them to work an angle that either nets him a lot of credits or brings down an enemy. If he''s really lucky—and he tends to have an unshakable faith in his luck—he''ll manage both. 

[P]His dynamic nature is spelled out in the Scoundrel''s additional career skills: [B]Charm, Cool, Deception,[b] and [B]Ranged (Light)[b]. If this is the character''s starting Specialization, he may choose two of these skills and gain one free rank in each, without spending starting experience. Combined with his talents, these skills make him formidable in a fight, useful in dealing with the underworld, and an individual simply not to be trusted. 

[P]Scoundrels fulfill many roles in the Outer Rim. Some are grifters, others are middle-men, and still others are simply thrill-seekers looking to see what they can get into next. Scoundrels tend to avoid taking charge of anything, but they are more than willing to ride the coattails of powerful people, often applying their unique skill set to help their employer in any number of ways. Scoundrels rarely put down roots for very long, and will always be looking for the next interesting thing to do (especially if it can make them some money). 

[P]In a Player Character group, the Scoundrel is a kind of all-purpose character. He''s got enough underworld savvy and social ability to act as a "face" for the group, and he''s no slouch in a fight. He may or may not be a pilot, but it''s almost certain he''s got many of the rogue-style abilities a group might need.', NULL, '["CHARM","COOL","DECEP","RANGLT"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["BLA","CONV","QUICKDR","RAPREA"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["CONV","BLA","CONV","QUICKST"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":false},{"right":false,"down":true,"left":false,"up":true}]},{"index":2,"cost":15,"talents":["HIDD","TOUGH","BLA","SIDESTEP"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":3,"cost":20,"talents":["TOUGH","RAPREA","HIDD","SIDESTEP"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":4,"cost":25,"talents":["DEDI","NATCHARM","SOFTSP","QUICKST"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('SCOUT', 'Scout', '[H4]Scout — Discovering New Planets[h4]
There''s finding a planet, and then there''s going down to the planet and seeing what''s what. The Scout is the professional for the task, trained to survey and survive, gathering all of the information he can while keeping his head attached to his body. While bravery in combat is one thing, there can be no denying the fearlessness of anyone willing to touch down on a completely unknown planet and trudge about with only scanners and his wits to discover its secrets. 
[P]A Scout knows his way around in any environment, and he''s both tough and knowledgeable enough to make the most of his situation. His additional Career skills make his job much easier: [B]Athletics, Medicine, Piloting (Planetary),[b] and [B]Survival[b]. If this is the character''s starting Specialization, he may choose two of these skills and gain one free rank in each, without spending starting experience. Most Scouts are skilled at: covering any ground (or lack thereof); how to find what to eat and where to sleep; and how to survey an area and gather all the needed data. Scouts are often excellent at driving or piloting atmospheric craft as well. 

[P]There are plenty of Scouts that work either for the Empire or for corporations that actively seek out and survey planets for possible exploitation. They normally work with survey teams with excellent support and resources. Independent Scouts—like the one a player is likely to play—operate with a great deal more autonomy. They will find smaller operations to work with, ones with looser rules and regulations that let them operate more as they choose. Living by his toughness and wits as he must, a Scout will be surprisingly effective in most situations. After all, adapting to the unknown is a trademark talent of any Scout.', NULL, '["ATHL","MED","PILOTPL","SURV"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["RAPREC","STALK","GRIT","SHORTCUT"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["FORAG","QUICKST","LETSRIDE","DISOR"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["RAPREC","NATHUN","FAMSUNS","SHORTCUT"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":3,"cost":20,"talents":["GRIT","HEIGHT","TOUGH","QUICKST"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":4,"cost":25,"talents":["UTIL","DEDI","STALK","DISOR"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":false,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('SEER', 'Seer', '[H4]Seer[h4]
Some individuals are able to remain constantly aware of the Force''s presence, even as they go about their daily lives. They recognize its influence in the subtlest of ways. For them, minor ripples in the Force reveal deep meanings and forewarn of critical events far in the future. However, this quantity of information—particularly in environments filled with other sentients—can become overwhelming. Because of this, many who follow the path of the Seer choose to live lives of relative isolation, far from crowded towns and cities. 

[P]Seers acquire [B]Discipline, Knowledge (Lore), Survival,[b] and [B]Vigilance[b] as additional career skills. If this is the character''s starting specialization, he may choose two of these skills and gain one free rank in each, without spending starting experience. Successful Seers must be able to maintain focus on daily life even as they also observe the Force. They must learn to recognize a broad range of subtle signs. They must also be prepared to dwell in a potentially hostile environment, apart from civilization, so that they can be spared from information overload. 

[P]Among Force-sensitive individuals, Seers are arguably the ones who feel the strongest sense of guidance from the Force. Dwelling within the Force at all times, they can recognize even minor ripples and follow them to their source to stop a small problem from turning into a major crisis. Similarly, they may recognize an event that occurs far away and advise those nearby to take action so they can be prepared well in advance of an upcoming crisis. Seers'' abilities often give them insights into the future, guiding them to places and people who most need their wisdom and advice. This sometimes enables Seers to be in just the right place at the right time to take action that proves to be pivotal. 

[P]The challenge for many Seers is to know the best time to move into a civilized area. As their sensitivity can become muddled, they may miss a sign of great import. Consequently, some prefer to remain apart from society for as long as possible, depending on allies to carry their missives. Seldom, however, are others capable of communicating a warning as effectively as the Seer who initially sensed the danger.', NULL, '["DISC","LORE","SURV","VIGIL"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["FORAG","UNCANREAC","GRIT","EXTRACK"],"directions":[{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["RAPREA","KEENEYED","UNCANREAC","TOUGH"],"directions":[{"right":true,"down":true,"left":false,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":false},{"right":false,"down":true,"left":false,"up":true}]},{"index":2,"cost":15,"talents":["SENSDANG","GRIT","FOREWARN","PREEMAVOID"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":3,"cost":20,"talents":["FORCERAT","SENSEADV","FORCEALLY","DODGE"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":false,"up":true}]},{"index":4,"cost":25,"talents":["RAPREA","TOUGH","NATMYSTIC","FORCERAT"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":false}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('SENTRY', 'Sentry', '[H4]Sentry — Hunting The Hunters[h4]
Despite the grand legends of the Jedi and their sweeping battles in half-forgotten wars, neighborhoods still need day-to-day protection. Padawans may have dreamt of striking down an evil general or forging alliances between powerful armies, but  when they became Sentries, they patrolled the streets streets, city blocks, and alleyways to help the overlooked, the common people. These foot soldiers gained none of the glory of their peers, and their thankless tasks have not been preserved in Jedi myths, but their work has benefited countless lives throughout the years.
[P]Sentries gain access to the additional career skills of [B]Coordination[b], [B]Lightsaber[b], [B]Stealth[b] and [B]Vigilance[b]. Characters who select this as their starting specialization may choose two of these skills and gain one free rank in each without spending starting experience.
[P]Although both have a lightsaber-focused specialization, Sentries and Shien Experts differ considerably. Whereas Shien Experts approach life and combat as tactical exercises, Sentries concentrate on the immediate and the personal. They reach their targets through speed or subterfuge, stay aware of potential threats, and strike sure and quick.
[P]Sentries are concerned with the present; a crime committed is a violation too far and stopped too late. While other Sentinels concern themselves on the bigger picture, Sentries pick up the pieces in the moment. They catch those who slip through the cracks and are forgotten, and stop those who break through safeguards to do irreparable damage. To Sentries, the details are the real picture, and allowing one person to suffer in order to promote justice is no justice at all.
[P]Perhaps the most personally engaged of the Sentinel specialists, Sentries defend individuals, whether a specific person they are charged with protecting or a random person walking down the street. During the days of the Jedi Order, Sentries were accused of being too attached to the singular, becoming too emotionally involved with people and losing sight of larger tasks. However, the sentries remained steadfast, channeling grief, anger, and love into pushing themselves to their limits to save their charges, and finding strength in their personal attachments.
[P]Despite their efforts—or perhaps because of them—Sentries don''t have a glowing reputation for purity. They revel in their reputation, utilizing fear and surprise against their opponents. Sentries can only maintain this reputation among their adversaries if their communities fear them as well. They must become the monster who the monsters fear.
[P]The Force guides Sentries to be in the right place at the right time to prevent violence. They move unseen, sometimes on rooftops to get a higher perspective, sometimes in the shadows to get an up-close point of view. Their senses expand as Sentries search for an opportunity, an opening, to get the jump on evil.
[P]Once engaged in combat, their priorities change. After slipping out of the shadows or dropping down from above, sentries operate visibly and encourage their enemies to target them. Sentries want to be the most intimidating and to be the most dangerous-looking so that their enemies will fear them and fight them rather than their charges. Their talents lie not in ending a fight quickly or attacking directly though. Sentries work best when surprising opponents, removing them one by one and giving the rest a chance to run away or surrender in this way. This lets Sentries use the negative emotions of fear and anger to disorient their opponents.', NULL, '["COORD","LTSABER","STEAL","VIGIL"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["TOUGH","REFLECT","GRIT","CONDITIONED"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["UNCANREAC","GRIT","REFLECT","UNCANREAC"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":2,"cost":15,"talents":["SLEIGHTMIND","SABERTHROWIMP","SABERTHROW","IMPOSFALL"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":3,"cost":20,"talents":["DODGE","FEARSHAD","CONSTVIGIL","SLEIGHTMIND"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":true,"down":true,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["FORCERAT","REFLECTIMP","DODGE","DEDI"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":false}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('SEPARATISTCOMMANDER', 'Separatist Commander', '[H4]Separatist Commander[h4]
Please see page 35 of the Collapse of the Republic Sourcebook for details.', NULL, '["COERC","LEAD","VIGIL","WARF"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["GRIT","WELLTRAV","COM","INTIM"],"directions":[{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["TOUGH","SPKBIN","CRUELCOM","SCATH"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["FLDCOMMIMP","FLDCOMM","SPKBIN","SCATHIMP"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":3,"cost":20,"talents":["DROIDCOMM","SPKBINSUP","SPKBINIMP","SCATHSUP"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":4,"cost":25,"talents":["LEADFRONT","DEDI","INTIM","LEADBACK"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('SHADOW', 'Shadow', '[H4]Shadow[h4]
In the ancient days of the Jedi Order, Sentinels worked tirelessly to police the galaxy''s criminal underbelly. However, a small subset of these enforcers focused their attentions on a far greater and more dangerous threat. They trained tirelessly to find and eliminate those who had fallen to the dark side of the Force and willingly embraced corruption These Sentinels were called Shadows, and they hunted the Sith. 

[P]For many years, the Sith were thought destroyed, and the Jedi Shadows gave up their calling or pursued other dark side Force users. They never realized that the Sith had not been eliminated, and were hiding right under their noses. 

[P]Now, with the Jedi Order destroyed and a Dark Lord of the Sith ruling the Galactic Empire, those who would follow the path of the Shadow find their roles reversed. No longer the secret investigators of an established order who searched the shadows of civilization, they are now the ones who must stay hidden. However, within these dark corners. Shadows still work tirelessly to bring justice to untouchable criminals and dark side Force users alike. 

[P]Shadows acquire [B]Knowledge (Underworld), Skulduggery, Stealth,[b] and [B]Streetwise[b] as additional career skills. If this is the character''s starting specialization, he may choose two of these skills and gain one free rank in each, without spending starting experience. These characters recognize that stealth and deception are integral to finding the targets they hunt. Criminal organizations are often mired in secrecy. and uncovering these secrets requires underhanded methods. While their techniques are frequently of questionable moral character. Shadows firmly believe their ultimate accomplishments more than justify the tools that they must use. 

[P]Of course, an initiate who has turned to the dark side can prove a powerful opponent for a Shadow. Working against such an adversary can require all of an adepts mundane and Force talents. A Shadow''s willingness to examine and utilize every tool and asset can play a major factor in overcoming such capable foes.', NULL, '["SKUL","STEAL","SW","UND"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["SLEIGHTMIND","STRSMART","COD","INDIS"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["WELLROUND","MENTFOR","GRIT","INDIS"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":false}]},{"index":2,"cost":15,"talents":["SHROUD","DODGE","SLEIGHTMIND","GRIT"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":false}]},{"index":3,"cost":20,"talents":["SLIPMIND","COD","NOWYOUSEE","DODGE"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["FORCERAT","ANAT","MASSHAD","DEDI"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":false}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('SHARPSHOOTER', 'Sharpshooter', '[H4]Sharpshooter — Take the Shot[h4]
With a love of firearms and a pride in personal accuracy, the Sharpshooter is the most desirable asset a team can ask for when a firelight erupts. He maintains his composure under a blanket of blaster bolts, takes careful aim, and eliminates threats with ruthless efficiency and lightning speed. Sharpshooters are, simply, the masters of personal-scale ranged combat. 

[P]Not surprisingly, Sharpshooters gain [B]Cool, Perception, Ranged (Heavy),[b] and [B]Ranged (Light)[b] as career skills, and two of these gain a free rank if this is the first specialization for the PC. The focus on personal-scale ranged weapons is a natural fit for Sharpshooters, and their ability to take in their surroundings completely and assess targets carefully under high-stress situations is essential to their survival. 

[P]Most Sharpshooters are thoroughly comfortable with any ranged weapon, though many will focus attention and effort on mastering a single (often highly-personalized) weapon. Some prefer a sniper role, taking up a hidden position and removing threats from the field as invisible dealers of death. Other Sharpshooters prefer a more direct approach, blaster energy blazing in waves of destruction as they cover their teammates against hordes of Imperial soldiers. 

[P]The focus on individual excellence within the Alliance elevates the Sharpshooter over his typical counterpart in the Empire. He is encouraged to train to higher degrees of proficiency, and he is encouraged to master techniques of survival, depending on his team to stay alive. The average stormtrooper is given a decent amount of training, but the lack of attention to personal excellence means he will never reach the pinnacle of accuracy and deadly effectiveness attained by a Sharpshooter in the Rebellion.', NULL, '["COOL","PERC","RANGHVY","RANGLT"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["EXTRACK","SNIPSHOT","BRA","GRIT"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["GRIT","TRUEAIM","DEADACC","LETHALBL"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":true}]},{"index":2,"cost":15,"talents":["BRA","LETHALBL","SNIPSHOT","TRUEAIM"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["EXTRACK","DEADACC","TOUGH","CRIPV"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":false},{"right":false,"down":true,"left":false,"up":true}]},{"index":4,"cost":25,"talents":["QUICKFIX","NATMAR","DEDI","TARGBL"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('SHIEN', 'Shien Expert', '[H4]Shien Expert[h4]
A lightsaber is a potent weapon. When wielded forcefully, it can even overpower an opponent who has a weapon capable of parrying it. Further, its ability to deflect blaster bolts can make it an effective ranged weapon as well. Those who consider themselves Shien Experts—masters of the Shien lightsaber form—embrace the seeming contradiction between those two uses. They know that true lightsaber masters must possess the cunning to use such weapons to their full potential. It takes clever precision to reflect a ranged attack back toward an adversary. but just as much shrewd brilliance to recognize the right time to overpower adversaries through raw force. 

[P]Shien Experts acquire [B]Athletics, Lightsaber, Resilience,[b] and [B]Skulduggery[b] as additional career skills. If this is the characters starting specialization, he may choose two of these skills and gain one free rank in each. without spending starting experience. In order to effectively follow this path, a character needs to be flexible and to recognize the best approaches for different types of physical conflicts. Resilience and Athletics are critical tools for engaging in and enduring a prolonged battle, while  Skulduggery enables the character to case out and prepare possible combat locations ahead of time to exploit the environment against an opponent. 

[P]Whenever possible, a Shien Expert prepares a battleground well in advance of a conflict. Often, these individuals take the time to study a range of different locations soon after they arrive in a city. Once combat begins, they can carefully exploit the environment and trigger any traps they may have prepared to unleash upon their opponents. 

[P]During combat, Shien Experts continue to constantly analyze the situation. While they take advantage of the terrain throughout a battle, they are also selective in choosing the best way to use their training as well as their lightsaber. This can change with each passing instant, in reaction to the armament, position, and stance of their enemies. For these individuals, an extended conflict is a sure route to victory as they react to every move their opponents make with a clever counter or powerful strike.', NULL, '["ATHL","LTSABER","RESIL","SKUL"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["DEFTRAIN","CONDITIONED","STRSMART","REFLECT"],"directions":[{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["TOUGH","PARRY","SHIENTECH","REFLECT"],"directions":[{"right":true,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":2,"cost":15,"talents":["PARRY","COUNTERST","GRIT","REFLECTIMP"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["DJEMSODEFL","DEFSTA","SABERTHROW","REFLECT"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["FALLAVAL","DEDI","DISRUPSTRIKE","REFLECTSUP"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('SHIICHO', 'Shii-Cho Knight', '[H4]Shii-Cho Knight[h4]
The ancient lightsaber fighting style of Shii-Cho is said to be the first lightsaber form taught to the Jedi and their predecessors. It focuses on the essentials of saber fighting and borrows heavily from other sword fighting techniques. Appropriately, the modern practitioners of this form focus on perfecting the core tenants of sword fighting, recognizing the strength of simplicity. Shii-Cho Knights eschew fancy maneuvers, preferring to focus on the fundamentals of block, parry. and strike. 

[P]Shii-Cho Knights acquire [B]Athletics, Coordination, Lightsaber,[b] and [B]Melee[b] as additional career skills. If this is the character''s starting specialization, he may choose two of these skills and gain one free rank in each, without spending starting experience. These skills provide them with a solid grounding in the core techniques of any physical conflict. They are familiar with the weapon they wield, but they are also very comfortable exploiting their natural athleticism and flexibility. Because of this, they can not only avoid an enemy''s attack, but also make certain that they are able to strike effectively when their target is at a disadvantage.

[P]Followers of this path are seldom concerned with personal appearances or the style that they exhibit in a conflict. Instead, they are focused on precision and on achieving their ultimate goal of victory. For them, a solid grounding in the basics is something they can rely on in any situation. When lives are on the line, they devote their attention to executing their maneuvers in a traditional way, using them to counter an opponent while simultaneously restricting his options.', NULL, '["ATHL","COORD","LTSABER","MELEE"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["PARRY","SECWIND","TOUGH","PARRY"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["SECWIND","CONDITIONED","MULTOPP","DURA"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":2,"cost":15,"talents":["QUICKDR","GRIT","PARRY","DEFTRAIN"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["NATBLADE","SARSWEEP","PARRYIMP","SUMDJEM"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["CENTBEING","DURA","DEDI","PARRY"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":false}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('SHIPCAPTAIN', 'Ship Captain', '[H4]Ship Captain — Independent Leaders[h4]

For Ship Captains, their vessel and their crew are everything.  Without them, captains are imprisoned in an incomplete existence.  With both, they''re free.  To protect this freedom, they demand and unmatched excellence from everyone aboard and provide the kind of leadership that gets these results.  If crew members aren''t highly skilled when joining a crew, Ship Captains will push them to become so through inspirational words and leading by example.  In exchange, crew members become a family and gain access to a wealth of camaraderie, connections, and experience.

[P]The additional skills a PC receives when taking the Ship Captain universal specialization are [B]Charm[b], [B]Leadership[b], [B]Negotiation[b], and [B]Piloting (Space)[b].  Given a good ship and a loyal crew, there is little this PC cannot accomplish.

[P]Ship Captains captain ships.  It''s what they do and who they are. For most beings, investment in a vessel is an unfathomable dream.  For Ship Captains, the lack of a vessel is an unbearable nightmare.  Once they''ve tasted the freedom only a starship or wide-ranging skimmer can provide, it becomes impossible to return to a predictable life and a seemingly meaningless existence.  Ship Captains control their own lives.

[P]In order to live their dreams, Ship Captains rely on the contributions of an effective and close-knit crew.  While they can find jobs and know the best places to sell goods, they aren''t necessarily the finest of pilots, engineers, or fighters.  When needed, they can always step in to fill a vacancy in order to escape pursuit, make a temporary fix, or shoot a blaster, but the best captains have specialists to fill these roles.  Such specialists tend to travel with a single captain for extended durations.  As captains and crews become comfortable with each other, all members learn about how best to perform their key responsibilities and where they can most effectively support everyone else.  For many, this professional arrangement acts as a surrogate family structure, with the captain as parent.

[P]As surrogate parents, Ship Captains are responsible for keeping everyone in line and for pushing them to be their best.  When there is a dispute between crew members, captains resolve it.  When a decision needs to be made, captains make it, and when shipmates doubt their own capabilities in a moment of crisis, captains instill them with confidence.  Ship Captains themselves must be stron to earn the respect of their crews, but they cannot operate through strength and threats alone.  If that strength can''t be tempered with compassion, every crew member will eventually find reasons to leave.

[P]This Compassion is one reason why some captains rebel against the injustices of the Empire.  For some of them, the Empire''s human-centric policies are intolerable, as they view species, beliefs, and affiliations as largely irrelevant as long as the shipmates meld with the rest of the crew and perform well.  Many others see the tightening grip of the Empire as a threat to their independent existence.  This threat can be even more pronounced in light of a captain and crew''s past transgressions against the Empire.

[P]Independent and Driven to stay that way, Ship Captains are dangerous threats to the Empire.  No matter what role, legal or otherwise, they may have had before they gained ownership and command of a vessel, they offer much to freedom fighters.  With the capability to lead strikes with effectively supported crews, they give hope to and signal the possibility of a more powerful organized resistance.  Wherever they are needed, Ship Captains can get there and inspire their crews to victory.', NULL, '["CHARM","LEAD","NEG","PILOTSP"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["WHEEL","PRIDEANDJOY","GRIT","KILL"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["KILL","PRIDEANDJOYIMP","FLDCOMM","SKILLJOCK"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["WHEEL","ENCWORD","SEENALOTOFTHINGS","FULLTH"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":false}]},{"index":3,"cost":20,"talents":["TRUSTHTECAPTAIN","INSPRHET","TRUSTHTECAPTAIN","PRIDEANDJOYSUP"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["MOSTIMPRESSIVE","INSPIRINGLEADERSHIP","GRIT","DEDI"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":false}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('SHIPWRIGHT', 'Shipwright', '[H4]Shipwright — Designing for War[h4]
[P]In peacetime, a Shipwright designs, oversees, and launches custom ships to grace the hyperspace lanes.  During the era of the Republic, Shipwrights crafted ships with elegant fins, spires, and curves that made people wonder, "Who built that?" Currently, the Empire favors ship designs that express power and inspire fear.  The Core World shipyards have followed suit, as the Empire remains the dominant culture in the galaxy.  Elegance is a bygone ideal, a symbol of Republic corruption or a lost fancy.  Even the Alliance often must eschew aesthetics for practicality and utility, something many Shipwrights in the Rebellion understand but mourn.

[P]Shipwrights receive [B]Gunnery, Knowledge (Education), Mechanics,[b] and [B]Piloting (Space)[b] as additional career skills. Characters who select this as their starting specialization may choose two of these skills and gain one free rank in each without spending starting experience.

[P]In the Alliance, Shipwrights primarily maintain and repair the various ships it fields. An important secondary task is the breaking down and retrofitting of commissioned starships. Since the majority of these vessels come from smuggled sources, civilian donations, or scrapyard rescues, Shipwrights have to determine If they should be utilized, scrapped, or junked.

[P]For ships to be added to the Fleet, they then oversee the installation of new or updated equipment and basic repairs. Then comes crew training, space trials and testing, readying the hull for hyperspace travel, and, for some lucky Shipwrights, naming and serving aboard them.

[P]Alliance shipyards tend to be hidden, remote, or highly mobile- often all three.  As always, materials, supplies, and labor are the main factors limiting construction, along with time; at any point, the Empire may suddenly discover the location of the shipyard,
prompting a rapid evacuation.

[P]Shipwrights can work on a space station or in its shipyard. Mobile Alliance shipyards can house weapon platforms or support mining and refining facilities. The more advanced shipyards resemble a fully staffed mining colony. In such a shipyard, Ship-wrights must incorporate industrial components in to their designs as well as handle worker accommodations and support. At this level, Shipwrights resemble civil engineers. Even something as basic as organic waste elimination can be important to the Alliance.  Only Shipwrights, for example, might know that the station''s trash disposal hold can hide an allied light freighter attempting to elude Imperial patrols!

[P]On the rare occasion when the Alliance requires a new ship design, Shipwrights usually must throw aesthetics out the transparisteel window to aim for utility, safety, and reliability.  Primarily, their designs must try to ensure that the ship and its crew can accomplish the mission and hopefully return in one piece. Good Shipwrights keep In mind that their creations should be easy to repair, offer a modicum of comfort, and be able to throw enough firepower at enemies to make crews happy to fly aboard them in to victory.', NULL, '["EDU","GUNN","MECH","PILOTSP"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["DOCKEXP","EYEDET","GRIT","CREATDES"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["SOLREP","FINETUN","EYEDET","DEPSHOT"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":false},{"right":true,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["KNOWSCH","DOCKEXP","SMARTHAND","CREATDES"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":false}]},{"index":3,"cost":20,"talents":["BOUGHT","PUSHSPEC","SOLREP","CREATDES"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":4,"cost":25,"talents":["DEDI","MASTART","STRGEN","EXHPORT"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('SKIPTRACER', 'Skip Tracer', '[H4]Skip Tracer[h4]
Not all debts need to be settled with blasters. Sometimes, a Bounty Hunter just needs to do some legwork, find a target, and get that individual to pay what is owed with a few well-chosen words. This is the specialty of Skip Tracers, who take on commissions to seek out people with unpaid debts from clients who wish to have items returned, cash given back, or recompense paid in some other way. Most Skip Tracers prefer to keep their guns holstered for the whole job, and try their utmost to avoid causing negotiations with their targets to break down explosively. Property destruction and medical bills cut into the commission, after all. Of course, as most Skip Tracers know all too well, things rarely go so smoothly. More often, the Skip Tracer ends up needing to apply pressure somewhere along the line, whether this takes the form of gaining leverage on the target or delivering a threat of violence—at the hands of the client or otherwise.
[P]In addition to the Bounty Hunter''s eight career skills, the Skip Tracer receives [B]Cool[b], [B]Knowledge (Underworld)[b], [B]Negotiation[b], and [B]Skulduggery[b] as bonus career skills. If this is the character''s starting specialization, the Skip Tracer may choose two of these skills and gain one free rank in each without spending starting experience.
[P]All Bounty Hunters have access to investigative abilities through access to Perception and Streetwise as career skills, but Skip Tracers are particularly strong at this aspect of the job. Several Skip Tracer talents are especially useful when backed by a high Cunning or Intelligence; Improved Street Smarts and Reconstruct the Scene let Skip Tracers find leads on even the scantest of evidence, and Bypass Security can help these investigators reach secured locations where their targets might be hiding. Through dedication and keen insight, Skip Tracers can locate and pursue a target across nearly any distance, which makes them ideal for finding people who wish to avoid notice.
[P]Skip Tracer also benefit from an investment in their Presence, as once they find their marks, they must convince them to part with what is owed. Several of the Skip Tracer''s talents, such as Good Cop and Nobody''s Fool make it difficult for targets to get the better of Skip Tracers in negotiations, and ensure that they recover the client''s property. If matters do become ugly, however, Skip Tracers are not defenseless: Hard-Boiled and Rapid Recovery allow Skip Tracers to doggedly pursue their quarry even after taking a beating, and Soft Spot lets them slip a finishing blow through at exactly the right moment, even against a tough opponent.', NULL, '["COOL","UND","NEG","SKUL"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["BYP","HARDBOILED","GOODCOP","RAPREC"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["TOUGH","EXTRACK","STRSMART","BOUGHT"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["HARDBOILED","RAPREC","STRSMARTIMP","STRSMART"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["BYP","NOBFOOL","GOODCOP","INFORM"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["RECSCENE","HARDBOILED","DEDI","SOFTSP"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":false}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('SLEEPERAGENT', 'Sleeper Agent', '[H4]Sleeper Agent — Ensuring Trust[h4]
Sleeper agents aquire [B]Charm, Cool, Discipline,[b] and [B]Knowledge (Education)[b] as additional career skills. If this is the character''s starting specialization, the player may choose two of these skills and gain one free rank in each without spending starting experience.
[P]
On a mission, the vast majority of Sleeper Agents time involves working a mundane job that may seem unrelated to their objective. In a few cases, the job is a military one, but those assignments require extensive security checks. More often, the Sleeper Agent works a civilian job that may have military connections. The agent may even serve as a member of a criminal organization. Whichever is the case, the Sleeper Agent''s duties offer peripheral access to a resource that is of great interest to the Rebellion. It is vitally important that agents remain constantly discreet about their true intentions.
[P]
All Sleeper Agents must be proficient in some profession that is not inherently related to uncovering military intelligence for the Rebellion. They might not need to be experts, but they must be able to convincingly assume an unremarkable civilian or military career. This act must be sustained for an extended period of time while the operatives wait to have their missions activated. Some missions focus entirely upon placing agents in critical places so that they can be activated to avert a currently unknown crisis. In these cases, the agents might pursue their cover career for years. Other missions have established timeframes or discrete objectives that the operative must pursue without raising suspicion.
[P]
Critically, Sleeper Agents must remain unflinchingly loyal to their cause. At the same time, they must be able to maintain the illusion that they are loyal to the enemy. In the case of extended assignments, they must build friendships that they know they will eventually betray. Few individuals are capable of maintaining this level of duplicity without developing some level of emotional attachment. Such attachment incurs terrible risk, as it could lead to hesitation at a critical juncture.', NULL, '["CHARM","COOL","DISC","EDU"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["COD","GRIT","CUNNINGPERSONA","WELLROUND"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["TOUGH","BYP","CONV","CREATKILL"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":false},{"right":true,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["ANALYZEDATA","COD","GRIT","CONV"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["GRIT","BYP","DURA","ASTEPAHEAD"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["DEDI","INSIDEPERSON","NATCHARM","INSIDEKNOWLEDGE"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":false}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('SLICER', 'Slicer', '[H4]Slicer — Making the Data Flow[h4]
For the Slicer, a computer or datapad is just a puzzle to solve with prizes for doing so. "Slicing" is the term used for the invasive efforts to steal or alter data in a system. With practically the entire galaxy wired to computerized systems, Slicers are extremely valuable people to know, and dangerous to cross. 

[P]Slicers naturally tend towards the underworld, yet they are also highly intelligent and knowledgeable. They add these skills to their career skills: [B]Computers, Knowledge (Education), Knowledge (Underworld),[b] and [B]Stealth[b]. If this is the character''s starting Specialization, he may choose two of these skills and gain one free rank in each, without spending starting experience. Their talents mainly focus on making computerized and electronic systems dance to their tune. 

[P]Slicers are among the most valued professionals in the Outer Rim, especially to the criminal world. A Slicer''s worth, however, is only as good as his reputation; success and loyalty will earn him top credits, while blowing key operations or double-crossing an employer will tend to make his prospects far less attractive.

[P]A Player Character group without a Slicer will have something of a handicap, especially where acquiring data or handling computerized problems is concerned. A Slicer might join a group for a chance to get away from a bad deal, or simply because he''s ready to see the next planet. Slicers tend to be a quirky bunch, so there might be any number of motivations at work.
 [H4]Slicer — Finding The Data[h4]
In a war, the vast majority of those who fight use weapons, explosives, and other tools of violence and destruction to confront the enemy. There are warriors, however, who do battle with codes, data packets, lightning-quick programming skills, and intuitive rewiring of communication networks to unmake the enemy''s plans and reduce his technology to just so much useless metal, plastic, and wires. These tech warriors are called Slicers.
[P]
Slicers Gain [B]Computers, Knowledge (Education), Knowledge (Underworld),[b] and [B]Stealth[b] as their added career skills. For PCs choosing this as their first specialization, two of these skills gain a free rank. Computers and electronic systems are the battlefield of the typical Slicer, but he is also skilled at the arts of breaking and entering and other covert actions. Most slicers also know their way around the streets and the criminal world, even when they are working legitimately for a military, government, or corporate organization.
[P]
There is a feeling of community where Slicers are concerned, even among those who are directly opposed to one another. They know they operate at a different level from everyone else, understanding technology in a way the vast majority of the galaxy''s population never will.
[P]
For the Slicer, the secrets of banking, security, communications, droids, automated systems, vehicles, ships and everything else involving a computer are his to manipulate or take. Any Slicer might be a minor god of a given system or networked machiines but for the interference and opposition of other Slicers. Recognizing that only those of their kind can hope to challenge them gives most Slicers a sense of superiority, or at least a smug security in their value to those without such skills.
[P]
Those Slicers working for the Rebellion are often more altrustic than their compatriots elsewhere in the galaxy, though more than a few are with the Alliance simply because they need protection from the Empire and its allied corporations. Most Slicers work directly with Alliance Intelligence, but there are those adventurous types who prefer to be part of a special teams sent into the heart of areas under Imperial influence. There, they can do battle directly with their counterparts, proving their superiority while serving the cause.', NULL, '["COMP","EDU","UND","STEAL"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["COD","GRIT","TECHAPT","BYP"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["DEFSLI","TECHAPT","GRIT","BYP"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":false},{"right":true,"down":true,"left":true,"up":false},{"right":false,"down":true,"left":true,"up":false}]},{"index":2,"cost":15,"talents":["NATPRO","BYP","DEFSLI","GRIT"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["DEFSLI","DEFSLIIMP","COD","RESOLVE"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["SKILLSLIC","MASSLIC","MENTFOR","DEDI"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('SORESU', 'Soresu Defender', '[H4]Soresu Defender[h4]
Guardians frequently and deliberately put themselves in harm''s way in order to aid others. However, just as the Protector is unmatched at keeping others safe. the Soresu Defender has mastered the art of self defense. With lightsaber in hand, Soresu Defenders can fend off hordes of enemies or stand firm against hails of blaster fire. surviving the worst the enemy can throw at them. 

[P]A Soresu Defender earns additional career skill access to [B]Discipline, Knowledge (Lore), Lightsaber,[b] and [B]Vigilance[b]. If this is the character''s starting specialization, he may choose two of these skills and gain one free rank in each, without spending starting experience. With this combination of skills, the character can maintain constant vigilance, recognize threats, and remain resolute in the face of danger. 

[P]Soresu Defenders depend on the Force to guide them through dangers. Their techniques rest almost entirely on knowing how best to use their weapons for defensive purposes. In many ways, this style approaches the level of precognition, as the Force guides its practitioners to use their weapons to deflect an incoming attack or to move out of the way of an assault. Individuals who are unaware of their Force potential can become accomplished martial artists using these techniques, but true Soresu Defenders must be sensitive to the Force.', NULL, '["DISC","LTSABER","LORE","VIGIL"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["PARRY","PARRY","TOUGH","DEFSTA"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["SORESUTECH","REFLECT","GRIT","GRIT"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":false,"down":true,"left":true,"up":false},{"right":false,"down":true,"left":false,"up":true}]},{"index":2,"cost":15,"talents":["CONF","PARRYIMP","DEFCIRCLE","PARRY"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":3,"cost":20,"talents":["PARRY","REFLECT","REFLECT","DEFSTA"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["PARRYSUP","DEDI","REFLECTIMP","STRATFORM"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":false}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('SQUADLEADER', 'Squadron Leader', '[H4]Squadron Leader — Ship-to-Ship[h4]
Though perhaps the most important engagements involve capital ships, the daily struggle for survival and victory happens at a much smaller scale. Snubfighters, small gunships, combat airspeeders, and hovertanks go hammer-and-tongs against the massive Imperial war machine, and it''s only the tactical genius and daring of those who lead these units keeping them alive. The best Squadron Leaders even manage to pull out more than their fair share of victories. 

[P]Squadron Leaders have access to [B]Gunnery, Mechanics, Piloting (Planetary),[b] and [B]Piloting (Space)[b] as their additional career skills. As the first specialization choices, two of these skills can begin with a free rank. Squadron Leaders tend to know their machines very well, and of course they need to be able to operate the same types of vehicles they are commanding. 

[P]Squadron Leaders rarely lead from the rear. More often than not, theirs are the first ships or vehicles to engage the enemy, and they''re the last ones out of a combat zone Of they get out at all). Leading by example is a way of life for a Squadron Leader, and he won''t ask anyone to do what he''s not ready to do himself. He rides his team to keep their machines in top shape, and he trains them constantly. He wants both crew and machines back in the hangar when the mission is over, and he does whatever it takes to make it happen. 

[P]Alliance High Command knows every single battle is important, and most of them are won at the front line, by mechanized detachments and starfighter squadrons under the command of Squadron Leaders. The upper echelons are constantly on the lookout for anyone with the right qualities to inspire and lead pilots and vehicle crews into the worst kinds of hell and back again.', NULL, '["GUNN","MECH","PILOTPL","PILOTSP"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["GRIT","QUICKST","LETSRIDE","DEFDRI"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["FLDCOMM","CONF","QUICKST","SITAWARE"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":false},{"right":true,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["COM","GRIT","FULLSTOP","DEFDRI"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":false}]},{"index":3,"cost":20,"talents":["FLDCOMMIMP","COM","FORMONME","TRICK"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["MASLEAD","CONF","DEDI","BRI"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('STARACE', 'Starfighter Ace', '[H4]Starfighter Ace[h4]
Starfighter pilots enthusiastically engage in one of the most dangerous forms of battle imaginable. Their shields and armor—for starfighters that have either—offer virtually no resistance to the weapons of the capital ships they oppose. Instead, they must trust in the Force to protect them as they launch their daring assaults. Those who embrace the risks of space combat may pursue the Starfighter Ace specialization. 

[P]Starfighter Aces acquire [B]Astrogation, Gunnery, Mechanics,[b] and [B]Piloting (Space)[b] as additional career skills. If this is the character''s starting specialization, he may choose two of these skills and gain one free rank in each, without spending starting experience. These provide the essentials needed to successfully pilot a starfighter in combat. Force adepts who acquire these skills most often control single-passenger craft, in which they must assume responsibility for weapons at the same time that they handle navigation. 

[P]While this style of combat is dependent on a vehicle, it remains physically exhausting. Even with a full range of technological enhancements, effective pilots must be capable of enduring rapid and extreme shifts in velocity and direction. They must also remain ready to strike a deadly blow against an opponent at just the right instant, even while struggling to endure extreme physiological conditions.', NULL, '["ASTRO","GUNN","MECH","PILOTSP"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["GRIT","SKILLJOCK","RAPREA","SOLREP"],"directions":[{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["INTUITEVA","CONF","SOLREP","GALMAP"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["FULLTH","RAPREA","EXHPORT","GRIT"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":3,"cost":20,"talents":["INTUITSTRIKE","TOUCH","GRIT","SKILLJOCK"],"directions":[{"right":true,"down":true,"left":false,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["FORCERAT","TRICK","DEDI","INTUITEVA"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('STEELHANDADEPT', 'Steel Hand Adept', '[H4]Steel Hand Adept — Unarmed and Dangerous[h4]
The Jedi were known for, and even symbolized by, their distinctive use of lightsabers. For those who also know of the Sith and their own use of lightsabers, it would seem that these weapons are a universal feature of Force users. This was never truly the case, especially not in this age of the Empire, when most Force sensitives must do without formal training in any Force tradition. Through necessity or choice. Force users do battle with a variety of weapons, from vibro-axes to repeating blasters. And some fight with no weapons at all. 

[P] Steel Hand Adepts gain [B]Brawl, Coordination, Discipline[b], and [B]Vigilance[b] as additional career skills.  If this is the character''s starting specialization, the player chooses two of these skills and gains one free rank in each, without spending starting experience. These skills allow Adepts to fight with their mind and body in perfect harmony, and with mastery over both.
[P]Countless martial arts disciplines have focused on unarmed combat through the millennia, from Teras Kasi to Zavat.  Even the most renowned masters of hand-la-hand combat face certain limitations when compared to wielders of the variety of advanced weapons in use throughout the galaxy.  No fist or claw can breach heavy armor, or overcome the range advantage of a blaster-none, that is, except those of beings who wield the Force like a weapon.

[P] As [B]FORCE AND DESTINY[b] characters. Steel Hand Adepts might represent Force users with training in a variety of martial arts forms. Some might specialize in a particular form, while others might blend techniques from many practices. Alternatively, an Adept could be self taught, augmenting an improvisational combat style honed through years of cantina brawls with an instinctive use of the Force. Regardless of their background, Steel Hand Adepts draw on the Force to accomplish seemingly impossible maneuvers, from punching through heavy combat armor to striking enemies beyond arms'' reach.

[P]The ways of Steel Hand Adepts have little basis in the teachings of the Jedi Order. Although the Jedi trained in some hand-to-hand techniques, these were generally used as a recourse should a Knight be disarmed or ambushed without a lightsaber at hand. However, many other Force disciplines have come and gone throughout the galaxy''s history, and some of these have focused more prominently on unarmed combat. Conversely, many martial arts traditions have a strong mystical component, tapping into the Force in varying capacities. Although martial arts schools of this kind generally accept members who are not particularly Force sensitive, those who are so gifted tend to excel, becoming masters and legends.

[P]The capabilities of Steel Hand Adepts can be astounding for onlookers and terrifying for foes. Not only can adepts exhibit the same range of abilities other Force users draw upon to augment their lightsaber strikes, but they can fight just as effectively without a weapon of any kind. A practiced Adept can even be a match for an accomplished lightsaber duelist. Against more ordinary combatants, they spin and leap with frightening grace, laying foes low with rapid strikes.  

[P]A Steel Hand Adept can easily disarm all but the most skilled opponents through a variety of techniques. Some adepts can even shatter weapons with their bare hands. An unarmed opponent of an Adept. far from being on equal rooting, is almost certainly at an insurmountable disadvantage. Enemies with the seeming advantage of range are not safe, either. Blaster-wielding foes are often surprised when a Force user affects objects and even sentients at a distance, but no Force ability is as shocking as Adepts'' ability to lash out with punishing strikes, laying into foes at range with the full strength and impact of their fists and feet.', NULL, '["BRAWL","COORD","DISC","VIGIL"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["GRIT","IRONBODY","IRONBODY","TOUGH"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["MARTIALGRACE","ACKLAYSCYTHINGSTRIKE","UNARMPARRY","PRECSTR"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":true}]},{"index":2,"cost":15,"talents":["DODGE","SWIFT","PARRY","PRECSTRIMP"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["IMPDODGE","TOUGH","GRIT","SAPITHSUNDERING"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true}]},{"index":4,"cost":25,"talents":["FORCERAT","FARSTRIKE","DEDI","DODGE"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":false}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('STRATEGIST', 'Strategist', '[H4]Strategist — In for The Long Haul[h4]
Strategists are responsible for forming the core directives used in the war against the Empire. Rather than focusing on individual battles, they analyze the big picture—both what has happened and what is bound to happen should their plans bear fruit. They also monitor the effectiveness of logistics to ensure that military units aren’t too thinly spread or sparsely supplied to be effective. Anything that might change the tide of battle concerns them, and they must possess sharp minds and keen wits to keep all the variables under control.
[P]
Strategists receive [B]Computers, Cool, Vigilance,[b] and [B]Knowledge (Warfare)[b] as additional career skills. If this is the character’s starting specialization, the player may choose two of these skills and gain one free rank in each without spending experience. Though they rarely possess direct command of armies or units, Strategists are expected to arrange the high- level details of the operations and battles the Rebel military must participate in. A Strategist must also be incredibly detail-oriented, as forgetting a minor item when planning a planetary strike could lead to the deaths of thousands of Alliance troops.
[P]
Strategists must be able to keep their cool. Viewing the Galactic Civil War from such a lofty vantage point can cause even the most tranquil individuals to break under pressure. In fact, the conflict at hand is so vast and complex that it can be difficult to digest it all, even in multiple sittings. Keeping a cool head also allows the Strategist an opportunity to examine an enemy’s movements in order to discern whether or not it is attempting a feint or a full-fledged assault. Imperial commanders are cunning tacticians, and their ruses can be disastrous if they aren’t seen for what they are before it’s too late.
[P]
Obviously, successful Strategists must know the ins and outs of warfare. Being aware of their enemies’ capabilities, as well as those of their own troops, is vital to planning a successful campaign. In addition, possessing intimate knowledge of wars both past and present allows Strategists to learn from the lessons of their predecessors, or to call up a little-used tactic to catch the Empire off guard.
[P]
Though a Strategist may seem like an odd choice for the typical Alliance cell, the knowledge and keen insight such a character brings to a party are well worth having. With a little combat training, a Strategist can act as a secondary combatant while watching the battlefield for signs of opportunity or disaster. Given their potential training in both Cool and Vigilance, it’s unlikely that a Strategist will be caught unawares when things turn ugly.', NULL, '["COMP","COOL","VIGIL","WARF"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["RESEARCH","GRIT","READANY","GRIT"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["GRIT","CLEVCOMM","COM","WELLREAD"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["KNOWSPEC","RESEARCH","READANY","MASSTRAT"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":3,"cost":20,"talents":["RESEARCHIMP","KNOWSPEC","COORDASS","COM"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["THORASS","CAREPLAN","READANYIMP","DEDI"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('SURV', 'Survivalist', '[H4]Survivalist — Master of the Wild[h4]
[P]Beyond civilization, in the farthest reaches of the galaxy, there are places where few (if any) sentients have ever trodden the ground. Places like these are ideal hiding places for those fleeing the law or retribution for their actions. Places like these are where Bounty Hunters who specialize as Survivalists thrive.

[P]Hearkening back to the ancient practices of true wilderness hunters, the Survivalist gains [B]Knowledge (Xenology), Perception, Resilience,[b] and [B]Survival[b] as additional Career skills. If this is the character''s starting Specialization, he may choose two of these skills and gain one free rank in each, without spending starting experience. With his talent array, he can keep himself and his companions alive, and he knows where and what to look for when searching for just about anything or anyone. He''s also gifted at hunting any kind of target. 

[P]Not everything that happens in the galaxy occurs in cities or out in space. In fact, most of the habitable places of the galaxy are rural or wilderness in nature. A specialization in Survivalist ensures a character has the necessary knowledge and training to make his way in such environments, and help the far more urban-minded folks he''s likely traveling with. 

[P]Despite their capacity to live off the land, Survivalists enjoy credits and the things that can be purchased with them just like anyone else. They will often look to hire themselves out to customers who need their expertise in seeking out (or hunting) something beyond the duracrete and tapcafs.', NULL, '["XEN","PERC","RESIL","SURV"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["FORAG","STALK","OUTDOOR","EXTRACK"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["OUTDOOR","SWIFT","HUNT","SOFTSP"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":2,"cost":15,"talents":["TOUGH","EXTRACK","STALK","NATOUT"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["TOUGH","HUNT","EXTRACK","BLO"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":4,"cost":25,"talents":["ENDUR","DEDI","GRIT","HERO"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":false,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('TACTICIAN', 'Tactician', '[H4]Tactician — On the Ground[h4]
All of the victories in space, in the air, and even on the ground mean nothing if the winning force cannot hold the territory taken. At the end of the day, a few troops with blasters and bombs can disable any installation, disrupt an entire defensive grid, and create the conditions of victory. They do so under the courageous and savvy leadership of a Tactician. 

[P]The additional career skills for a Tactician are [B]Brawl, Discipline, Leadership,[b] and [B]Ranged (Heavy)[b]. Two of these four skills begin with a free rank if this is the first specialization chosen for the PC. Tacticians often insist on being able to fight even without weapons if called upon to do so, and many prefer heavier weapons for combat. Additionally, they are the ones who must be true leaders, even in the face of the worst possible odds. 

[P]When all is going well, a Tactician tends to be the person the rest of a team grouses about over too much work, monotonous duties, and repeated training. However, when the blaster fire is flying and people are screaming and dying all around, the team looks to the Tactician to lead them, whether it''s out of danger or into glory. A Tactician assesses the situation at all times, looking for the best way to accomplish the mission and keep his people alive. His team depends on him for these skills. 

[P]By Alliance philosophy, Tacticians are made, not born. Battlefield promotions happen constantly, for Alliance ground forces suffer the greatest losses constantly. Those who show any capacity for leadership are brought up in rank rapidly when the need calls. Others are cultivated more fully for the most important and dangerous missions. The Alliance is blessed with a high proportion of talented individuals, what it needs are special individuals who can organize and lead them.', NULL, '["BRAWL","DISC","LEAD","RANGHVY"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["OUTDOOR","COMMPRES","TOUGH","SIDESTEP"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["OUTDOOR","CONF","QUICKDR","SWIFT"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["NATOUT","TOUGH","BOD","BOD"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["CONF","COMMPRES","FLDCOMM","SIDESTEP"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":false},{"right":false,"down":true,"left":false,"up":true}]},{"index":4,"cost":25,"talents":["COORDASS","NATLEAD","FLDCOMMIMP","DEDI"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('TEACHER', 'Teacher', '[H4]Teacher — The Greatest Gift[h4]

There comes a time in the life of most who feel the draw of the Force when they decide that they can best serve the galaxy by passing along the accumulated knowledge and wisdom of their lifetime. Whether they have been classically trained in one of the ancient disciplines, have pursued a more mundane education in an academy or conservatory, or are self-taught through innate discipline and drive, Teachers now seek to assist others in gaining the training and enlightenment they have accrued. Through the efforts of Teachers, their allies can attain greater abilities and assets than they would have alone.
[P]
A Teacher''s additional career skills are [B]Knowledge (Education)[b], [B]Knowledge (Lore)[b]. [B]Leadership[b], and [B]Perception[b]. Characters who select this as their starting specialization may choose two of these skills and gain one free rank in each, without spending starting experience. Given their selection of skill, Teachers will be far better at enhancing the potential of their group than any other Consular. In addition to providing valuable assistance to their companions, Teachers are more than capable of holding their own in almost any situation. They can pursue a wide range of skills and abilities with an eye toward passing this knowledge along to others. Teachers feel the Force throughout their life and will feel the draw of many paths through the years. Through this process, they will accumulate a vast store of knowledge and experience. Many reach a point where the drive to push on is overcome by the desire to pass on their knowledge to others, to better serve the galaxy.
[P]
Some Teachers work closely with established schools and academies, perhaps echoing the techniques and traditions of the fallen Jedi Temple. Many of these work in the Outer Rim, far from the prying eyes of the Galactic Empire. Others, feeling no need for more advanced aids and accoutrements, content themselves with little more than a clearing or a log to sit their pupils upon, from which they might contemplate the mysteries of the galaxy together. Teachers are often keenly aware of their place in the scheme of life and seek to pass the peace and assurance of this knowledge on to their students that their students may better serve their own purposes. No matter the particular goal of the moment, a Teacher will have advice and instruction to assist in its achievement.
[P]
In the course of a lifetime, any setting can turn into a classroom with a willing Teacher on one side and an apt pupil in the other. Whether in a dry, dusty hut in the middle of a desert, the sodden expanse of a humid swamp, or the cramped confines of a tramp freighter, Teachers will do what is needed to see that their students are prepared for the tasks that lie before them.
[P]
Often the path of the Teacher is not one that is selected, but one that is thrust upon one by circumstance. In the pursuit of expansive goals, it may be hard to realize that it is best left to others to achieve them, the responsibility of the Teacher being to assist them and shepherd them along. Having a Teacher in a group can be a great boon no matter the goal, given the versatility of Teachers'' abilities and their capacity to assist other members of their group in any efforts they may make. When the need is greatest and a new generation must rise to confront the darkness, there can be no greater ally in the Force than knowledge passed down from the vantage of experience and understanding.', NULL, '["EDU","LEAD","LORE","PERC"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["RESEARCH","RESPSCHOL","SENSDANG","WELLROUND"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["WELLTRAV","GRIT","NOBFOOL","ENCWORD"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["TOUGH","SKILLEDTEACH","MASINST","NOWMAST"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":3,"cost":20,"talents":["WISEWARIMP","WISEWAR","GRIT","ONCELEARN"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":4,"cost":25,"talents":["DEDI","GRIT","SKILLEDTEACH","FORCERAT"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('THIEF', 'Thief', '[H4]Thief — A Galaxy of Treasures[h4]
Where the Scoundrel is a bit flashier, and the Pilot focuses on mastering his ship, the Thief really is a covert operative. His ideal circumstance is to get into places blocked to others, grab things he''s not supposed to have, and get out without anyone ever knowing he was there. If he can sell what he grabbed for a tidy sum, that makes for a perfect day. 

[P]Thieves gain the additional career skills [B]Computers, Skulduggery, Stealth,[b] and [B]Vigilance[b]. If this is the character''s starting Specialization, he may choose two of these skills and gain one free rank in each, without spending starting experience. Combined with his talents, a Thief is particularly adept at hiding, spotting the hidden, getting past locks and security, and getting the jump on opponents in combat. He also knows his way around the underworld and where to get what''s needed. 

[P]Generally, Thieves tend to either operate with a group that shares in their larcenous goals, or they work alone. The galaxy is full of treasures, many of which are guarded by locks and goons. A Thief will gladly handle the locks, though he''ll probably appreciate having some backup to handle the goons if things go badly. Then again, if he''s truly good at what he does, that shouldn''t happen. Some Thieves gain a strong enough reputation that they are offered contract opportunities by powerful people or groups. seeking to accomplish something against an opponent that is far beyond the realms of legal action. Of course, Thieves must always be on the lookout for a double-cross. 

[P]As a part of a Player Character team, a Thief may not even identify himself by his specialization, preferring to display skills and abilities that are more generically appropriate to his career as a Smuggler. Frankly, most Smugglers have at least some skill in the areas that he is masterful with, so he might never have to reveal much more than that. Still, having a master Thief on a team may mean getting into—and out of—some seriously difficult places in the future.', NULL, '["COMP","SKUL","STEAL","VIGIL"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["STRSMART","BLA","INDIS","BYP"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["BLA","DODGE","GRIT","HIDD"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":true,"down":true,"left":true,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["STALK","GRIT","RAPREA","SHORTCUT"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["BYP","NATROG","STRSMART","JUMP"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["MASSHAD","DODGE","INDIS","DEDI"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":false,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('TRADER', 'Trader', '[H4]Trader — Discovering New Markets[h4]
Those seeking to take what they discover as they explore the Outer Rim and beyond (and turn a serious profit from it) are Traders. For a Trader, a new planet represents nigh-infinite potential for resource exploitation, while a new culture or hidden community is a customer base just begging for his particular talents. 

[P]Traders gain access to the additional Career skills of [B]Deception, Knowledge (Core Worlds), Knowledge (Underworld),[b] and [B]Negotiation[b]. If this is the character''s starting Specialization, he may choose two of these skills and gain one free rank in each, without spending starting experience. Most Traders know how to build connections between the center of civilization and the far reaches, and they are often educated folks who bring knowledge and proficiency in economics, sociology, and politics with them.

[P]Traders are exceptionally adept at commerce, naturally; they know how to find what is needed, and can usually bypass the kinds of restrictions that stymie others. At the same time, Traders can get the most out of a transaction, as well as talk themselves into or out of almost anything. Traders are strategic thinkers, planning ahead for contingencies. They are also strong-willed, making them excellent companions in a crisis. 

[P]A Trader played in a campaign will likely serve as the group''s public face, though not necessarily as the leader. He will be one of the best first choices for interacting with public officials, money men, and anyone with whom the group seeks to do business. When it comes to finding and buying something that the team needs, or fencing something that they wish to get rid of for a profit, he is invaluable.', NULL, '["DECEP","CORE","UND","NEG"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["KNOWSOM","CONV","WHEEL","SMOOTHTALK"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["WHEEL","GRIT","SPARECL","TOUGH"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":false}]},{"index":2,"cost":15,"talents":["KNOWSOM","NOBFOOL","SMOOTHTALK","NOBFOOL"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":false}]},{"index":3,"cost":20,"talents":["WHEEL","STNERV","BLA","BLA"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":true,"left":true,"up":false}]},{"index":4,"cost":25,"talents":["KNOWSOM","NATNEG","DEDI","MASMERC"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('TRAILBLAZER', 'Trailblazer', '[H4]Trailblazer — Unseen Paths[h4]
Catching the enemy off-guard is one of the oldest and most diverse tactics in the galaxy, and Trailblazers seek to turn it to their advantage at every turn. To this end, a Trailblazer receives [B]Knowledge (Outer Rim), Perception, Stealth,[b] and [B]Survival[b] as additional career skills. If this is a character''s starting specialization, he may choose two of these skills and gain one free rank in each, without spending starting experience. Survival makes the Trailblazer better at tracking foes and setting clever traps, while Stealth helps in avoiding enemies who might uncover the Trailblazer''s presence.
[P]
Trailblazers tend to favor patience and indirect solutions, pitting the foe against the wilderness of using the features of the terrain to eliminate enemy advantages. Heavy walkers cannot function in the confines of a forest, for instance, nor can massive infantry surges push through urban environments without exposing themselves to risk. Trainblazers work to make the best of cover and prefer to fight on their own turf, where they can turn ever piece of their knowledge to their advantage. The Cunning Snare talent, in particular, shines here, giving the Trailblazer the ability to set up a devastating trap for unsuspecting foes. While this talent takes some setup to use, the payout can be considerable, levelling a fight with a numerically superior or better-equipped foe. The Trailblazer can even use this talent without advanced supplies, using cleverness and woodcraft to overcome dire situations if the PCs are ever stranded without access to optimal gear- and on the shifting battlefields of the Galatic Civil War, Soldiers of the Rebellion can find themselves cut off and without support in an instant.
[P]
Trailblazers often act as guides to other members of their squads, helping them to avoid the dangers of the wild and the battlfield alike as the group moves to the most advantageous position possible. A skilled Trailblazer can no only allow a group of PCs to win difficult battles through subterfuge and trickery, but also to avoid unnecessary battles entirely. The Rebel Alliance frequently needs to achieve objectives without the Empire noticing, and so the best battle is often the one that was never fought. A Trailblazer can be substantial boon to any [B]Age of Rebellion[b] group in other contexts, too, whether the PCs are moving through the wilds or the streets of a city.', NULL, '["OUT","PERC","STEAL","SURV"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["STALK","TOUGH","OUTDOOR","EXTRACK"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["DISOR","PRIMEPOS","CUNNSNARE","OUTDOOR"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["GRIT","DODGE","BLINDSPOT","TOUGH"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":3,"cost":20,"talents":["DODGE","PREYWEAK","EXTRACK","ONENAT"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["DEDI","AMBUSH","DISOR","PREYWEAK"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":false}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('VANGUARD', 'Vanguard', '[H4]Vanguard — Unrelenting Onslaught[h4]
Vanguards are first to the fight, Soldiers skilled in taking point and taking charge. While they generally do
not command in the traditional sense, their preferred
mode of combat is to hit hard and fast, and thus allies
tend to fall in behind them, if only so that they are
not left behind. This means that Vanguards shoulder a
great deal of the risk in battle, but most would rather
take a blaster bolt than let a squad mate be shot. As a
result of taking so many hits over the course of their
military careers, the Vanguards who survive tend to be
extremely tough.
[P]Vanguards have [B]Athletics[b], [B]Cool[b], [B]Vigilance[b], and
[B]Resilience[b] as additional career skills. If this is a character''s starting specialization, he may choose two of
these skills and gain one free rank in each, without spending starting experience. Having both Cool and
Vigilance means that Vanguards are extremely unlikely
to flinch or hesitate when the shots start flying, regardless of whether
they are launching an ambush or reacting
to an unexpected move. Athletics reflects the
physical acumen of Vanguards, while Resilience
stems from the long history of hits such characters
have likely taken.
[P]On battlefields often dominated by massive walkers, sudden starfighter strikes, and orbital bombardments, standing still in the open can be a death sentence, and Vanguards know it. Rather than hunkering down and hoping to avoid the worst, Vanguards take
the battle directly to the enemy, seizing the in initiative to end the battle before their foes even realize
that it has begun. They tend to favor rapid strikes,
armored assaults, and shipboard actions that leave
the enemy reeling and unable to bring its arm or to
bear. So long as they keep moving, their logic goes,
the enemy cannot hope to pin them down. Barriers
to their entry, from blast doors to bunkers, are something to be smashed so that they can move on to the
next target. The Moving Target talent is particularly
useful when keeping mobile to stay alive, and makes
a Vanguard with the drop on the enemy extremely
difficult to bring down.
[P]Off the field of battle, Vanguards are frequently
quick to action as well Hesitation on the battlefield
is often fatal, and many Vanguards apply this mentality to their other activities, trying to keep opponents.', NULL, '["ATHL","COOL","RESIL","VIGIL"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["BOD","CONDITIONED","TOUGH","RAPREA"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["TOUGH","MOVTARGET","POINTBL","SUPPRFIRE"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":true,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["CONDITIONED","BOD","TOUGH","RAPREA"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["BODIMP","TOUGH","SUPPRFIRE","MOVTARGET"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":true,"down":true,"left":true,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["DEDI","BODSUP","DYNFIRE","SEIZEINIT"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":false},{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('WARDEN', 'Warden', '[H4]Warden — The Daunting Defender[h4]
Whether they wield the power of the Force consciously or not, Wardens know that they have been gifted with power. But more importantly, they know that they must wield this might to perform a necessary duty, subduing those who would abuse that same power to harm the Warden''s friends and allies. While Guardians of all stripes might be driven by a desire to create a fairer world, the concept of justice is especially important to Wardens. The job of punishing the wicked is frequently a thankless one, especially in the era of the Empire, when the ruling regime is so deeply corrupt. Many Wardens see this burden as inevitable; after all, it is their role to make sure evil is stripped of the means to threaten their chosen allies, not to be loved for these efforts.

[P]The Warden is unique among Guardian specializations in being focused specifically on weakening enemies rather than just bolstering allies. In some ways, this specialization is the mirror image of the Aggressor. Both wield fear as a weapon, but the Warden uses dread to weaken foes'' strikes rather than make them more vulnerable to attacks, and relies on counterattacking instead of striking first. What a Warden lacks in raw toughness as compared to a Protector or Armorer, this unique Guardian makes up for with the ability to control foes options by restricting their movement, inflicting strain upon them and intimidating them into submission.

[P]To assist in their task of identifying and subduing threats to their allies, Wardens have [B]Brawl, Coercion, Discipline and Knowledge (Underworld)[b] as additional career skills. If this is the characters stating specialization, he may choose two of these skills and gain one free rank in each without spending starting experience.

[P]Wardens are suited to taking major roles on and off the battlefield, thanks to their specialization''s focus on Coercion. While using intimidation as a primary social tool can have consequences for the character''s morality, many unnecessary fights can be avoided if potential foes are too afraid to draw weapons against a Warden. In battle, Wardens shine in close quarters, where foes must approach to attack and thus suffer the consequences of engaging such frightening enemies. Wardens do what is needed to give their allies the best chance of survival in a harsh galaxy, and if this includes some unsavory tasks, so be it.', NULL, '["BRAWL","COERC","DISC","UND"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["GRIT","TOUGH","INTIM","GRIT"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["PRECSTR","CONF","SCATH","BADCOP"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["SENSEADV","CONF","FEARSOME","NOESC"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":true,"down":false,"left":true,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":3,"cost":20,"talents":["TOUGH","OVERBAL","BALEGAZE","BADCOP"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":false},{"right":false,"down":true,"left":false,"up":true}]},{"index":4,"cost":25,"talents":["GRAPPLE","DEDI","FORCERAT","FEARSOME"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":false},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_specializations (key, name, description, career_key, career_skill_keys, talent_tree, dataset_source, is_retired) VALUES ('WARLEADER', 'Warleader', '[H4]Warleader — The Shrewd Leader[h4]
Not all Guardians solve their problems through feats of prowess with the lightsaber alone. The mind can be a deadlier weapon still, and a little foresight can do as much to win a battle as the greatest feat of heroism. The Warleader possesses a number of tricks and abilities that help to carry the day in battle, and more importantly, to keep friends and allies alive to fight another day.
[P]Warleaders are calculating fighters who rely more on mental acuity and guile tan on raw combat strength. While Warleaders are capable combatants in their own right, thanks to their ranged combat skills, their greatest edge comes when they have comrades in arms to guide in battle. Unlike Peacekeepers, Warleaders do not focus on inspiring others; while individual Warleaders might indeed be charismatic, their friends trust them with their lives not because of rousing speeches, but because of their reliability in the field.
[P]Warleaders might not protect their allies by deftly deflecting blaster shots with  lightsaber or heroically taking blows meant for them, but their guidance can keep comrades safe just the same. Warleaders acquire [B]Leadership, Perception, Ranged (Light) and Survival[b] as additional career skills, all of which assist them in negotiation on the battlefield and guiding their allies across it. If this is the character''s starting specialization, he may chose two of these skills and gain one free rank in each without spending starting experience.
[P]Whether through formal military training, practical combat experience or simply having keen minds, PC''s who take on this specialization are well-equipped to handle matters of strategy and tactics. Warleaders often have an intuitive grasp of the field of combat thanks to their connection to the Force, and combine this with shrewd tactics to concoct and execute forward-thinking plans that seem almost prescient to their foes. Cover is an especially valuable resource for Warleaders. They can use it not only to grant their comrades additional defensive benefits, but also to gain the edge over enemies by guiding allies to strike them from unexpected angles.
[P]Trust is the foundation of any Warleader''s command. More often than not in [B]Force and Destiny[b], a party of Player Characters consists of a group of equals pursuing a common goal rather than a formally structured organization. Even if one PC is nominally in charge, that person might or might not be the Warleader. When battle breaks out, however, the Warleader keeps friends out of the line of fire, exposes weaknesses in enemy plans, and comes up with cunning strategies  that catch foes off guard.  
[P]Outside of battle, the Warleader''s acute problem-solving skills can also be very useful, as can the character''s foresight. Regardless of the situation, the Warleader can look at challenges from an angle others might have neglected. In doing so, the Warleader can help lead the group to victory through unexpected solutions.', NULL, '["LEAD","PERC","RANGLT","SURV"]'::jsonb, '{"rows":[{"index":0,"cost":5,"talents":["PRIMEPOS","SUPPRFIRE","GRIT","UNCANSENS"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["GRIT","CAREPLAN","SENSDANG","SWIFT"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":false},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["SUPPRFIRE","GRIT","UNCANSENS","PRESSHOT"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":false,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":false}]},{"index":3,"cost":20,"talents":["COORDASS","PRIMEPOS","BLINDSPOT","FOREWARN"],"directions":[{"right":true,"down":false,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":true,"down":true,"left":true,"up":false},{"right":false,"down":true,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["CLEVERSOLN","DEDI","FORCERAT","PROPAIM"],"directions":[{"right":true,"down":false,"left":false,"up":false},{"right":false,"down":false,"left":true,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;

-- ── ref_careers (respec) ───────────────────────────────────────────────
INSERT INTO ref_careers (key, name, description, career_skill_keys, specialization_keys, dataset_source, is_retired) VALUES ('THEACE', 'Ace', '[H4]Ace [h4]
An Ace''s eight career skills are [B]Astrogation, Cool, Gunnery, Mechanics, Perception, Piloting (Planetary), Piloting (Space),[b] and [B]Ranged (Light).[b] The Ace automatically gains a rank in four of these skills without spending experience, and receives a discount on increasing them with future experience points.

[H4]An Ace''s Role[h4]

Piloting vehicles, from repulsorlift speeders to massive starships and everything in between, is a fairly common skill for anyone who lives outside of a completely isolated, low-tech society. However, when it''s time to get somewhere fast or plunge into the thick of vehicular combat, Aces are the ones people want at the controls. 

[P]Just getting from one place to another is not enough for the Ace; this flier wants to get there faster, and to do so with style. He''d rather dive headlong into an asteroid field with half a dozen ships on his tail than safely move cargo down a well-traveled hyperspace lane. Aces are not the kind of people most transport companies want to hire to move their goods. They are, however, in very high demand when it comes to ship-to-ship combat of any kind, or when war machines need to be maneuvered into place during a planet-side battle. 

[P]The Ace isn''t just a master of piloting and driving, but often has a gift for using vehicular weapons to deadly effect. He understands that shooting is about more than merely looking through a scope and pulling a trigger—leading the target, compensating for the complexities of moving bodies in space, and aiming for vulnerable systems make the Ace a force to be reckoned with in any dogfight or speeder chase.', '["ASTRO","COOL","GUNN","MECH","PERC","PILOTPL","PILOTSP","RANGLT"]'::jsonb, '["BEASTRIDER","BEASTRIDER1.0","DRIVER","GROUNDSUPP1.0","GUNNER","GUNNER1.0","HOTSHOT","HOTSHOT1.0","PILOT","RIGGER","RIGGER1.0G","WINGMATE1.0"]'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_careers (key, name, description, career_skill_keys, specialization_keys, dataset_source, is_retired) VALUES ('BOUNT', 'Bounty Hunter', '[H4]Bounty Hunter[h4]
The Bounty Hunter''s eight career skills are [B]Athletics, Brawl, Perception, Piloting (Planetary), Piloting (Space), Ranged (Heavy), Streetwise,[b] and [B]Vigilance[b]. He automatically gains one rank in four of these skills (of his choosing) without spending experience, and he receives a discount when he spends experience to purchase ranks in any of these skills. 

[H4]A Bounty Hunter''s Role[h4]

The name says it all: this is a hunter who seeks to collect bounties for his work. Bounty Hunters tend to be feared, reviled, looked down upon—and in great demand throughout the galaxy. They are expert trackers, brutal combatants, and effective investigators. They tend to prefer skulduggery, stealth, and traps over frontal assaults, but the most respected Bounty Hunters will do whatever it takes to catch their quarries and collect their fees. 

[P]Bounty Hunters generally fall within three categories: Imperial Bounty Hunters, Guild Bounty Hunters, or Independents. Imperial Bounty Hunters are essentially on permanent contract to the Imperial Security Bureau (or a similar arm of Imperial law), and they never take assignments from corporations, smaller governments, or individuals. They are highly-trusted members of the extended law-enforcement community of the Empire, usually ex-military personnel that prefer a less-regimented (if possibly dangerous) way to serve. 
[P]Those Bounty Hunters who join a guild enjoy many excellent benefits: room and board wherever the guild has a presence, exceptional training and access to high-end equipment as needed for specific assignments, and a steady stream of jobs given to them by the guild brokers acting on their behalf. The downside to all of this is the fact that Guild Bounty Hunters have little-to-no say in what jobs they get, and failure to accept an assignment is grounds for immediate termination of a guild contract. 

[P]The greatest freedom comes with being an Independent Bounty Hunter; it also comes with the greatest challenges and dangers. Although Independents often take Imperial contracts, which are usually the most readily available and lucrative, they enjoy knowing they are not exactly a part of the Empire. Not being a part of a guild also serves an Independent Bounty Hunter''s sensibilities; he can pick and choose his contracts as he likes, and has only himself to credit for success or failure. 

[P]Player Characters are almost certainly going to be either Guild or Independent Hunters. However, regardless of what type of Bounty Hunter is played, the character will need to have a current and legitimate Imperial Peace-Keeping Certificate (IPKC). This is the specific license that all Bounty Hunters are required to have on file with the Empire in order to operate as professionals. Without such documentation and status, a Bounty Hunter is little more than a kidnapper and, possibly, a murderer. Any character with the Bounty Hunter career automatically gains an IPKC—unless the player would prefer his character not start with one. Although this may seem like an odd choice, it could make for a particularly compelling story or character background.', '["ATHL","BRAWL","PERC","PILOTPL","PILOTSP","RANGHVY","SW","VIGIL"]'::jsonb, '["ASSAS","ASSASS1.3","GADG","GADGET1.4","MARTIALARTIST","MARTARTI1.3","OPERATOR","OPERATOR1.2","SKIPTRACER","SKIPTRAC1.3","SURV","SURVIVALIST1.3"]'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_careers (key, name, description, career_skill_keys, specialization_keys, dataset_source, is_retired) VALUES ('COLO', 'Colonist', '[H4]Colonist[h4]
For the Colonist, the eight defining career skills are [B]Charm, Deception, Knowledge (Core Worlds), Knowledge (Education), Knowledge (Lore), Leadership, Negotiation,[b] and [B]Streetwise[b]. He automatically gains one rank in four of these skills (of his choosing) without spending experience, and he receives a discount when he spends experience to purchase ranks in any of these skills. 

[H4]A Colonist''s Role[h4]

In a way, Colonists are the most out-of-place people in the Outer Rim. They are most often from the Core Worlds, where they were well educated and part of the cultural and professional elite. A Colonist doesn''t tend to have the training to survive in areas of high conflict, and he isn''t particularly adept at physical exploits. 

[P]What he does possess, however, is a keen grasp of the bigger picture, and he usually has both the knowledge to understand problems and the capacity to get them solved. He probably came to the Outer Rim to create opportunities for himself, or to find a better life than what he left behind. If he cannot find that better life, he''ll apply all of his knowledge to the task of creating it, and he''ll use his considerable social skills to gather like-minded allies to his cause. 

[P]Of course, not all Colonists are necessarily altruistic in their pursuits. If knowledge is power, and power corrupts, then it follows that the Colonist is well-suited to take what he knows and exploit it for personal wealth. With charisma and street smarts, a Colonist might gather quite a team of specialists together to both watch his back and see to it that his enemies are brought to heel as he solidifies his power base. Countless Outer Rim worlds have become the personal fiefs of Colonists with bold ideas and willing followers.

[P]Of course, some Colonists fail in their pursuits, and run afoul of the law or their fellows. These Colonists are forced to flee their lives of luxury and survive wherever they can. Some of these individuals may fall in with less reputable, even criminal, individuals. Luckily, these unfortunate Colonists sometimes find their unique skill sets are in high demand. 

[P]The clever Colonists—the ones most likely to survive their first few months in the Outer Rim—figure out how to parlay their knowledge and talents into currency and contacts. Providing excellent advice, medical aid, or valuable knowledge can easily endear a Colonist to a warlord or gang leader, giving him the very thing he needs most: security. From a position of relative safety, a wise Colonist will begin gathering connections and data, building up a network that he can one day exploit for his aims, whatever they may be. 

[P]Colonists are the consummate leaders, negotiators, inspirational speakers, and strategists. A Colonist can take any small group of capable operators and turn them into a true force to be reckoned with. A capable Colonist in a group can mean the difference between just getting by and doing something truly spectacular in the galaxy.', '["CHARM","CORE","DECEP","EDU","LEAD","LORE","NEG","SW"]'::jsonb, '["DOCTOR","DOCRES12","DOCRESPEC","ENTREPRENEUR","ENTREPRE1.2","MARSHAL","MARSHAL1.21","PERFORMER","PERFRES13","PERFROMERRESPEC","POLITICO","POLITICO1.2","SCHOLAR","SCHOLAR1.21"]'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_careers (key, name, description, career_skill_keys, specialization_keys, dataset_source, is_retired) VALUES ('COMMANDER', 'Commander', '[H4]Commander [h4]
A Commander''s eight career skills are [B]Coercion, Cool, Discipline, Knowledge (Warfare), Leadership, Perception, Ranged (Light),[b] and [B]Vigilance[b]. He automatically gains a rank in four of these skills without spending experience, and gains a discount on increasing them with future experience points. 

[H4]A Commander''s Role[h4]

Individual warriors can act bravely and with resolute determination, accomplishing great things. They can also cause untold havoc without any real achievement, save property damage and loss of life, including their own. A motley mob of people capable of violence is only a threat until a more disciplined force arrives to put it down. 

[P]The role of a Commander is to organize, manage, and lead the fighters and other people who serve in a military force so they accomplish truly great things together. He must see the bigger picture, make the hard decisions, and motivate his people to charge into the jaws of death for a greater cause, all while never wasting personnel or resources. Without good Commanders, true victory is impossible for any military. 

[P]Whether on the bridge of a capital ship, flying in formation with a squad of starfighters, or standing on a hill shouting encouragement to his troops, the Commander is the true heart and soul of the Alliance military. In his hands lies the key to victory or defeat.', '["COERC","COOL","DISC","LEAD","PERC","RANGLT","VIGIL","WARF"]'::jsonb, '["COMMODORE","COMMODORERES","FIGUREHEAD","FIGUREHEADRES","INSTRUCTOR","INSTRUCTORRESPEC","SQUADLEADER","SQUADLEADERRES","STRATEGIST","STRATEGISTRES","TACTICIAN","TACTICIANRES"]'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_careers (key, name, description, career_skill_keys, specialization_keys, dataset_source, is_retired) VALUES ('CONSULAR', 'Consular', '[H4]Consular[h4]
The Consular''s six career skills are [B]Cool, Discipline, Knowledge (Education), Knowledge (Lore), Leadership,[b] and [B]Negotiation[b]. A Consular automatically gains a rank in three of these skills without spending experience, as well as a discount on increasing them with future experience points. [B]The Consular begins play with a Force rating of 1.[b]

[H4]A Consular''s Role[h4] 

The Consular focuses on the goal of achieving peace and harmony through positive discourse. Followers of this career try to avoid physical conflict whenever possible. Instead, they have faith in the Force to fuel basic compassion in all sentient beings. They believe that it is always more effective to have an intelligent discussion about a problem and then solve it through negotiations and other peaceful means than to engage in conflict to resolve it. They are opposed to needless violence but know that when confronting true evil, they must be willing to take decisive action. A Consular prides himself in knowing when to speak words of peace, and when the time for words is over. 

[P]Followers of this career are not Jedi Consulars of the now-fallen Republic. but they do embrace some of the same philosophies and practices. During the time of the Galactic Civil War. Consulars are a relatively rare breed. Imperial negotiations are most commonly handled through a position of vastly superior military might. Consequently. the Empire has little use for their peaceful approaches.

[P]In contrast, the Rebel Alliance has a far greater need for Consulars. As the various smaller Rebel groups come into contact with one another, they need negotiators capable of building a foundation for an alliance. Consulars have helped build the foundations for the fight for freedom, bringing groups of diverse backgrounds and needs together and joining them in common cause against injustice.

[P]Even as the Rebel Alliance becomes a well-established entity, the need for Consulars continue. Maintaining the Rebellion''s push against the Empire requires assistance from a broad range of different groups Consulars are capable of working with planetary governments—and even large corporations—to procure the equipment necessary to maintain and grow the Rebellion. They are also instrumental in persuading worlds to risk attempts at throwing off the shackles of the Empire. 

[P]Of course, not every Consular has necessarily played a role on the galactic stage. In fact, many help settle disputes closer to home, in small villages or planetary governments. Most Consulars see helping two feuding families find peace to be as rewarding as convincing an entire world to join the fight against the Empire. 

Beginning characters—particularly those who are cognizant of their Force abilities—are most likely to have learned their techniques from relatively obscure traditions. Alternatively, characters who do not recognize their abilities could be extremely competent negotiators, such as accomplished political, religious. and business leaders. Any of these Individuals might unwittingly tap into their Force abilities during the course of their work. This could provide the basis for a character who denies any knowledge of Force techniques while simultaneously depending on them.', '["COOL","DISC","EDU","LEAD","LORE","NEG"]'::jsonb, '["HEALER","NIMAN","SAGE"]'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_careers (key, name, description, career_skill_keys, specialization_keys, dataset_source, is_retired) VALUES ('DIPLOMAT', 'Diplomat', '[H4]Diplomat[h4]
A Diplomat''s eight career skills are [B]Charm, Deception, Knowledge (Core Worlds), Knowledge (Lore), Knowledge (Outer Rim), Knowledge (Xenology), Leadership,[b] and [B]Negotiation[b]. He automatically gains a rank in four of these skills without spending experience, and gains a discount on increasing them with future experience points. 

[H4]A Diplomat''s Role[h4]
 
The single most important resource in any war is people, and the Diplomat is the procurer of this resource, as well as the one who guides its use. Diplomats may not directly wage the war, but they ensure there is a chance for victory, and they are utterly indispensable for arranging and managing the peace to follow. 

[P]While many of the Rebellion''s heroes wage war with weapons, Diplomats are masters of employing words for strategic gain. If the stylus is stronger than the sword, then it is the Diplomat who must wield it with the skill and finesse necessary to achieve victory without spilling a drop of blood. Whether overseeing a treaty with a potential ally or arranging the terms for an enemy''s equitable surrender, a Diplomat''s battlefield is the negotiating table. 

[P]In the halls of the Senate, on the streets of a planet rife with political discord, or in a warehouse full of desperately needed medical supplies, the Diplomat struggles to gain the upper hand and achieve a favorable—and perhaps peaceful—outcome for his people. No matter his methods, the Diplomat''s success or failure has dramatic impact on a great many lives, and this drives him to passionately pursue his own form of victory at all costs.', '["CHARM","CORE","DECEP","LEAD","LORE","NEG","OUT","XEN"]'::jsonb, '["ADVOCATE","ADVOCATERES","AGITATOR","AGITATORRES","AMBASSADOR","AMBASSADORRES","ANALYST","PROPAGANDIST","PROPAGANDARES","QUARTERMASTER","QUARTERMASRES"]'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_careers (key, name, description, career_skill_keys, specialization_keys, dataset_source, is_retired) VALUES ('ENGINEER', 'Engineer', '[H4]Engineer[h4]
An Engineer''s eight career skills are [B]Athletics, Computers, Knowledge (Education), Mechanics, Perception, Piloting (Space), Ranged (Light),[b] and [B]Vigilance[b]. The Engineer automatically gains a rank in four of these skills without spending experience, and gains a discount on increasing them with future experience points. 

[H4]An Engineer''s Role[h4] 

There would be no Galactic Civil War if not for the massive technological capabilities of both the Empire and the Alliance. Machines of every size and weapons of every type are employed across great distances to hammer away at the enemy. These machines are imagined, designed, and built by Engineers, and Engineers are the ones who know how to keep them running—or to stop them cold. 

[P]Engineers speak the languages of computers, engines, and electrical conduits (they should, since they invented them). Most engineers prefer working with technology over people, especially in light of how chaotic the latter are. While some Engineers are fully (and eagerly) aware of the massive destruction their creations are capable of, most are merely fascinated with the challenge of creating something new, or fixing something thought beyond repair. Some focus their attentions on disrupting the machines of others, pitting their knowledge and talents against those of rivals working for the opposition. 

[P]Whether at the design table, in the hangar bay, or scurrying towards an access panel with explosives in hand, Engineers are a vital part of the Alliance''s war effort. They bring the Rebellion new weapons to fight with, keep its machines in service, and deliver devastating setbacks to the Empire''s continuing agenda to craft superweapons of mass destruction.', '["ATHL","COMP","EDU","MECH","PERC","PILOTSP","RANGLT","VIGIL"]'::jsonb, '["MAINTAINER","DROIDSPEC","DROSPEC","MECHANIC","SABOTEUR","SABOTEURRES","SAPPER","SAPPERRES","SCIENTIST","SCIRE10","SHIPWRIGHT","SHIPRE10"]'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_careers (key, name, description, career_skill_keys, specialization_keys, dataset_source, is_retired) VALUES ('EXPLORER', 'Explorer', '[H4]Explorer[h4]
The Explorer''s eight career skills are [B]Astrogation, Cool, Knowledge (Lore), Knowledge (Outer Rim), Knowledge (Xenology), Perception, Piloting (Space),[b] and [B]Survival[b]. He automatically gains one rank in four of these skills (of his choosing) without spending experience, and he receives a discount when he spends experience to purchase ranks in any of these skills. 

[H4]An Explorer''s Role[h4]

The Empire is vast, but it is a mere fraction of the galaxy, and the Explorer seeks to uncover the countless mysteries and opportunities the universe contains. Explorers are both vitally important and insidiously dangerous to the New Order; on the one hand, they reveal information, trade routes, and resources that are deeply coveted by the Empire, and on the other hand, they expand the ranges into which rebels, criminals, and iconoclasts can spread out and avoid Imperial might. 

[P]The Empire employs countless scouts and mercantile agents, and there are many more such entities working for the millions of galactic corporations seeking advantage over one another as they expand. The Explorer is a free agent; he makes his own way, tracks his own discoveries, and arranges his own special deals and connections. He will often sell the information he has at a decent price, or arrange to guide those who wish to go where he has been. 

[P]Other Explorers scour the HoloNet and other data services, looking for groups, businesses, or organizations in need. This is why the most well-traveled Explorers are in the greatest demand: they have maps and information about places only a fraction of a percent of the galaxy''s population might knows even exist. An Explorer with data about a planet a company wishes to exploit, or with a safe route to a part of the galaxy a group wishes to use for covert operations, can demand top prices. 

[P]Any Explorer relatively new to the trade finds himself in the classic conundrum—he needs experience in order to attain the choicest contracts, yet he cannot gain that experience because he cannot get hired. As such, many Explorers will take on any opportunity to travel and work in the Outer Rim, gathering what knowledge and leads they can in order to build up their contacts. resources, and their library of maps and routes. Most commonly, Explorers are able to parlay their astrogation and pilot skills into work opportunities.', '["ASTRO","COOL","LORE","OUT","PERC","PILOTSP","SURV","XEN"]'::jsonb, '["ARCHEOLOGIST","ARCHEOLORES","BGMHUNTER","BIGGAMEHRES","DRIVER","DRIVERRES","FRINGER","FRINGERRES","SCOUT","SCOUTRES","TRADER","TRADERRES"]'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_careers (key, name, description, career_skill_keys, specialization_keys, dataset_source, is_retired) VALUES ('GUARD', 'Guardian', '[H4]Guardian[h4]
The Guardian''s six career skills are [B]Brawl, Cool, Discipline, Melee, Resilience,[b] and [B]Vigilance[b]. A character who chooses this career automatically ''gains a rank in three of these skills without spending experience and gains a discount on increasing them with future experience points. [B]The Guardian begins with a Force rating of 1.[b]

[H4]A Guardian''s Role[h4] 

Adherents of the Guardian career are driven by a strong sense of responsibility and compassion. They recognize their affinity for the Force gives them the power—and responsibility—to help the helpless and aid the oppressed. Guardians tend to be blunt and forthright, using their prodigious combat prowess and natural leadership skills to directly intercede where they are needed most. 

[P]Most Guardians have a swagger about them, a cool confidence coupled with an air of nobility and authority. This poise is often well deserved. Guardians are capable of surviving and winning battles against overwhelming odds. Their martial training tends to focus almost exclusively on defense and resilience, leaving a Guardian as hard as granite. Hordes of opponents break upon a Guardian like waves upon shoreline rocks, leaving themselves exhausted and open to devastating counterattacks. 

[P]Alone, this combat prowess would be impressive, but a Guardian couples his abilities with his connection to the Force. This combination makes the Guardian far more than a mere thug, inspiring compassion and concern for those he protects. A Guardian''s defensive combat style matches this concern for life. Rather than make aggressive moves, he gives his opposition every chance to relent and choose a peaceful resolution. However, if they attack, the Guardian quickly demonstrates why their choice was the wrong one. 

[P]In many cases, a Guardian becomes established within a particular geographic region. This might be as large as a group of planets within a sector or as small as a neighborhood in a large city. A Guardian who focuses on a region in this way can choose to take stewardship of it. Notably, such stewardship comes out of a sense of responsibility and duty rather than any actual authority. Guardians seldom assume political power. Instead, they act in accordance with their internal moral compass, as guided by the Force, to ensure that everyone under their protection receives the justice they deserve. 
[P]Other Guardians follow the calling of the Force to travel and aid beings in need wherever they might find them. Many such Guardians wander in a seemingly aimless fashion, apparently letting random chance direct them where they might need to go. Almost invariably. their voyages soon lead them to people who desperately need help.', '["BRAWL","COOL","DISC","MELEE","RESIL","VIGIL"]'::jsonb, '["PEACE","PROTECT","SORESU"]'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_careers (key, name, description, career_skill_keys, specialization_keys, dataset_source, is_retired) VALUES ('HIREDGUN', 'Hired Gun', '[H4]Hired Gun[h4]
The Hired Gun''s eight career skills are [B]Athletics, Brawl, Discipline, Melee, Piloting (Planetary), Ranged (Light), Resilience,[b] and [B]Vigilance[b]. He automatically gains one rank in four of these skills (of his choosing) without spending experience, and he receives a discount when he spends experience to purchase ranks in any of these skills. 

[H4]A Hired Gun''s Role[h4]

When it comes to fighting, the Hired Gun is at the forefront. He''s less of an independent operator than the Bounty Hunter, preferring to have a defined mission, an objective to achieve, and some credits to spend when the job is done. Hired Guns are muscle and applied force, meant to defend or attack as the situation requires. They deal damage or protect others for credits, and this makes them simple and sometimes refreshingly direct. 

[P]A Hired Gun one typically encounters in the Outer Rim likely came from one of three kinds of backgrounds; he may have been a soldier for the Empire (or, possibly, even for the Old Republic before its fall), he might have served with a planetary or organizational force of some kind, or he simply came up hard, learning how to shoot and fight because that was the only way he could survive. However he came by them, the Hired Gun has the kinds of skills and talents that make it fairly easy to find work in the Outer Rim and the fringes of society.

[P]Many Hired Guns are true mercenaries, either working for themselves or contracted to a guild or company of some kind. Much like Bounty Hunters, the Hired Guns who are part of a guild tend to enjoy a great deal of support. They do not, however, have much in the way of freedom. More than a few Hired Guns have walked away from contracts that either violated their personal ethics or left them feeling completely exploited with terrible terms of service. Unfortunately, such mercenaries are left watching their backs for years after. 

[P]Independent Hired Guns enjoy the greatest freedom, yet they also spend a lot of time just trying to find a good job, and preferably one that doesn''t give them a life expectancy measured in days. Reputation can mean everything for such professionals, yet a simple test of skills and competency may often result in a better arrangement if the right employer is impressed.', '["ATHL","BRAWL","DISC","MELEE","PILOTPL","RANGLT","RESIL","VIGIL"]'::jsonb, '["BODYGUARD","BODYGUARDRES","DEMOLITIONIST","DEMOLITIONRES","ENFORCER","ENFORCERRES","HEAVY","HEAVYRES","MARAUDER","MARAUDERRES","MERCENARY","MERCSOLRES"]'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_careers (key, name, description, career_skill_keys, specialization_keys, dataset_source, is_retired) VALUES ('MYSTIC', 'Mystic', '[H4]Mystic[h4]
The Mystic''s six career skills are [B]Charm, Coercion, Knowledge (Lore), Knowledge (Outer Rim), Perception,[b] and [B]Vigilance[b]. A Mystic automatically gains a rank in three of these skills without spending experience and gains a discount on increasing them with future experience points. [B]A Mystic begins play with a Force rating of 1.[b]

[H4]A Mystic''s Role[h4]
 
Characters who follow the Mystic career are typically born to accept this mantle. From the time they first open their eyes, a strong connection to the Force colors their perception of the world surrounding them. They constantly perceive the ebb and flow of its energies between all living things. To many Mystics, the Force is as important a guide and mentor as their family and trusted friends. It teaches them to trust their instincts more than any training or instruction, for those instincts come from the Force.

[P]Because Mystics dwell so deeply in the Force, they often learn to master a broad range of Force powers. Training and practice can, of course, enhance their aptitude, but not all of them require a teacher. Rather, many Mystics simply intuit their powers through experience and their connection to the Force. Many Mystics accept this as the natural way of things. They strongly believe that the Force guides and provides for them as long as they remember to remain open and aware of its presence. 

[P]Many Mystics come from a culture where their connection to the Force has made them a person of importance. In some instances, they might have served as an advisor or even a magistrate. In other cases, their role could have been more religious or shamanic. They are likely to expect a certain degree of deference because of their previous experiences. This means many Mystics develop a powerful charisma and captivating presence. Some Mystics come by this naturally, able to convince others of what they have seen using soft words and persuasive arguments. Others work tirelessly to develop these personality traits, knowing that a compliment (or even a lie) in the right ear at the right time can quickly advance their goals.', '["CHARM","COERC","LORE","OUT","PERC","VIGIL"]'::jsonb, '["ADVISOR","ALCHEMIST","MAGUS","MAKASHI","PROPHET","SEER"]'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_careers (key, name, description, career_skill_keys, specialization_keys, dataset_source, is_retired) VALUES ('SEEKER', 'Seeker', '[H4]Seeker[h4]
The Seeker''s six career skills are [B]Knowledge (Xenology), Piloting (Planetary), Piloting (Space), Ranged (Heavy), Survival,[b] and [B]Vigilance[b]. Characters with this career automatically gain a rank in three of these skills without spending experience and gain a discount on increasing them with future experience points. [B]Seekers begin the game with a Force rating of 1.[b] 

[H4]A Seeker''s Role[h4] 

It is not uncommon for some Force adepts to feel compelled to travel throughout the galaxy to aid those in need and to oppose those who use the dark side. While some might focus their attentions in cities and urban centers, the need can be just as great far 
from the heart of galactic civilization. A Force adept who is willing and able to travel and work in these environments can help ease crushing poverty or crippling plagues of hunger and disease. He can also discover new Force techniques, find sensitives in need of training, and at times halt dangerous threats that could otherwise fester in isolation. A Seeker must be capable of doing all of these things, while traveling far from any meaningful support network. 
[P]Seekers generally take a very pragmatic view toward the Force. Operating independently, they consider it to be one of the tools in their arsenal, but not the only one. For a Seeker, preparedness and adaptability are paramount. They cannot count on finding the right tools for the job in the isolated areas in which they travel. As such, they learn to be flexible and adapt quickly to find the best equipment from what is available. In some environments, this may mean discovering information about flora and fauna that is previously undocumented. In such situations, the Force can be the most reliable asset, and its flexibility can aid them in selecting and using whatever else is at hand. 

[P]This flexibility is vital for a Seeker. Some of these characters travel at the direction of the Force, allowing fortune and chance to select their destinations and their traveling companions. Others work within the confines of larger groups. They may be troubleshooters. bounty hunters, envoys, or even traveling merchants. The variety of work means the Seeker must be prepared to quickly adapt to these changing situations and to make the most effective use possible of the tools that are at hand.', '["PILOTPL","PILOTSP","RANGHVY","SURV","VIGIL","XEN"]'::jsonb, '["ATARU","HUNTER","PATH"]'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_careers (key, name, description, career_skill_keys, specialization_keys, dataset_source, is_retired) VALUES ('SENTINEL', 'Sentinel', '[H4]Sentinel[h4]
The Sentinel''s six career skills are [B]Computers, Deception, Knowledge (Core Worlds), Perception, Skulduggery,[b] and [B]Stealth[b]. These characters automatically gain a rank in three of these skills without spending experience and gain a discount on increasing them with future experience points. [B]Sentinels begin the game with a Force rating of 1.[b]

[H4]A Sentinel''s Role[h4] 

Every city has its secrets, and every shining beacon of civilization has its seedy underworld. Within these shadowy depths, miscreants and malcontents prey on the helpless, committing heinous crimes and leaving misery and chaos in their wake. 

[P]Most law enforcement agencies try to combat criminals without violating the very laws the agencies exist to uphold. Thus, their agents must abide by strict regulations that restrain their behavior. Even institutions that exist to uphold evil laws, such as the Empire, have codes of conduct that apply to their enforcers. The Sentinel, however, plays by his own rules.

[P]During the time of the Old Republic, the Jedi Sentinels were Force adepts who blended combat expertise and training in the Force with a more pragmatic approach to their duties. Sentinels embraced practical technologies and utilized techniques borrowed from police forces, skip tracers, spies, and even law-breakers. Sentinels relied on quick thinking and cunning to accomplish their tasks, and they quickly found their calling in the owns of urban environments. tin the streets. Sentinels could fight criminals by using their own tactics against them. 

[P]Such an approach was not without risk. Even as Sentinels skirted the law to enforce justice, they skirted the dark side of their own morality as well. A Sentinel had to maintain constant vigilance over his own actions, analyzing each choice he made to ensure it was the right one. The best Sentinels avoided falling to the dark side by cultivating a fierce intellect and a brilliant cunning-to see all sides of a no-win situation and find the unexpected solution. 

[P]Although the Empire has long since wiped out the Jedi Order, and with it the Jedi Sentinels, some remain who follow these guiding principles. Many quick-witted Force-sensitives living in urban areas find themselves unconsciously adopting a Sentinel''s tactics as they unlock their own hidden potential. 

[P]Characters with a strong moral imperative may see these crusading skills as a means of Investigating powerful individuals. If they find powerful villains who are above the law, then employing less ethical approaches might be the only means to bring these rogues to justice. Under these circumstances, a Sentinel could readily justify deception and even minor crimes if they were undertaken to assure that a tyrant''s excesses could be curbed.', '["COMP","CORE","DECEP","PERC","SKUL","STEAL"]'::jsonb, '["ARTISAN","SHADOW","SHIEN"]'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_careers (key, name, description, career_skill_keys, specialization_keys, dataset_source, is_retired) VALUES ('SMUG', 'Smuggler', '[H4]Smuggler[h4]
Smugglers are a crafty, diverse bunch with core skills as follows: [B]Coordination, Deception, Knowledge (Underworld), Perception, Piloting (Space), Skulduggery, Streetwise,[b] and [B]Vigilance[b]. He automatically gains one rank in four of these skills (of his choosing) without spending experience, and he receives a discount when he spends experience to purchase ranks in any of these skills.

[H4]The Smuggler''s Role[h4]

Though they spend most of their lives struggling to avoid Imperial entanglements, keeping their ships flying, dodging blaster fire, and having enough to eat, Smugglers are often seen as the freest beings in the galaxy. They travel the hyperspace lanes, system to system, planet to planet, bringing what people want and need (and cannot get through legitimate means). 

[P]Unfortunately, that freedom is often an illusion; many Smugglers find themselves indebted to powerful people, having been forced to take a marker on their ships just to stay in business. Such markers inevitably lead Smugglers into a kind of indentured servitude unless they can figure a way out of it. That requires a very big ''score" of some kind—a job of such financial reward, the Smuggler can buy his ship back and afford to operate on his own again. 

[P]Few Smugglers survive that kind of job. Most just deal with their circumstances and keep their ships going. 

[P]Even with a marker on the ship, though, Smugglers tend to have a great deal of autonomy, and they develop a great many skills and talents that any group making their way through the Outer Rim will find helpful. Smugglers know their way around the underworld and fringe society, and they tend to know how to get things done, especially if legality isn''t an issue. 

[P]Smugglers are a vital part of Outer Rim society. With tariffs, quantity restrictions, and outright banning of even basic necessities being shipped to worlds not fully under Imperial Law, a great many people would be scratching out the poorest sort of existence, or perhaps dying outright due to lack of food and medicine. Smugglers'' ships are the lifelines that keep many distant population centers going. 

[P]Of course, the most profitable cargoes are the ones that will land someone in the Kessel spice mines if he''s caught with them.', '["COORD","DECEP","PERC","PILOTSP","SKUL","SW","UND","VIGIL"]'::jsonb, '["BLORUN","CHARMER","CHARRESP","GAMBLER","USERSPECIAL1","GUNSLINGER","GUNRE","PILOT","SCOUND","SCOUNRE","THIEF","THIEFRES"]'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_careers (key, name, description, career_skill_keys, specialization_keys, dataset_source, is_retired) VALUES ('SOLDIER', 'Soldier', '[H4]Soldier[h4]
A Soldier''s eight career skills are [B]Athletics, Brawl,  Knowledge (Warfare), Medicine, Melee, Ranged (Light), Ranged (Heavy),[b] and [B]Survival[b]. The Soldier automatically gains a rank in four of these skills without spending experience, and gains a discount on increasing them with future experience points. 

[H4]A Soldier''s Role[h4] 

Soldiers are the ones who take up arms and face death for a cause, for pay, or sometimes for lack of anything better to do. Fighting is what they know and what they do, and the ones who do it best survive long enough to pass on that knowledge to the green recruits who follow in their bloody footsteps. There is glory and honor to be found serving as a Soldier, yet there is also terror, pain, blood, and brutality. For a Soldier, a boring day is often one of his best days. 

[P]Administrators and politicians craft policy, commanders dictate how policy is to be implemented, and Soldiers are the tools of that implementation. Most care little for what the actual policy is: for them, the job is to take out the enemy and stay alive (not necessarily in that order). Some Soldiers are more invested in the causes they are fighting for, motivated by the knowledge that they fight for something worthy. 

[P]On the battlefront, behind enemy lines, and across the galaxy, the true heart and soul of the Rebellion is found in the Soldiers who serve beneath its banner. The causes they fight for are justice and freedom from tyranny. The cost of failure is almost certainly death, not only for themselves, but for everyone and everything they love.', '["ATHL","BRAWL","WARF","MELEE","MED","RANGLT","SURV","RANGHVY"]'::jsonb, '["COMMANDO","MEDIC","SHARPSHOOTER"]'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_careers (key, name, description, career_skill_keys, specialization_keys, dataset_source, is_retired) VALUES ('SPY', 'Spy', '[H4]Spy[h4]
A Spy''s eight career skills are [B]Computers, Cool, Coordination, Deception, Knowledge (Warfare), Perception, Skulduggery,[b] and [B]Stealth[b]. The Spy automatically gains a rank in four of these skills without spending experience, and gains a discount on increasing them with future experience points.

[H4]A Spy''s Role[h4]
 
Soldiers of a different type, Spies seek out the secrets of the enemy, undo the enemy''s plans, and hinder the enemy''s ability to do battle effectively. A single Spy, in the right place I at the right moment, can save (or destroy) many thousands of lives, with a single well-timed action. Most military forces (along with governments, criminal factions, and large corporations) place a great deal of emphasis on crafting an effective corps of espionage operatives.

[P]The primary role of any Spy is the gathering of intelligence—information about what is happening in the areas of operation, as well as what the enemy is doing—for those in command of Allied forces. There are many ways to do this, meaning there are many types of Spies with divergent specialties. Some focus on infiltrating the ranks of the enemy and gathering data from within, while others focus on external observations of troop and asset movements. Some take advantage of the dependency of modern military forces on electronic means of data collation, tapping into their opponents'' networks and siphoning off everything that can be snagged. 

[P]The Alliance''s reliance on Spies cannot be understated. Together with other specialist operatives, Spies are critical to the Rebellion''s chance for success. Their skills and talents play a crucial role in balancing the scales against the Empire''s overwhelming superiority in both forces and resources. As the war progresses, however, the Alliance can no longer treat its Spies as untouchable assets, never to be unduly risked; more and more, Spies are being called on to make direct strikes against the targets from which they are sent to gain information.', '["COMP","COOL","COORD","DECEP","PERC","SKUL","STEAL","WARF"]'::jsonb, '["COURIER","INFILTRATOR","INTERROGATOR","SCOUT","SLEEPERAGENT","SLICER"]'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_careers (key, name, description, career_skill_keys, specialization_keys, dataset_source, is_retired) VALUES ('TECHNICIAN', 'Technician', '[H4]Technician[h4]
Technicians are both knowledgeable and handy, and their skills show it: [B]Astrogation, Computers, Coordination, Discipline, Knowledge (Outer Rim), Mechanics, Perception,[b] and [B]Piloting (Planetary)[b]. He automatically gains one rank in four of these skills (of his choosing) without spending experience, and he receives a discount when he spends experience to purchase ranks in any of these skills. 

[H4]The Technician''s Role[h4]

Pretty much anything to do with technology or mechanical devices lies within the Technician''s purview. He knows how to operate, maintain, repair, and upgrade just about anything with power or gears. Most Technicians would rather deal with machines and droids than people; the latter are just too unpredictable. 
[P]Technicians can be found almost anywhere, at any tier of society or in any location where there''s even a few machines. Formality—even cleanliness—tends to fall far outside their daily concerns. They usually smell of some kind of grease, solvent, or other substance that''s used on machines, and even their cleanest clothes are seldom free from stains. Even those Technicians that move among the higher echelons come off as rumpled and slouching; it''s just not in their nature to put on a professional front. They let their work speak for itself. 

[P]Note that Technicians do have a sense of pride, and it resides in the work they perform. If a Technician brings someone a piece of tech that he''s not only repaired but upgraded with some very useful modifications, the reaction of the recipient can make or break his entire day. 

[P]This is why Technicians tend to gravitate to one another socially, or bond with someone who has an appreciation for machinery. Gadgeteer-oriented Bounty Hunters and Smugglers are most likely to befriend a Technician in a group. This can be a mutually beneficial relationship, considering all of the wonderful things a technically proficient individual can do for someone''s gear. 

[P]Like Pilots and Doctors, Technicians of almost any specialization will have a relatively easy time finding work in the Outer Rim. Every operation, from small farmsteads to large space stations, has need of those who can keep the tech running. Criminal overlords particularly enjoy having a Technician on their payroll, not only to take care of their many assets, but also to craft the occasional "toy" for them with which to surprise their enemies.', '["ASTRO","COMP","COORD","DISC","MECH","OUT","PERC","PILOTPL"]'::jsonb, '["CYBERTECH","CYBTECRES","DROIDTECH","DROTECRESP","MECHANIC","MECHANICRES","MODDER","MODDERES","OUTLAW","OUTLAWTECHRES","SLICER","SLICERRES"]'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_careers (key, name, description, career_skill_keys, specialization_keys, dataset_source, is_retired) VALUES ('WAR', 'Warrior', '[H4]Warrior[h4]
The Warriors six career skills are [B]Athletics, Brawl, Cool, Melee, Perception, and Survival[b]. Characters with this career automatically gain a rank in three of these skills without spending experience and gain a discount on increasing them with future experience points. [B]Warriors begin the game with a Force rating of 1.[b]

[H4]A Warrior''s Role[h4]
 
Though the lightsaber is an iconic weapon for many Force users. some dedicate themselves wholly to becoming paragons of strife. These dangerous individuals are known as Warriors.

[P]At their most basic, Warriors are focused combatants who use the Force to augment their prodigious martial prowess. Whether flying in the pilot''s seat of a starfighter, wielding a lightsaber on the field of battle, or blazing away with a blaster pistol. Warriors excel in combat of all types. 

[P]Legends indicate that the Jedi Order''s origins began with warriors who worked to integrate Force techniques into their physical training. Even in the absence of the Old Republic''s guardians, this association remains. The Force can give strength to those who need it, and Warriors excel at exploiting that strength. They become a physical manifestation of the Force, willing and ready to overcome those who would inflict harm. 

[P]The Warrior''s greatest strength, however, can also be his most dangerous weakness. Endless aggression can be a path toward the dark side. A wise individual must recognize that violence has its place but is not the only possible answer. A Warrior can inflict substantial and precise damage. However, even carefully applied attacks can still have far-reaching consequences. Because of this, it can be every bit as important for a Warrior to recognize when it is more appropriate not to attack. Some individuals who follow this career consider this sense of judgment to be the most important aspect of their training. 
[P]Warriors can come from a broad range of different cultures and environments. Physical conflict is every bit as common within the civilized and technologically advanced worlds of the Core as it Is within the less structured societies of the Outer Rim. Combat styles and the tools employed within conflicts may change. but the motivations and final outcomes are often similar. Ultimately, Warriors must be willing to risk their own lives so that they can overcome threats to themselves and to those they hold most dear.', '["ATHL","BRAWL","COOL","MELEE","PERC","SURV"]'::jsonb, '["AGGRES","COLOSSUS","JUYOBERSERKER","SHIICHO","STARACE","STEELHANDADEPT"]'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;

-- ── Mark OggDude PILOT and DRIVER specializations as retired ───────────
UPDATE ref_specializations
SET is_retired = true
WHERE dataset_source = 'oggdude'
  AND key IN ('PILOT', 'DRIVER');
